    const eurFmt = new Intl.NumberFormat('it-IT', { style: 'currency', currency: 'EUR', maximumFractionDigits: 0 });
    const eurFmt2 = new Intl.NumberFormat('it-IT', { style: 'currency', currency: 'EUR', minimumFractionDigits: 2, maximumFractionDigits: 2 });
    const numFmt = new Intl.NumberFormat('it-IT');

    // titolare dello studio: unico a vedere "Dati e backup" e a ricevere le allerte
    const PROPRIETARIO = 'a.missori@emvas.tax';
    // icone lineari (stroke = currentColor, si adattano al colore del contesto)
    const ICO_LUCCHETTO = '<svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="vertical-align:-2px;margin-right:5px;"><rect x="3" y="11" width="18" height="11" rx="2"/><path d="M7 11V7a5 5 0 0 1 10 0v4"/></svg>';
    const ICO_ALLERTA = '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="vertical-align:-3px;margin-right:7px;"><path d="M10.29 3.86 1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"/><line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg>';
    // icona "proposta" (documento con spunta): stato in attesa di conferma
    const ICO_PROPOSTA = '<svg viewBox="0 0 24 24" width="15" height="15" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="vertical-align:-2px;margin-right:7px;"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><path d="M14 2v6h6"/><path d="m9 15 2 2 4-4"/></svg>';
    // fatturazione predefinita in base al tipo di incarico
    function fatturazionePredefinita(tipo) {
        if (tipo === 'legale') return 'trimestrale';
        return 'annuale';
    }
    // descrizione leggibile della modalita di fatturazione (con finestra o data specifica)
    const MESI_BREVI_FATT = ['', 'gen', 'feb', 'mar', 'apr', 'mag', 'giu', 'lug', 'ago', 'set', 'ott', 'nov', 'dic'];
    function descriviFatturazione(inc) {
        const per = inc.fatturazione || 'annuale';
        const et = p => (p && p.mese) ? (MESI_BREVI_FATT[p.mese] + ' ' + p.anno) : '';
        if (per === 'specifica') return inc.fattData ? ('data specifica: ' + fmtData(inc.fattData)) : 'data specifica (da impostare)';
        const nome = per === 'mensile' ? 'Mensile' : (per === 'trimestrale' ? 'Trimestrale' : 'Annuale');
        const fin = [];
        if (inc.fattInizio) fin.push('da ' + et(inc.fattInizio));
        if (inc.fattFine) fin.push('a ' + et(inc.fattFine));
        return nome + (fin.length ? ' (' + fin.join(', ') + ')' : '');
    }

    /* Spese generali forfettarie (tecnologia, banche dati, software, segreteria):
       percentuale sugli onorari di ogni scadenza. Gli incarichi salvati prima che la
       scelta esistesse non hanno i campi e restano al 5%, come e sempre stato. */
    const SPESE_PERC_DEFAULT = 5;
    function spesePerc(inc) {
        if (!inc) return SPESE_PERC_DEFAULT;
        if (inc.speseGenerali === false) return 0;
        const p = Number(inc.speseGeneraliPerc);
        return isFinite(p) && p >= 0 ? p : SPESE_PERC_DEFAULT;
    }
    // spese generali su un importo, arrotondate al centesimo
    function speseSu(importo, inc) {
        return Math.round((Number(importo) || 0) * spesePerc(inc)) / 100;
    }
    // percentuale scritta all'italiana (5, 7,5) per etichette e lettera
    function percTesto(p) {
        return String(Math.round(p * 100) / 100).replace('.', ',');
    }

    /* Importi in euro con decimali (formato italiano): lettura robusta di quanto
       viene battuto a mano e formattazione per rimetterlo nel campo. */
    function parseEuro(s) {
        s = String(s == null ? '' : s).replace(/[^\d.,-]/g, '').trim();
        if (!s) return 0;
        if (s.indexOf(',') >= 0) {
            s = s.replace(/\./g, '').replace(',', '.');            // virgola = decimali, punto = migliaia
        } else if (s.indexOf('.') >= 0) {
            const parti = s.split('.');
            // piu punti (1.234.567) o ultimo gruppo di 3 cifre (1.234) = separatore di migliaia; altrimenti punto decimale (50.5, 50.00)
            if (parti.length > 2 || parti[parti.length - 1].length === 3) s = parti.join('');
        }
        return Math.round((Number(s) || 0) * 100) / 100;
    }
    function fmtEuroInput(n) {
        return n ? Number(n).toFixed(2).replace('.', ',') : '';
    }

    /* Stato "proposta": un incarico appena creato o rinnovato NON entra in fatturazione e
       compensi finche' non viene confermato. Per un rinnovo resta escluso SOLO il nuovo
       periodo (gli esercizi gia' confermati continuano a contare). */
    function inProposta(inc) {
        return !!inc && inc.stato === 'proposta';
    }
    // anni del periodo proposto (quello in attesa di conferma): esercizioPeriodo + durata del tipo
    function anniPeriodoProposto(inc) {
        const primo = Number(inc && inc.esercizioPeriodo);
        if (!primo) return null;                                  // periodo non indicato: si escludono tutti gli anni
        const durata = inc.tipo === 'legale' ? 3 : 1;
        const anni = [];
        for (let a = primo; a < primo + durata; a++) anni.push(a);
        return anni;
    }
    // true se, per via della proposta (o della sua mancata accettazione), l'anno
    // NON deve contare nei totali. Un incarico "non accettato" resta escluso come
    // una proposta: per un rinnovo contano solo gli esercizi gia' confermati.
    function propostaEscludeAnno(inc, anno) {
        if (!inProposta(inc) && !(inc && inc.stato === 'nonAccettato')) return false;
        const anni = anniPeriodoProposto(inc);
        return anni ? anni.includes(Number(anno)) : true;         // senza periodo: escludi tutto
    }
    // compenso che entra nei TOTALI (cruscotto, report, fatturazione): 0 se in proposta per quell'anno
    function compensoContabile(inc, anno) {
        return propostaEscludeAnno(inc, anno) ? 0 : Incarichi.compensoAnno(inc, anno);
    }

    function esc(s) {
        return String(s == null ? '' : s)
            .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
    }
    function uid() {
        return 'id-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 9);
    }
    function oggiISO() {
        const d = new Date();
        return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
    }
    /* Chiave di confronto di una regione: uguale per grafie diverse della STESSA regione
       (maiuscole, accenti, apostrofi dritti/curvi, trattino vs spazio). Cosi'
       "Trentino-Alto Adige", "Trentino Alto Adige" e "TRENTINO ALTO ADIGE" coincidono,
       e "Valle d'Aosta" con apostrofo dritto o curvo coincide. Usata per il filtro
       regione dei coordinatori e per raggruppare le regioni. */
    function chiaveRegione(r) {
        return String(r == null ? '' : r).trim().toLowerCase()
            .normalize('NFD').replace(/[̀-ͯ]/g, '')    // via gli accenti
            .replace(/['\'`]/g, '')                // via gli apostrofi (dritto e curvo)
            .replace(/[\s-]+/g, ' ');                            // trattini e spazi multipli -> spazio
    }
    function fmtData(iso) {
        if (!iso) return '';
        const [a, m, g] = iso.split('-');
        if (!a || !m || !g) return iso;
        return g + '/' + m + '/' + a;
    }
    function fmtDataOra(ts) {
        const d = new Date(ts);
        return String(d.getDate()).padStart(2, '0') + '/' + String(d.getMonth() + 1).padStart(2, '0') + '/' + d.getFullYear() +
            ' ' + String(d.getHours()).padStart(2, '0') + ':' + String(d.getMinutes()).padStart(2, '0');
    }
    /* Solo la data (senza ora) a partire da un timestamp. */
    function fmtGiorno(ts) {
        const d = new Date(ts);
        return String(d.getDate()).padStart(2, '0') + '/' + String(d.getMonth() + 1).padStart(2, '0') + '/' + d.getFullYear();
    }
    function parseImporto(str) {
        if (typeof str === 'number') return str;
        if (!str) return 0;
        const pulito = String(str).replace(/[.\s€]/g, '').replace(',', '.');
        const n = parseFloat(pulito);
        return isNaN(n) ? 0 : n;
    }
    function annoCorrente() { return new Date().getFullYear(); }

    /* ---------- SHA-256 (Web Crypto con fallback puro JS) ---------- */
    function sha256Js(ascii) {
        // Implementazione compatta di SHA-256 per contesti senza crypto.subtle
        function rr(v, c) { return (v >>> c) | (v << (32 - c)); }
        let maxWord = Math.pow(2, 32), result = '';
        const words = [], asciiBitLength = ascii.length * 8;
        let hash = sha256Js.h = sha256Js.h || [], k = sha256Js.k = sha256Js.k || [];
        let primeCounter = k.length;
        const isComposite = {};
        for (let candidate = 2; primeCounter < 64; candidate++) {
            if (!isComposite[candidate]) {
                for (let i = 0; i < 313; i += candidate) isComposite[i] = candidate;
                hash[primeCounter] = (Math.pow(candidate, 0.5) * maxWord) | 0;
                k[primeCounter++] = (Math.pow(candidate, 1 / 3) * maxWord) | 0;
            }
        }
        ascii += '\x80';
        while (ascii.length % 64 - 56) ascii += '\x00';
        for (let i = 0; i < ascii.length; i++) {
            const j = ascii.charCodeAt(i);
            if (j >> 8) return null;
            words[i >> 2] |= j << ((3 - i) % 4) * 8;
        }
        words[words.length] = ((asciiBitLength / maxWord) | 0);
        words[words.length] = (asciiBitLength);
        for (let j = 0; j < words.length;) {
            const w = words.slice(j, j += 16);
            const oldHash = hash.slice(0, 8);
            for (let i = 0; i < 64; i++) {
                const w15 = w[i - 15], w2 = w[i - 2];
                const a = hash[0], e = hash[4];
                const temp1 = hash[7]
                    + (rr(e, 6) ^ rr(e, 11) ^ rr(e, 25))
                    + ((e & hash[5]) ^ ((~e) & hash[6]))
                    + k[i]
                    + (w[i] = (i < 16) ? w[i] : (
                        w[i - 16]
                        + (rr(w15, 7) ^ rr(w15, 18) ^ (w15 >>> 3))
                        + w[i - 7]
                        + (rr(w2, 17) ^ rr(w2, 19) ^ (w2 >>> 10))
                    ) | 0);
                const temp2 = (rr(a, 2) ^ rr(a, 13) ^ rr(a, 22))
                    + ((a & hash[1]) ^ (a & hash[2]) ^ (hash[1] & hash[2]));
                hash = [(temp1 + temp2) | 0].concat(hash);
                hash[4] = (hash[4] + temp1) | 0;
            }
            for (let i = 0; i < 8; i++) hash[i] = (hash[i] + oldHash[i]) | 0;
        }
        for (let i = 0; i < 8; i++) {
            for (let j = 3; j + 1; j--) {
                const b = (hash[i] >> (j * 8)) & 255;
                result += ((b < 16) ? 0 : '') + b.toString(16);
            }
        }
        return result;
    }

    async function sha256(testo) {
        if (window.crypto && crypto.subtle) {
            try {
                const buf = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(testo));
                return Array.from(new Uint8Array(buf)).map(b => b.toString(16).padStart(2, '0')).join('');
            } catch (e) { /* fallback sotto */ }
        }
        // fallback: converte in "ascii-safe" tramite encodeURIComponent
        return sha256Js(unescape(encodeURIComponent(testo)));
    }

    function generaPasswordTemporanea() {
        const set = 'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghjkmnpqrstuvwxyz23456789';
        let p = '';
        const rand = new Uint32Array(10);
        if (window.crypto && crypto.getRandomValues) crypto.getRandomValues(rand);
        else for (let i = 0; i < 10; i++) rand[i] = Math.floor(Math.random() * 1e9);
        for (let i = 0; i < 10; i++) p += set[rand[i] % set.length];
        return p;
    }

    /* =========================================================
       ARCHIVIO (localStorage)
    ========================================================= */
    const CHIAVI = {
        utenti: 'rvArea.utenti',
        incarichi: 'rvArea.incarichi',
        persone: 'rvArea.persone',
        audit: 'rvArea.audit',
        fatture: 'rvArea.fattureStato',
        rimborsi: 'rvArea.rimborsiSpese',
        allerte: 'rvArea.allerte',
        comunicazioni: 'rvArea.comunicazioni',
        sondaggi: 'rvArea.sondaggi',
        sondaggiConfig: 'rvArea.sondaggiConfig',
        eventiConfig: 'rvArea.eventiConfig',       // chi e abilitato alla sezione Eventi
        eventiPresenze: 'rvArea.eventiPresenze',   // conferme/presenze e note (dati nostri)
        newsletter: 'rvArea.newsletter',           // le newsletter preparate (bozze e inviate)
        newsletterContatti: 'rvArea.newsletterContatti', // iscritti raccolti a mano (di persona)
        newsletterConfig: 'rvArea.newsletterConfig',     // chi e abilitato alla sezione Newsletter
        richieste: 'rvArea.richieste',             // richieste di correzione dati (con gli scambi di messaggi)
        rating: 'rvArea.rating',                   // verifiche del merito creditizio (rating bancario)
        controlliQualita: 'rvArea.controlliQualita', // schede dei controlli di qualita (una per incarico)
        ruoli: 'rvArea.ruoli',
        impostazioni: 'rvArea.impostazioni'
    };
    /* Sezioni su cui un ruolo puo' avere: 'no' (nascosta), 'lettura' (vede ma non tocca),
       'scrittura' (piena). "Utenti", "Ruoli" e "Dati e backup" non sono qui: restano
       riservate ad amministratore e titolare, non delegabili a un ruolo su misura. */
    const SEZIONI_RUOLO = [
        { id: 'dashboard', nome: 'Cruscotto' },
        { id: 'incarichi', nome: 'Incarichi' },
        { id: 'persone', nome: 'Aderenti Revilaw' },
        { id: 'fatturazione', nome: 'Fatturazione' },
        { id: 'report', nome: 'Report compensi' },
        { id: 'rating', nome: 'Verifica merito creditizio' },
        { id: 'controlloQualita', nome: 'Controlli qualità' },
        { id: 'comunicazioni', nome: 'Comunicazione teams di revisione' },
        { id: 'sondaggi', nome: 'Sondaggi' },
        { id: 'registro', nome: 'Registro modifiche' }
    ];
    const LIVELLI_SEZIONE = { no: 'Nascosta', lettura: 'Sola lettura', scrittura: 'Scrittura' };
    const sezioniTutte = liv => { const o = {}; SEZIONI_RUOLO.forEach(s => { o[s.id] = liv; }); return o; };
    /* Ruoli predefiniti: coincidono con i ruoli storici (admin/qualita/procuratore) cosi' gli
       utenti gia' presenti continuano a funzionare esattamente come prima (accesso pieno).
       "Coordinatore territoriale" e il suo vice sono ruoli di sistema: SEMPRE in sola
       visualizzazione, limitati agli incarichi delle regioni della loro scheda in Aderenti Revilaw
       (le regioni coordinate spuntate sulla scheda; la Regione della scheda e' la sede
       e da sola non assegna alcun territorio). */
    const RUOLO_MARKETING = 'marketing';
    const RUOLI_DEFAULT = [
        { id: 'admin', nome: 'Amministratore', builtin: true, sezioni: sezioniTutte('scrittura') },
        { id: 'qualita', nome: 'Responsabile qualità', builtin: true, sezioni: sezioniTutte('scrittura') },
        { id: 'procuratore', nome: 'Procuratore', builtin: true, sezioni: sezioniTutte('scrittura') },
        { id: 'coordinatore', nome: 'Coordinatore territoriale', builtin: true, sistema: true, sezioni: sezioniTutte('lettura') },
        { id: 'vicecoordinatore', nome: 'Vice coordinatore territoriale', builtin: true, sistema: true, sezioni: sezioniTutte('lettura') },
        /* Marketing: parte in sola lettura su tutte le sezioni consentite, ma non e'
           bloccato li': dalla sezione Ruoli e permessi l'amministratore puo' concedergli
           la scrittura, sezione per sezione, come per gli altri ruoli di sistema.
           Sulle richieste di correzione resta un osservatore: le vede TUTTE, come un
           equity partner, ma non le riceve, non le prende in carico e non risponde.
           Il territorio non lo limita: non e' un ruolo di zona. */
        { id: RUOLO_MARKETING, nome: 'Marketing', builtin: true, sistema: true, sezioni: sezioniTutte('lettura') }
    ];
    /* Ruoli "solo sondaggio": accesso isolato alla sola sezione Sondaggi, per gli invitati
       che NON fanno parte dello staff. compila = puo' compilare il questionario; risultati =
       vede solo il riepilogo. L'isolamento vero (niente accesso agli altri dati) e' garantito
       dalle regole Firestore (vedi FIREBASE-SETUP.md); qui l'app evita di richiedere gli
       archivi non consentiti e mostra solo la sezione Sondaggi. */
    const RUOLI_SOND = { compila: 'sondaggio_compila', risultati: 'sondaggio_risultati' };
    // etichette leggibili dei due ruoli "solo sondaggio": compaiono nella tendina ruoli
    // (sezione Utenti), cosi l'admin puo poi cambiare ruolo e abilitare le altre aree.
    const NOMI_RUOLO_SOND = {
        [RUOLI_SOND.compila]: 'Sondaggio (questionario)',
        [RUOLI_SOND.risultati]: 'Sondaggio (sola visualizzazione)'
    };
    function eRuoloSoloSondaggio(ruolo) { return ruolo === RUOLI_SOND.compila || ruolo === RUOLI_SOND.risultati; }

    const Store = {
        leggi(chiave, def) {
            try {
                const raw = localStorage.getItem(chiave);
                return raw ? JSON.parse(raw) : def;
            } catch (e) { return def; }
        },
        scrivi(chiave, valore) {
            localStorage.setItem(chiave, JSON.stringify(valore));
            // in modalita cloud i dati condivisi vengono replicati su Firestore
            if (typeof Cloud !== 'undefined' && Cloud.attivo) Cloud.sincronizza(chiave, valore);
        },
        seed() {
            if (!localStorage.getItem(CHIAVI.utenti)) {
                const utenti = RV_UTENTI_INIZIALI.map(u => ({
                    ...u, hash: null, sale: uid(), mustChange: false,
                    tentativi: 0, bloccatoFino: 0, attivo: true,
                    creato: Date.now(), creatoDa: 'sistema'
                }));
                Store.scrivi(CHIAVI.utenti, utenti);
            }
            if (!localStorage.getItem(CHIAVI.incarichi)) {
                const incarichi = RV_INCARICHI_DEMO.map(r => ({
                    id: uid(), stato: 'attivo', fatturazione: 'annuale', ...r,
                    creato: { da: 'sistema (dati demo)', il: Date.now() },
                    modificato: null
                }));
                Store.scrivi(CHIAVI.incarichi, incarichi);
                Audit.registra('sistema', 'Inizializzazione', 'sistema', null, null,
                    'Caricati ' + incarichi.length + ' incarichi dimostrativi');
            }
            Store.seedPersone();
            Ruoli.seed();
        },
        /* l'anagrafica del team serve anche in modalita cloud */
        seedPersone() {
            if (!localStorage.getItem(CHIAVI.persone)) {
                const mappa = {};
                RV_ROSTER.team.forEach(n => { mappa[n] = { team: true }; });
                RV_ROSTER.qualita.forEach(n => { mappa[n] = { ...(mappa[n] || {}), qualita: true, team: true }; });
                RV_ROSTER.respIncarico.forEach(n => { mappa[n] = { ...(mappa[n] || {}), respIncarico: true, team: true }; });
                const noti = (typeof RV_EMAIL_PERSONE !== 'undefined' && RV_EMAIL_PERSONE) || {};
                const persone = Object.keys(mappa).sort().map(n => ({
                    id: uid(), nome: n,
                    qualita: !!mappa[n].qualita, respIncarico: !!mappa[n].respIncarico,
                    team: true, attivo: true,
                    email: (noti[n] && noti[n].email) || '', nomeProprio: (noti[n] && noti[n].nomeProprio) || ''
                }));
                Store.scrivi(CHIAVI.persone, persone);
            }
        }
    };

    /* =========================================================
       RUOLI (permessi per sezione + filtro regione).
       L'amministratore li crea e li modifica; ogni utente ha un ruolo
       (il campo utente.ruolo) che punta qui per id.
    ========================================================= */
    const Ruoli = {
        tutti() {
            const l = Store.leggi(CHIAVI.ruoli, null);
            const lista = Array.isArray(l) && l.length ? l.slice() : RUOLI_DEFAULT.map(r => ({ ...r, sezioni: { ...r.sezioni } }));
            // i ruoli di sistema (coordinatore e vice) ci sono sempre, anche negli elenchi
            // salvati prima che esistessero, e i loro id sono riservati. Se un vecchio ruolo
            // personalizzato occupava per caso uno di quegli id (possibile con le versioni
            // precedenti), viene riportato al profilo di sistema: e' comunque quello che il
            // programma applica a chi ha quel ruolo, meglio che l'elenco dica la verita'.
            RUOLI_DEFAULT.filter(d => d.sistema).forEach(d => {
                const idx = lista.findIndex(r => r.id === d.id);
                if (idx < 0) { lista.push({ ...d, sezioni: { ...d.sezioni } }); return; }
                if (!lista[idx].sistema) { lista[idx] = { ...d, sezioni: { ...d.sezioni } }; return; }
                // ruolo di sistema personalizzato dall'admin: mantiene le sue scelte, ma le sezioni
                // aggiunte dopo il salvataggio del ruolo restano visibili in sola lettura di default.
                // Il NOME resta quello del programma (i ruoli di sistema non si rinominano): cosi
                // un'etichetta vecchia rimasta in archivio si aggiorna da sola.
                const sez = { ...(lista[idx].sezioni || {}) };
                SEZIONI_RUOLO.forEach(s => { if (sez[s.id] !== 'no' && sez[s.id] !== 'lettura' && sez[s.id] !== 'scrittura') sez[s.id] = 'lettura'; });
                lista[idx] = { ...lista[idx], nome: d.nome, sezioni: sez, sistema: true };
            });
            /* I ruoli storici ad accesso pieno (qualita, procuratore) ricevono in scrittura
               anche le sezioni nate DOPO il salvataggio del ruolo: sono i profili "accesso
               pieno", una sezione nuova non deve nascere nascosta proprio a loro. I ruoli
               su misura invece restano chiusi (la sezione nuova la apre l'amministratore). */
            RUOLI_DEFAULT.filter(d => d.builtin && !d.sistema).forEach(d => {
                const idx = lista.findIndex(r => r.id === d.id);
                if (idx < 0) return;
                const sez = { ...(lista[idx].sezioni || {}) };
                SEZIONI_RUOLO.forEach(s => { if (sez[s.id] !== 'no' && sez[s.id] !== 'lettura' && sez[s.id] !== 'scrittura') sez[s.id] = d.sezioni[s.id] || 'no'; });
                lista[idx] = { ...lista[idx], sezioni: sez };
            });
            return lista;
        },
        salva(lista) { Store.scrivi(CHIAVI.ruoli, lista); },
        trova(id) { return this.tutti().find(r => r.id === id) || null; },
        // il seed resta SOLO locale: i ruoli su Firestore li scrive l'amministratore (le regole
        // permettono la scrittura di archivio/ruoli al solo admin). In cloud arrivano dal server.
        seed() {
            if (!localStorage.getItem(CHIAVI.ruoli)) {
                try { localStorage.setItem(CHIAVI.ruoli, JSON.stringify(RUOLI_DEFAULT.map(r => ({ ...r, sezioni: { ...r.sezioni } })))); } catch (e) { }
            }
        },
        // normalizza un ruolo letto da fuori: garantisce le chiavi sezione
        normalizza(r) {
            const sez = {};
            SEZIONI_RUOLO.forEach(s => { const v = r && r.sezioni && r.sezioni[s.id]; sez[s.id] = (v === 'lettura' || v === 'scrittura') ? v : 'no'; });
            return { id: r.id, nome: r.nome || r.id, builtin: !!r.builtin, sistema: !!r.sistema, sezioni: sez };
        }
    };

    /* =========================================================
       ALLERTE (messaggi per sbloccare un calcolo congelato,
       visibili al titolare dello studio)
    ========================================================= */
    const Allerte = {
        tutte() { return Store.leggi(CHIAVI.allerte, []); },
        salva(l) { Store.scrivi(CHIAVI.allerte, l); },
        attive() { return this.tutte().filter(a => !a.letta); },
        aggiungi(a) {
            const lista = this.tutte();
            lista.unshift({ id: uid(), ts: Date.now(), letta: false, ...a });
            if (lista.length > 500) lista.length = 500;
            this.salva(lista);
        },
        segnaLetta(id) {
            const lista = this.tutte();
            const a = lista.find(x => x.id === id);
            if (a) { a.letta = true; this.salva(lista); }
        }
    };

    /* =========================================================
       COMUNICAZIONI (mail preparate: bozze condivise e inviate)
       Record: { id, oggetto, testo, destinatari:[email], stato:'bozza'|'inviata',
                 creato:{da,il}, inviata?:{da,il,n} }
    ========================================================= */
    const Comunicazioni = {
        tutte() { return Store.leggi(CHIAVI.comunicazioni, []); },
        salva(l) { Store.scrivi(CHIAVI.comunicazioni, l); },
        trova(id) { return this.tutte().find(c => c.id === id) || null; },
        salvaUna(c) {
            const lista = this.tutte();
            const i = lista.findIndex(x => x.id === c.id);
            if (i >= 0) {
                // Riconcilia con la versione piu fresca gia in archivio: se il server
                // (invio programmato) ha avanzato la schedulazione o registrato un invio
                // mentre la modale era aperta, non riportarlo indietro col valore del form.
                const cur = lista[i];
                const chiave = v => (v && v.il || 0) + '|' + (v && v.da || '') + '|' + (v && v.n || '');
                const visti = new Set(), uniti = [];
                [].concat(cur.invii || [], c.invii || []).forEach(v => { const k = chiave(v); if (!visti.has(k)) { visti.add(k); uniti.push(v); } });
                c.invii = uniti;
                // riconcilia solo se la versione in archivio e' ATTIVA (solo allora il server puo averla fatta
                // avanzare): se e' sospesa o disattivata non va mai riportata indietro sul valore del form,
                // altrimenti riprogrammandola a una data anticipata sparirebbe da tutte le sezioni.
                if (c.programmazione && cur.programmazione && cur.programmazione.attiva !== false && !cur.sospesa
                    && (cur.programmazione.prossimoInvio || 0) > (c.programmazione.prossimoInvio || 0)) {
                    c.programmazione = Object.assign({}, c.programmazione, {
                        prossimoInvio: cur.programmazione.prossimoInvio,
                        ultimoInvio: cur.programmazione.ultimoInvio,
                        attiva: cur.programmazione.attiva
                    });
                }
                if (cur.stato === 'inviata') { c.stato = 'inviata'; if (cur.inviata) c.inviata = cur.inviata; }
                lista[i] = c;
            } else lista.unshift(c);
            this.salva(lista);
        },
        elimina(id) { this.salva(this.tutte().filter(c => c.id !== id)); }
    };

    /* =========================================================
       RICHIESTE DI CORREZIONE DATI
       ------------------------------------------------------------
       Chi non puo' (o non deve) mettere le mani sui dati chiede la correzione
       da qui, invece che a voce: la richiesta resta scritta, e' indirizzata a
       un equity partner e porta con se' tutto lo scambio di messaggi che la
       riguarda, raggruppato in un'unica scheda.

       Record: { id, oggetto,
                 ambito: 'incarico' | 'funzione',
                 incaricoId, cliente, funzione,     // secondo l'ambito
                 regione,                           // decide coordinatore e vice in copia
                 richiedente: {email, nome}, destinatario: {email, nome},
                 conoscenza: [{email, nome, ruolo}],   // coordinatore e vice al momento dell'invio
                 stato: 'aperta' | 'presa' | 'risolta' | 'respinta',
                 creato, aggiornato,
                 messaggi: [{ id, ts, autore:{email,nome}, testo, tipo:'richiesta'|'messaggio'|'stato', stato }],
                 invii: [{ il, a:[email], esito:'ok'|'errore', msg }] }
    ========================================================= */
    const STATI_RICHIESTA = [
        { id: 'aperta', nome: 'Aperta', classe: 'ambra', aperta: true },
        { id: 'presa', nome: 'Presa in carico', classe: 'legale', aperta: true },
        { id: 'risolta', nome: 'Corretta', classe: 'verde' },
        { id: 'respinta', nome: 'Respinta', classe: 'neutro' }
    ];
    function statoRichiesta(id) { return STATI_RICHIESTA.find(s => s.id === id) || STATI_RICHIESTA[0]; }
    function badgeStatoRichiesta(id) { const s = statoRichiesta(id); return '<span class="badge ' + s.classe + '">' + esc(s.nome) + '</span>'; }

    const Richieste = {
        tutte() { return Store.leggi(CHIAVI.richieste, []); },
        salva(l) { Store.scrivi(CHIAVI.richieste, l); },
        trova(id) { return this.tutte().find(r => r.id === id) || null; },
        salvaUna(r) {
            const lista = this.tutte();
            const i = lista.findIndex(x => x.id === r.id);
            if (i >= 0) lista[i] = r; else lista.unshift(r);
            this.salva(lista);
        },
        /* Le richieste che l'utente collegato puo' vedere:
           - tutti gli equity partner e i founding partner (piu' admin e titolare) le vedono TUTTE;
           - gli altri vedono quelle che hanno scritto, quelle indirizzate a loro e quelle
             del territorio che coordinano (coordinatore e vice della regione della richiesta).
           Il territorio si legge dalla scheda in Aderenti Revilaw, non dal ruolo di accesso:
           chi coordina una regione resta in copia anche se entra con un altro ruolo. */
        visibili() {
            const tutte = this.tutte();
            if (Auth.vedeTutteLeRichieste()) return tutte;
            const em = String((Auth.utenteCorrente && Auth.utenteCorrente.email) || '').toLowerCase();
            const regioni = regioniCoordinateDaMe();
            return tutte.filter(r => {
                if (String((r.richiedente && r.richiedente.email) || '').toLowerCase() === em) return true;
                if (String((r.destinatario && r.destinatario.email) || '').toLowerCase() === em) return true;
                if ((r.conoscenza || []).some(c => String(c.email || '').toLowerCase() === em)) return true;
                return !!r.regione && regioni.includes(chiaveRegione(r.regione));
            });
        },
        ultimoMessaggio(r) {
            const m = (r && r.messaggi) || [];
            return m.length ? m[m.length - 1] : null;
        }
    };

    /* Le regioni che l'utente collegato coordina secondo la sua scheda in Aderenti Revilaw
       (coordinatore o vice), in chiave di confronto. Elenco vuoto se non ne coordina alcuna. */
    function regioniCoordinateDaMe() {
        const p = Auth.personaCorrente();
        if (!p || (!p.coordinatore && !p.viceCoordinatore)) return [];
        return Array.from(new Set(regioniCoperte(p).map(chiaveRegione).filter(Boolean)));
    }
    /* Coordinatore e vice di una regione: sono loro a restare in copia sulla richiesta. */
    function coordinatoriDiRegione(regione) {
        const k = chiaveRegione(regione || '');
        if (!k) return [];
        return Persone.tutte()
            .filter(p => p.attivo && !p.eliminato && p.email && (p.coordinatore || p.viceCoordinatore))
            .filter(p => regioniCoperte(p).some(r => chiaveRegione(r) === k))
            .map(p => ({
                email: String(p.email).toLowerCase(),
                nome: nomeCompletoPersona(p),
                ruolo: p.coordinatore ? 'Coordinatore territoriale' : 'Vice coordinatore territoriale'
            }));
    }
    /* Gli equity partner a cui si puo' indirizzare una richiesta (scheda attiva e con email:
       senza indirizzo non potrebbero ricevere il riepilogo). */
    function equityPartners() {
        return Persone.tutte()
            .filter(p => p.equityPartner && p.attivo && !p.eliminato && p.email)
            .map(p => ({ email: String(p.email).toLowerCase(), nome: nomeCompletoPersona(p) }))
            .sort((a, b) => a.nome.localeCompare(b.nome, 'it'));
    }
    function nomeCompletoPersona(p) {
        if (!p) return '';
        return (p.nomeProprio ? p.nomeProprio + ' ' : '') + (p.nome || '');
    }

    /* L'ultima parola detta su una richiesta: la segnalazione iniziale o una risposta.
       I passaggi di stato restano nel filo ma non sono conversazione: prendere in
       carico non e' rispondere. */
    function ultimaParolaRichiesta(r) {
        const m = (r && r.messaggi) || [];
        for (let i = m.length - 1; i >= 0; i--) if (m[i].tipo !== 'stato') return m[i];
        return null;
    }
    /* Il pallino "in attesa di risposta": la richiesta e' ancora aperta, mi riguarda in
       prima persona (l'ho scritta io oppure e' indirizzata a me) e l'ultima parola non
       e' la mia. Si spegne quando rispondo e si riaccende quando risponde l'altro.
       E' calcolato dai messaggi condivisi, non da uno stato "letto/non letto" salvato
       nel browser: cosi' dice la stessa cosa su ogni dispositivo. */
    function richiestaAttendeRisposta(r) {
        if (!r || !statoRichiesta(r.stato).aperta) return false;
        const em = String((Auth.utenteCorrente && Auth.utenteCorrente.email) || '').toLowerCase();
        if (!em) return false;
        const scrittaDaMe = String((r.richiedente && r.richiedente.email) || '').toLowerCase() === em;
        const perMe = String((r.destinatario && r.destinatario.email) || '').toLowerCase() === em;
        if (!scrittaDaMe && !perMe) return false;
        const ult = ultimaParolaRichiesta(r);
        return !!ult && String((ult.autore && ult.autore.email) || '').toLowerCase() !== em;
    }
    /* Quante richieste aspettano una mia risposta: e' il numero sul menu di sinistra. */
    function richiesteDaRispondere() {
        if (!Auth.utenteCorrente || !Auth.puoVedere('richieste')) return 0;
        return Richieste.visibili().filter(richiestaAttendeRisposta).length;
    }

    /* =========================================================
       PERSONE (anagrafica modificabile del team)
    ========================================================= */
    /* separatore unico per gli elenchi di nominativi: virgola, punto e
       virgola, o trattino con almeno uno spazio adiacente (cosi i
       cognomi composti tipo "Rossi-Bianchi" restano interi) */
    function dividiNomi(testo) {
        return String(testo || '')
            .split(/[,;]|\s+-\s*|\s*-\s+/)
            .map(t => t.trim())
            .filter(Boolean);
    }

    /* ---- Variabili di personalizzazione delle comunicazioni ----
       Nel testo/oggetto si possono usare {nome} {cognome} {nome_completo}
       {incarichi}; vengono sostituite per ogni destinatario. {incarichi} nel
       testo HTML diventa una tabella (cliente, resp. qualita, resp. incarico). */
    const VARIABILI_MAIL = [
        { chiave: 'nome', desc: 'Nome della persona (o ragione sociale del cliente)' },
        { chiave: 'cognome', desc: 'Cognome della persona' },
        { chiave: 'nome_completo', desc: 'Nome e cognome (o ragione sociale)' },
        { chiave: 'incarichi', desc: 'Tabella degli incarichi della persona: cliente, resp. qualità e resp. incarico (aggiornata a ogni invio). Nel testo del messaggio diventa una tabella; nell\'oggetto resta l\'elenco dei clienti.' },
        { chiave: 'periodo', desc: 'Periodo di riferimento (es. "primo trimestre 2026"): solo per invii programmati ricorrenti, dipende dalla frequenza e dalla data di ogni invio' }
    ];
    // {periodo} e una variabile "di invio" (uguale per tutti i destinatari), calcolata
    // dalla frequenza + data; sostituita a parte, non da applicaVariabili.
    function sostituisciPeriodo(s, periodo) { return String(s == null ? '' : s).replace(/\{periodo\}/g, periodo || ''); }
    const RE_VARIABILI = /\{(nome_completo|nome|cognome|email|incarichi)\}/;
    function haVariabili(s) { return RE_VARIABILI.test(String(s || '')); }
    function applicaVariabili(s, d) {
        d = d || {};
        const nc = (d.nome && d.cognome) ? (d.nome + ' ' + d.cognome) : (d.nome || d.cognome || '');
        // funzioni di sostituzione: il valore e' inserito LETTERALE (evita che un "$" nel testo
        // venga interpretato come riferimento speciale di String.replace)
        return String(s == null ? '' : s)
            .replace(/\{nome_completo\}/g, () => nc)
            .replace(/\{nome\}/g, () => d.nome || '')
            .replace(/\{cognome\}/g, () => d.cognome || '')
            .replace(/\{email\}/g, () => d.email || '')
            .replace(/\{incarichi\}/g, () => d.incarichi || '');
    }
    // come applicaVariabili ma per contenuto HTML: i valori vengono escaped, tranne {incarichi}
    // che e' gia' una TABELLA HTML pronta (incarichiHtml) e va inserita RAW.
    function applicaVariabiliHtml(s, d) {
        d = d || {};
        return applicaVariabili(s, { nome: esc(d.nome || ''), cognome: esc(d.cognome || ''), email: esc(d.email || ''), incarichi: (d.incarichiHtml != null ? d.incarichiHtml : esc(d.incarichi || '')) });
    }
    // gli incarichi (come oggetti {cliente, qualita, respIncarico}) in cui la PERSONA compare
    // come team, responsabile incarico o referente (NON come responsabile della qualita).
    // Risolve i nomi per etichetta, cosi due omonimi (stesso cognome) restano distinti.
    function incarichiObjDiPersona(persona, incarichi, risolvi) {
        if (!persona || typeof persona !== 'object') return [];
        const r = risolvi || risolutorePersone();
        const out = [], visti = {};
        (incarichi || []).forEach(inc => {
            const cita = [inc.team, inc.respIncarico, inc.referente].some(f =>
                f && dividiNomi(String(f)).some(t => { const x = r(t.trim()); return !!x && x.id === persona.id; }));
            if (cita && inc.cliente && !visti[inc.cliente]) { visti[inc.cliente] = 1; out.push({ cliente: inc.cliente, qualita: inc.qualita || '', respIncarico: inc.respIncarico || '' }); }
        });
        return out;
    }
    // tabella HTML (email-safe) degli incarichi della persona: cliente, resp. qualita, resp. incarico
    function tabellaIncarichiHtml(objs) {
        if (!objs || !objs.length) return ''; // niente incarichi: {incarichi} sparisce (coerente su tutti i canali)
        const th = 'border:1px solid #CBD5E1;padding:6px 9px;text-align:left;background:#F1F5F9;';
        const td = 'border:1px solid #CBD5E1;padding:6px 9px;';
        return '<table style="border-collapse:collapse;margin:10px 0;font-size:13px;"><tr>'
            + '<th style="' + th + '">Incarico</th><th style="' + th + '">Resp. qualità</th><th style="' + th + '">Resp. incarico</th></tr>'
            + objs.map(o => '<tr><td style="' + td + '">' + esc(o.cliente) + '</td><td style="' + td + '">' + esc(o.qualita || '-') + '</td><td style="' + td + '">' + esc(o.respIncarico || '-') + '</td></tr>').join('')
            + '</table>';
    }
    // per una lista di email, costruisce i dati di personalizzazione di ciascun destinatario
    function datiDestinatari(emails) {
        const persone = (typeof Persone !== 'undefined') ? Persone.tutte() : [];
        const incarichi = (typeof Incarichi !== 'undefined') ? Incarichi.tutti() : [];
        const risolvi = risolutorePersone(persone);
        const perEmail = {}, cliEmail = {};
        persone.forEach(p => { if (p.email) perEmail[String(p.email).toLowerCase()] = p; });
        incarichi.forEach(i => { [i.email1, i.email2].forEach(e => { if (e) { const k = String(e).toLowerCase(); if (!cliEmail[k]) cliEmail[k] = i.cliente; } }); });
        return (emails || []).map(email => {
            const k = String(email || '').toLowerCase();
            const p = perEmail[k];
            if (p) { const cognome = p.nome || ''; const objs = incarichiObjDiPersona(p, incarichi, risolvi); return { email: k, nome: p.nomeProprio || cognome, cognome: cognome, incarichi: objs.map(o => o.cliente).join(', '), incarichiHtml: tabellaIncarichiHtml(objs) }; }
            if (cliEmail[k]) return { email: k, nome: cliEmail[k], cognome: '', incarichi: '', incarichiHtml: '' };
            return { email: k, nome: '', cognome: '', incarichi: '', incarichiHtml: '' };
        });
    }

    /* =========================================================
       FUSIONE A 3 VIE (sincronizzazione concorrente)
       ---------------------------------------------------------
       Ogni elenco condiviso e salvato come un unico documento: senza
       accortezze, il salvataggio di un utente sovrascriverebbe l'intera
       lista cancellando le modifiche fatte nel frattempo da un altro.
       Qui si calcolano le MIE differenze (base -> mio locale) e si
       applicano SOPRA lo stato remoto attuale, per record: per id negli
       array (incarichi, persone, allerte), per chiave negli oggetti
       (stati fatture), in append-only per l'audit. Cosi modifiche a
       record diversi non si perdono; sullo stesso record vince l'ultimo.
       Le funzioni sono pure e collaudate a parte.
    ========================================================= */
    function _formaDati(chiave) {
        if (chiave === CHIAVI.fatture) return 'oggetto';
        if (chiave === CHIAVI.audit) return 'audit';
        // Configurazioni: UN oggetto con chiavi, non un elenco di record. Senza questa
        // riga la fusione le trattava come elenco e andava in errore, cosi la modifica
        // restava solo in locale e non arrivava mai agli altri utenti.
        if (_eArchivioConfig(chiave)) return 'oggetto';
        return 'array';
    }
    /* Archivi di CONFIGURAZIONE (impostazioni, non elenchi di record). Vanno trattati a
       parte: si fondono per chiave e non si ripubblicano mai da una copia locale. */
    function _eArchivioConfig(chiave) {
        return chiave === CHIAVI.sondaggiConfig || chiave === CHIAVI.eventiConfig
            || chiave === CHIAVI.newsletterConfig;
    }
    /* Archivi che NON vanno mai ricreati sul server partendo dalla copia di un browser:
       il bootstrap usa una scrittura piena, senza fusione per record, quindi la copia di
       chi entra per ultimo diventerebbe l'intero contenuto condiviso. Vale per le
       configurazioni e per le presenze agli eventi, che ognuno modifica per conto suo.
       Questi archivi nascono dal salvataggio vero e proprio, che invece fonde. */
    function _senzaBootstrap(chiave) {
        return _eArchivioConfig(chiave) || chiave === CHIAVI.eventiPresenze;
    }
    /* Nome leggibile di un archivio, per i messaggi all'utente (che non deve
       ritrovarsi davanti sigle come "fattureStato"). */
    const NOMI_ARCHIVIO = {
        incarichi: 'incarichi', persone: 'anagrafica persone', audit: 'registro attività',
        fattureStato: 'stato fatture', allerte: 'allerte', comunicazioni: 'comunicazioni',
        sondaggi: 'risposte del questionario', sondaggiConfig: 'impostazioni del questionario',
        eventiConfig: 'accessi agli eventi', eventiPresenze: 'presenze agli eventi',
        newsletter: 'newsletter', newsletterContatti: 'contatti della newsletter',
        newsletterConfig: 'accessi alla newsletter',
        richieste: 'richieste di correzione dati',
        rating: 'verifiche di rating bancario',
        controlliQualita: 'controlli di qualità',
        ruoli: 'definizione dei ruoli'
    };
    function nomeArchivio(doc) {
        return Object.prototype.hasOwnProperty.call(NOMI_ARCHIVIO, doc) ? NOMI_ARCHIVIO[doc] : doc;
    }
    function _parseDati(str, forma) {
        try { const v = JSON.parse(str); return v == null ? (forma === 'oggetto' ? {} : []) : v; }
        catch (e) { return forma === 'oggetto' ? {} : []; }
    }
    function _deltaDati(baseStr, nuovoStr, forma) {
        const base = _parseDati(baseStr, forma), nuovo = _parseDati(nuovoStr, forma);
        if (forma === 'oggetto') {
            const upserts = {}, deletes = [];
            Object.keys(nuovo).forEach(k => { if (JSON.stringify(nuovo[k]) !== JSON.stringify(base[k])) upserts[k] = nuovo[k]; });
            Object.keys(base).forEach(k => { if (!(k in nuovo)) deletes.push(k); });
            return { upserts, deletes };
        }
        const baseById = {}; base.forEach(r => { if (r && r.id != null) baseById[r.id] = r; });
        const nuovoById = {}; nuovo.forEach(r => { if (r && r.id != null) nuovoById[r.id] = r; });
        const upserts = [], deletes = [];
        nuovo.forEach(r => { if (r && r.id != null && JSON.stringify(r) !== JSON.stringify(baseById[r.id])) upserts.push(r); });
        if (forma !== 'audit') Object.keys(baseById).forEach(id => { if (!(id in nuovoById)) deletes.push(id); });
        return { upserts, deletes };
    }
    function _applicaDelta(targetStr, delta, forma) {
        const target = _parseDati(targetStr, forma);
        if (forma === 'oggetto') {
            const out = Object.assign({}, target);
            Object.keys(delta.upserts).forEach(k => { out[k] = delta.upserts[k]; });
            delta.deletes.forEach(k => { delete out[k]; });
            return JSON.stringify(out);
        }
        const byId = {}, ordine = [];
        target.forEach(r => { if (r && r.id != null) { if (!(r.id in byId)) ordine.push(r.id); byId[r.id] = r; } });
        delta.upserts.forEach(r => { if (r && r.id != null) { if (!(r.id in byId)) ordine.push(r.id); byId[r.id] = r; } });
        delta.deletes.forEach(id => { delete byId[id]; });
        let out = ordine.filter(id => byId[id] !== undefined).map(id => byId[id]);
        if (forma === 'audit') { out.sort((a, b) => (b.ts || 0) - (a.ts || 0)); if (out.length > 2000) out = out.slice(0, 2000); }
        return JSON.stringify(out);
    }
    // fonde il mio valore locale con lo stato remoto attuale, partendo dalla base
    // (l'ultimo remoto che avevo visto). Ritorna la stringa JSON fusa.
    function _fondiDati(chiave, baseStr, localStr, remoteStr) {
        if (baseStr == null || remoteStr == null) return localStr;
        if (baseStr === remoteStr) return localStr;   // nessuna modifica altrui
        if (localStr === baseStr) return remoteStr;   // io non ho cambiato nulla
        return _applicaDelta(remoteStr, _deltaDati(baseStr, localStr, _formaDati(chiave)), _formaDati(chiave));
    }

    /* Etichetta con cui una persona viene citata negli incarichi e mostrata nelle tendine:
       di norma il solo cognome. Il nome si aggiunge ("Cognome Nome") solo quando un'ALTRA
       persona ATTIVA condivide lo stesso cognome, cosi due omonimi attivi restano distinguibili
       nelle scelte, nei conteggi e nelle lettere. */
    function etichettaPersona(p, lista) {
        const cog = String(p && p.nome || '').trim();
        if (!cog) return '';
        const np = String(p.nomeProprio || '').trim();
        if (!np) return cog;
        const condiviso = (lista || Persone.tutte()).some(x => x && x.id !== p.id && x.attivo && !x.eliminato
            && String(x.nome || '').trim().toLowerCase() === cog.toLowerCase());
        return condiviso ? (cog + ' ' + np) : cog;
    }
    /* Persona a cui si riferisce un'etichetta salvata in un incarico. Riconosce sia la forma
       corrente (etichettaPersona) sia "Cognome Nome" esplicito; per i dati storici (solo
       cognome) risale alla persona piu vecchia con quel cognome (ordine di inserimento). */
    /* Costruisce un risolutore etichetta->persona con lookup O(1). Le persone NON eliminate
       vengono inserite per prime, cosi con la stessa etichetta vincono loro (un'eliminata
       omonima non "adombra" quella attiva). Va costruito una volta per render e passato ai
       conteggi, per non pagare il costo quadratico su liste grandi. */
    function risolutorePersone(lista) {
        lista = lista || Persone.tutte();
        const perEt = new Map(), perPieno = new Map(), perCog = new Map();
        // ordine di priorita: prima le attive (possiedono il cognome nudo), poi le disattivate,
        // infine le eliminate; cosi un cognome nudo si risolve alla persona attiva.
        lista.filter(p => p.attivo && !p.eliminato).concat(lista.filter(p => !p.attivo && !p.eliminato)).concat(lista.filter(p => p.eliminato)).forEach(p => {
            const et = etichettaPersona(p, lista).toLowerCase();
            if (et && !perEt.has(et)) perEt.set(et, p);
            const np = String(p.nomeProprio || '').trim();
            if (np) { const f = (String(p.nome || '').trim() + ' ' + np).toLowerCase(); if (!perPieno.has(f)) perPieno.set(f, p); }
            const cg = String(p.nome || '').trim().toLowerCase();
            if (cg && !perCog.has(cg)) perCog.set(cg, p);
        });
        return str => { const s = String(str || '').trim().toLowerCase(); return s ? (perEt.get(s) || perPieno.get(s) || perCog.get(s) || null) : null; };
    }
    function personaDaEtichetta(str, lista) {
        return risolutorePersone(lista)(str);
    }

    const Persone = {
        tutte() { return Store.leggi(CHIAVI.persone, []); },
        salva(l) { Store.scrivi(CHIAVI.persone, l); },
        /* nomi attivi per un ruolo: 'qualita' | 'respIncarico' | 'team' (esclusi eliminati) */
        attive(ruolo) {
            return this.tutte()
                .filter(p => p.attivo && !p.eliminato && (!ruolo || p[ruolo]))
                .map(p => p.nome)
                .sort((a, b) => a.localeCompare(b));
        },
        /* come attive(), ma restituisce l'etichetta (cognome, o "Cognome Nome" per gli
           omonimi): e' il valore che le tendine mostrano e salvano negli incarichi. */
        attiveEtichette(ruolo) {
            const lista = this.tutte();
            return lista.filter(p => p.attivo && !p.eliminato && (!ruolo || p[ruolo]))
                .map(p => etichettaPersona(p, lista))
                .sort((a, b) => a.localeCompare(b));
        },
        trovaPerNome(nome) {
            const n = String(nome || '').trim().toLowerCase();
            return this.tutte().find(p => p.nome.toLowerCase() === n) || null;
        },
        // nome completo "Nome Cognome" se il nome proprio e registrato; altrimenti
        // (dati non ancora migrati) il vecchio nomeCompleto; altrimenti il solo cognome
        nomeCompleto(etichetta) {
            const p = personaDaEtichetta(etichetta);
            if (!p) return etichetta || '';
            if (p.nomeProprio) {
                // evita "Rossi Mario Rossi" se il nome proprio contenesse gia il cognome
                return p.nomeProprio.toLowerCase().endsWith(String(p.nome || '').toLowerCase())
                    ? p.nomeProprio : (p.nomeProprio + ' ' + p.nome).trim();
            }
            if (p.nomeCompleto) return p.nomeCompleto;
            return etichetta || '';
        },
        // migrazione una tantum: dai vecchi record con "nomeCompleto" ai nuovi
        // campi (cognome = nome; nomeProprio = nomeCompleto senza il cognome finale).
        // Idempotente: dopo la prima esecuzione non trova piu nulla da migrare.
        /* Indirizzi (e nomi propri) noti di alcune persone dello studio, da
           dati-demo.js (RV_EMAIL_PERSONE): le schede che ne sono ancora prive li
           ricevono all'apertura dell'area. Servono alle email automatiche dei
           Controlli qualita (es. la richiesta di sospensione del compenso al
           responsabile incarico). Idempotente: non tocca chi ha gia' un valore. */
        migraEmailNote() {
            const noti = (typeof RV_EMAIL_PERSONE !== 'undefined' && RV_EMAIL_PERSONE) || {};
            const cognomi = Object.keys(noti);
            if (!cognomi.length) return;
            const lista = this.tutte();
            let cambiato = false;
            cognomi.forEach(cog => {
                const p = lista.find(x => x && !x.eliminato && String(x.nome || '').trim().toLowerCase() === cog.toLowerCase());
                if (!p) return;
                if (noti[cog].email && !p.email) { p.email = noti[cog].email; cambiato = true; }
                if (noti[cog].nomeProprio && !p.nomeProprio) { p.nomeProprio = noti[cog].nomeProprio; cambiato = true; }
            });
            if (cambiato) this.salva(lista);
        },
        migraNomi() {
            const lista = this.tutte();
            let cambiato = false;
            lista.forEach(p => {
                if (p.nomeProprio === undefined) {
                    let np = '';
                    if (p.nomeCompleto) {
                        const nc = String(p.nomeCompleto).trim();
                        const cog = String(p.nome || '').trim();
                        np = (cog && nc.toLowerCase().endsWith(cog.toLowerCase()))
                            ? nc.slice(0, nc.length - cog.length).trim()
                            : nc;
                    }
                    p.nomeProprio = np;
                    cambiato = true;
                }
                if ('nomeCompleto' in p) { delete p.nomeCompleto; cambiato = true; }
            });
            if (cambiato) this.salva(lista);
        },
        /* Migrazione una tantum delle regioni coordinate.
           Prima la regola era implicita: "Regione della scheda + regioni spuntate". Ma il
           campo Regione e' un dato di RESIDENZA (nel modulo sta dentro l'indirizzo), e cosi'
           chi era coordinatore si ritrovava assegnato il territorio in cui abita senza che
           nessuno l'avesse scelto - comparendo tra i coordinatori di quella regione e
           vedendone gli incarichi. Ora contano solo le regioni spuntate.
           Per non togliere accessi di colpo, a ogni coordinatore/vice la Regione della
           scheda viene scritta TRA le regioni spuntate: il risultato di oggi non cambia,
           ma da qui in poi e' visibile sulla scheda e si puo' togliere.
           Il contrassegno per persona serve proprio a questo: senza, una regione tolta a
           mano verrebbe rimessa al caricamento successivo. */
        migraRegioniCoordinate() {
            const lista = this.tutte();
            let cambiato = false;
            lista.forEach(p => {
                if (p.regCoordMigrata) return;
                // si contrassegnano TUTTI, non solo i coordinatori di adesso: chi lo diventa
                // dopo la migrazione non deve ereditare la regione di residenza
                p.regCoordMigrata = true;
                cambiato = true;
                if (!p.coordinatore && !p.viceCoordinatore) return;
                const residenza = String(p.regione || '').trim();
                const gia = Array.isArray(p.regioniCoordinate) ? p.regioniCoordinate.filter(Boolean) : [];
                p.regioniCoordinate = gia;
                if (!residenza) return;
                if (gia.some(x => chiaveRegione(x) === chiaveRegione(residenza))) return;
                gia.push(residenza);
            });
            if (cambiato) this.salva(lista);
        },
        /* usato dall'import: aggiunge i nominativi mancanti con i ruoli
           rilevati e riporta i campi degli incarichi alla grafia canonica
           dell'anagrafica (evita doppioni tipo "MISSORI" / "Missori") */
        integraDaIncarichi(incarichi) {
            const lista = this.tutte();
            const indice = {};
            lista.forEach(p => { indice[p.nome.toLowerCase()] = p; });
            let aggiunte = 0;
            const registra = (nome, ruolo) => {
                const pulito = String(nome || '').trim();
                if (!pulito || pulito.length < 2 || /^#?n\s*[.\/]?\s*d\.?$/i.test(pulito)) return null;
                const chiave = pulito.toLowerCase();
                if (indice[chiave]) {
                    if (!indice[chiave][ruolo]) indice[chiave][ruolo] = true;
                    return indice[chiave].nome;
                }
                const nuova = { id: uid(), nome: pulito, qualita: false, respIncarico: false, team: true, attivo: true };
                nuova[ruolo] = true;
                indice[chiave] = nuova;
                lista.push(nuova);
                aggiunte++;
                return nuova.nome;
            };
            incarichi.forEach(i => {
                const q = registra(i.qualita, 'qualita');
                if (q) i.qualita = q;
                const r = registra(i.respIncarico, 'respIncarico');
                if (r) i.respIncarico = r;
                // il referente puo contenere piu nominativi
                const refs = dividiNomi(i.referente).map(t => registra(t, 'team') || t);
                if (refs.length) i.referente = refs.join(', ');
                const membri = dividiNomi(i.team).map(t => registra(t, 'team') || t);
                if (membri.length) i.team = membri.join(', ');
            });
            this.salva(lista);
            return aggiunte;
        }
    };

    /* Le regioni che una persona COORDINA: soltanto quelle scelte sulla sua scheda,
       senza doppioni e con la grafia originale.
       La "Regione" della scheda NON entra qui: e' un dato di residenza (nel modulo sta
       insieme a provincia, localita e indirizzo) e non dice nulla sul territorio coperto.
       Chi coordina la regione in cui abita ce l'ha tra le regioni spuntate, dove la
       migrazione l'ha scritta esplicitamente (vedi Persone.migraRegioniCoordinate).
       Regola unica: la usano il filtro dei permessi, l'etichetta nella barra laterale
       e la sezione Coordinatori e vice. */
    function regioniCoperte(p) {
        if (!p || !Array.isArray(p.regioniCoordinate)) return [];
        const viste = new Set(), out = [];
        p.regioniCoordinate.filter(Boolean).forEach(r => {
            const k = chiaveRegione(r);
            if (k && !viste.has(k)) { viste.add(k); out.push(String(r).trim()); }
        });
        return out;
    }

    /* =========================================================
       REGISTRO MODIFICHE (audit trail)
    ========================================================= */
    const Audit = {
        registra(utente, azione, entita, rif, cliente, dettagli) {
            const log = Store.leggi(CHIAVI.audit, []);
            log.unshift({
                id: uid(), ts: Date.now(),
                utente: typeof utente === 'object' ? (utente.nome + ' <' + utente.email + '>') : utente,
                azione, entita, rif: rif || null, cliente: cliente || null,
                dettagli: dettagli || null
            });
            if (log.length > 2000) log.length = 2000;
            Store.scrivi(CHIAVI.audit, log);
        },
        confronta(prima, dopo, campi) {
            const diff = [];
            // gli elenchi si mostrano leggibili ("Veneto, Lazio") e un elenco vuoto vale
            // come campo assente: cosi' aggiungere un campo-elenco nuovo non genera una
            // voce fantasma ("vuoto -> []") al primo risalvataggio dei record esistenti
            const testo = v => {
                if (v == null) return '';
                if (Array.isArray(v)) return v.length ? v.join(', ') : '';
                return typeof v === 'object' ? JSON.stringify(v) : String(v);
            };
            campi.forEach(c => {
                const sa = testo(prima ? prima[c.chiave] : undefined);
                const sb = testo(dopo ? dopo[c.chiave] : undefined);
                if (sa !== sb) diff.push({ campo: c.nome, prima: sa || 'vuoto', dopo: sb || 'vuoto' });
            });
            return diff;
        }
    };

    const CAMPI_TRACCIATI = [
        { chiave: 'cliente', nome: 'Cliente' },
        { chiave: 'tipo', nome: 'Tipo incarico' },
        { chiave: 'codiceFiscale', nome: 'Codice fiscale' },
        { chiave: 'area', nome: 'Area' },
        { chiave: 'regione', nome: 'Regione' },
        { chiave: 'dataInizio', nome: 'Data inizio' },
        { chiave: 'dataFine', nome: 'Data fine' },
        { chiave: 'rinnovo', nome: 'Rinnovo' },
        { chiave: 'qualita', nome: 'Responsabile qualità' },
        { chiave: 'respIncarico', nome: 'Responsabile incarico' },
        { chiave: 'referente', nome: 'Referente' },
        { chiave: 'team', nome: 'Team di revisione' },
        { chiave: 'email1', nome: 'Email 1' },
        { chiave: 'email2', nome: 'Email 2' },
        { chiave: 'compensi', nome: 'Compensi' },
        { chiave: 'fatturazione', nome: 'Modalità fatturazione' },
        { chiave: 'gruppoFatturazione', nome: 'Gruppo di fatturazione' },
        { chiave: 'fattInizio', nome: 'Inizio fatturazione' },
        { chiave: 'fattFine', nome: 'Fine fatturazione' },
        { chiave: 'fattData', nome: 'Data fattura' },
        { chiave: 'speseGenerali', nome: 'Spese generali' },
        { chiave: 'speseGeneraliPerc', nome: 'Percentuale spese generali' },
        { chiave: 'stato', nome: 'Stato' },
        { chiave: 'statoNote', nome: 'Note stato' },
        { chiave: 'calcoloCongelato', nome: 'Calcolo congelato' }
    ];

    /* =========================================================
       AUTENTICAZIONE (simulata)
    ========================================================= */
    const Auth = {
        utenteCorrente: null,

        utenti() { return Store.leggi(CHIAVI.utenti, []); },
        salvaUtenti(u) { Store.scrivi(CHIAVI.utenti, u); },
        trova(email) {
            return this.utenti().find(u => u.email.toLowerCase() === String(email || '').trim().toLowerCase()) || null;
        },

        async richiediPrimaPassword(email) {
            if (Cloud.attivo) return Cloud.primaPassword(email);
            const utenti = this.utenti();
            const u = utenti.find(x => x.email.toLowerCase() === email.toLowerCase());
            if (!u) return { ok: false, msg: 'Indirizzo non autorizzato. L\'accesso è riservato agli utenti abilitati dall\'amministratore.' };
            if (!u.attivo) return { ok: false, msg: 'Utenza disabilitata. Contatta l\'amministratore.' };
            if (u.hash) return { ok: false, msg: 'Password già impostata per questa utenza. Usa "Password dimenticata?" per reimpostarla.' };
            const temp = generaPasswordTemporanea();
            u.hash = await sha256(u.sale + '|' + temp);
            u.mustChange = true;
            this.salvaUtenti(utenti);
            Audit.registra(u.email, 'Prima password generata', 'utente', u.email, null,
                'Richiesta prima password dalla pagina di accesso');
            return { ok: true, temp };
        },

        async recuperaPassword(email) {
            if (Cloud.attivo) return Cloud.recuperaPassword(email);
            const utenti = this.utenti();
            const u = utenti.find(x => x.email.toLowerCase() === email.toLowerCase());
            if (!u) return { ok: false, msg: 'Indirizzo non autorizzato.' };
            if (!u.attivo) return { ok: false, msg: 'Utenza disabilitata. Contatta l\'amministratore.' };
            if (!u.hash) return { ok: false, msg: 'Per questa utenza non è mai stata impostata una password: usa "Richiedi la prima password".' };
            const temp = generaPasswordTemporanea();
            u.hash = await sha256(u.sale + '|' + temp);
            u.mustChange = true;
            u.tentativi = 0; u.bloccatoFino = 0;
            this.salvaUtenti(utenti);
            Audit.registra(u.email, 'Password reimpostata (recupero)', 'utente', u.email, null,
                'Recupero password dalla pagina di accesso');
            return { ok: true, temp };
        },

        async accedi(email, password) {
            if (Cloud.attivo) return Cloud.accedi(email, password);
            const utenti = this.utenti();
            const u = utenti.find(x => x.email.toLowerCase() === email.toLowerCase());
            if (!u || !u.attivo) return { ok: false, msg: 'Credenziali non valide o utenza non abilitata.' };
            if (u.bloccatoFino && Date.now() < u.bloccatoFino) {
                const min = Math.ceil((u.bloccatoFino - Date.now()) / 60000);
                return { ok: false, msg: 'Utenza temporaneamente bloccata per troppi tentativi. Riprova tra ' + min + ' minuti.' };
            }
            if (!u.hash) return { ok: false, msg: 'Nessuna password impostata: usa "Richiedi la prima password".' };
            const h = await sha256(u.sale + '|' + password);
            if (h !== u.hash) {
                u.tentativi = (u.tentativi || 0) + 1;
                if (u.tentativi >= 5) {
                    u.bloccatoFino = Date.now() + 5 * 60000;
                    u.tentativi = 0;
                    Audit.registra(u.email, 'Utenza bloccata (5 tentativi falliti)', 'utente', u.email, null, null);
                }
                this.salvaUtenti(utenti);
                return { ok: false, msg: 'Credenziali non valide.' };
            }
            u.tentativi = 0; u.bloccatoFino = 0; u.ultimoAccesso = Date.now();
            this.salvaUtenti(utenti);
            this.utenteCorrente = u;
            sessionStorage.setItem('rvArea.sessione', JSON.stringify({ email: u.email, ts: Date.now() }));
            Audit.registra(u.email, 'Accesso effettuato', 'utente', u.email, null, null);
            return { ok: true, mustChange: !!u.mustChange };
        },

        async cambiaPassword(email, nuova) {
            if (Cloud.attivo) return Cloud.cambiaPassword(email, nuova);
            const utenti = this.utenti();
            const u = utenti.find(x => x.email.toLowerCase() === email.toLowerCase());
            if (!u) return { ok: false, msg: 'Utente non trovato.' };
            const controllo = Auth.validaPassword(nuova);
            if (controllo) return { ok: false, msg: controllo };
            u.sale = uid();
            u.hash = await sha256(u.sale + '|' + nuova);
            u.mustChange = false;
            this.salvaUtenti(utenti);
            if (this.utenteCorrente && this.utenteCorrente.email === u.email) this.utenteCorrente = u;
            Audit.registra(u.email, 'Password modificata', 'utente', u.email, null, null);
            return { ok: true };
        },

        validaPassword(p) {
            if (!p || p.length < 8) return 'La password deve avere almeno 8 caratteri.';
            if (!/[A-Z]/.test(p)) return 'La password deve contenere almeno una lettera maiuscola.';
            if (!/[a-z]/.test(p)) return 'La password deve contenere almeno una lettera minuscola.';
            if (!/[0-9]/.test(p)) return 'La password deve contenere almeno una cifra.';
            return null;
        },

        ripristinaSessione() {
            try {
                const s = JSON.parse(sessionStorage.getItem('rvArea.sessione'));
                if (!s) return false;
                const u = this.trova(s.email);
                if (!u || !u.attivo || u.mustChange) return false;
                this.utenteCorrente = u;
                return true;
            } catch (e) { return false; }
        },

        esci() {
            if (this.utenteCorrente) Audit.registra(this.utenteCorrente.email, 'Uscita', 'utente', this.utenteCorrente.email, null, null);
            this.utenteCorrente = null;
            sessionStorage.removeItem('rvArea.sessione');
            // chi rientra deve rivedere l'avviso sul proprio territorio
            try { sessionStorage.removeItem(CHIAVE_AVVISO_AMBITO); } catch (e) { }
            if (Cloud.attivo) Cloud.esci();
        },

        eAdmin() { return this.utenteCorrente && this.utenteCorrente.ruolo === 'admin'; },
        // "Dati e backup" e riservato al titolare dello studio
        eProprietario() {
            return this.utenteCorrente && this.utenteCorrente.email && this.utenteCorrente.email.toLowerCase() === PROPRIETARIO;
        },
        /* L'eliminazione DEFINITIVA di un incarico non si annulla e porta via anche il suo
           piano di fatturazione: resta ad amministratore e titolare. Gli altri ruoli, se
           hanno la scrittura sugli incarichi, li chiudono con "Termina" o "Dimissioni"
           (reversibili, tutto lo storico resta). */
        puoEliminareIncarichi() { return this.eAdmin() || this.eProprietario(); },

        /* Il ruolo dell'utente collegato, gia' normalizzato. Il titolare e l'admin hanno sempre
           accesso pieno (non si possono chiudere fuori da soli). Il Coordinatore territoriale
           ha un profilo IMPOSTO dal codice, non dai dati salvati: sempre e solo visualizzazione.
           Un ruolo sconosciuto (es. cancellato) non vede nulla: fail-closed. */
        ruoloCorrente() {
            const u = this.utenteCorrente;
            if (!u) return null;
            if (this.eProprietario() || u.ruolo === 'admin') return { id: 'admin', nome: 'Amministratore', admin: true, builtin: true, sezioni: sezioniTutte('scrittura') };
            // ruoli "solo sondaggio": vedono unicamente la sezione Sondaggi (compilazione o risultati)
            if (eRuoloSoloSondaggio(u.ruolo)) {
                const compila = u.ruolo === RUOLI_SOND.compila;
                const sez = sezioniTutte('no'); sez.sondaggi = compila ? 'scrittura' : 'lettura';
                return { id: u.ruolo, nome: NOMI_RUOLO_SOND[u.ruolo] || 'Sondaggio', builtin: true, sistema: true, soloSondaggio: true, sondaggioRuolo: compila ? 'compila' : 'risultati', sezioni: sez };
            }
            // Coordinatore e Vice: i permessi per sezione sono MODIFICABILI dall'amministratore
            // (sezione Ruoli), ma il filtro per regione resta sempre attivo (flag coordinatore).
            // Si legge il profilo salvato; se manca del tutto, sola visualizzazione ovunque.
            if (u.ruolo === 'coordinatore' || u.ruolo === 'vicecoordinatore') {
                const salvato = Ruoli.trova(u.ruolo);
                const norm = salvato ? Ruoli.normalizza(salvato)
                    : { id: u.ruolo, nome: u.ruolo === 'coordinatore' ? 'Coordinatore territoriale' : 'Vice coordinatore territoriale', builtin: true, sistema: true, sezioni: sezioniTutte('lettura') };
                norm.coordinatore = true;
                return norm;
            }
            /* Marketing: i livelli per sezione li sceglie l'amministratore dalla sezione
               Ruoli e permessi, scrittura compresa. Se il profilo non e' mai stato
               salvato vale il valore di partenza: tutto in sola lettura. */
            if (u.ruolo === RUOLO_MARKETING) {
                const salvato = Ruoli.trova(RUOLO_MARKETING);
                if (salvato) return Ruoli.normalizza(salvato);
                return { id: RUOLO_MARKETING, nome: 'Marketing', builtin: true, sistema: true, sezioni: sezioniTutte('lettura') };
            }
            const r = Ruoli.trova(u.ruolo);
            if (r) return Ruoli.normalizza(r);
            return { id: u.ruolo || '', nome: u.ruolo || 'Senza ruolo', sconosciuto: true, sezioni: sezioniTutte('no') };
        },
        /* La scheda in Aderenti Revilaw dell'utente collegato (agganciata per email): per il
           Coordinatore territoriale e' li' che stanno scritte le sue regioni.
           Se per errore due schede hanno la stessa email, vince la piu' completa
           (attiva e con le regioni coordinate compilate), non la prima in elenco. */
        personaCorrente() {
            const u = this.utenteCorrente;
            if (!u || !u.email) return null;
            const em = String(u.email).toLowerCase();
            const match = Persone.tutte().filter(p => p.email && !p.eliminato && String(p.email).toLowerCase() === em);
            if (!match.length) return null;
            const punti = p => (p.attivo ? 2 : 0) + (regioniCoperte(p).length ? 1 : 0);
            return match.sort((a, b) => punti(b) - punti(a))[0];
        },
        /* Equity partner e founding partner sono qualifiche dell'ANAGRAFICA (scheda in
           Aderenti Revilaw), non ruoli di accesso: valgono comunque sia il ruolo con cui
           si entra. Servono alle richieste di correzione: agli equity si indirizzano, e
           insieme ai founding sono gli unici a vederle tutte. */
        eEquityPartner() { const p = this.personaCorrente(); return !!(p && p.equityPartner); },
        eFoundingPartner() { const p = this.personaCorrente(); return !!(p && p.foundingPartner); },
        /* Profilo "Marketing": e' un RUOLO (sezione Ruoli e permessi), non una qualifica
           dell'anagrafica. Sulle richieste di correzione vede quello che vede un equity
           partner - tutte - ma resta osservatore: non le riceve, non le lavora, non
           risponde. Nelle sezioni invece valgono i livelli del suo ruolo, e
           l'amministratore puo' dargli anche la scrittura. */
        eMarketing() {
            return !!this.utenteCorrente && this.utenteCorrente.ruolo === RUOLO_MARKETING
                && !this.eAdmin() && !this.eProprietario();
        },
        vedeTutteLeRichieste() {
            return this.eAdmin() || this.eProprietario() || this.eEquityPartner() || this.eFoundingPartner()
                || this.eMarketing();
        },
        /* Chi puo' PRENDERE IN CARICO e chiudere le richieste altrui. L'osservatore no:
           e' l'unica differenza rispetto a chi le vede tutte. */
        puoLavorareRichieste() {
            return this.eAdmin() || this.eProprietario() || this.eEquityPartner() || this.eFoundingPartner();
        },
        /* Vede tutto ma non puo' fare nulla sulle richieste che non sono sue: serve a
           dirglielo apertamente, invece di mostrargli comandi che non funzionano. */
        soloVisualizzazioneRichieste() {
            return this.vedeTutteLeRichieste() && !this.puoLavorareRichieste();
        },
        // livello sulla singola sezione di contenuto: 'no' | 'lettura' | 'scrittura'
        accessoSezione(sez) {
            const r = this.ruoloCorrente();
            if (!r) return 'no';
            if (r.admin) return 'scrittura';
            return (r.sezioni && r.sezioni[sez]) || 'no';
        },
        // sezioni "di sistema": non passano dai ruoli, restano di admin/titolare.
        // Il titolare ha sempre i poteri dell'admin (non deve potersi chiudere fuori).
        puoVedere(sez) {
            if (sez === 'utenti' || sez === 'ruoli') return this.eAdmin() || this.eProprietario();
            if (sez === 'dati') return this.eProprietario();
            // "Eventi" non passa dai ruoli: la vede l'admin e i soli utenti scelti a mano
            if (sez === 'eventi') return puoVedereEventi();
            // stessa regola per la Newsletter: si spediscono email a nome dello studio
            if (sez === 'newsletter') return puoVedereNewsletter();
            // Le richieste di correzione non passano dai ruoli e non si possono togliere:
            // sono la via di servizio con cui CHIUNQUE segnala un dato sbagliato, ed e'
            // proprio chi non ha la scrittura ad averne piu' bisogno. Restano fuori solo
            // gli invitati "solo sondaggio", che dei dati dello studio non vedono nulla.
            if (sez === 'richieste') return this.puoUsareRichieste();
            // I Controlli qualita hanno un filtro in piu' sulla PERSONA: la sezione compare
            // solo a chi in Aderenti Revilaw e' responsabile qualita o equity partner
            // (e ad amministratore e titolare). Vedi cqProfilo().
            if (sez === 'controlloQualita') return this.accessoSezione(sez) !== 'no' && !!cqProfilo();
            return this.accessoSezione(sez) !== 'no';
        },
        puoScrivere(sez) {
            if (sez === 'utenti' || sez === 'ruoli') return this.eAdmin() || this.eProprietario();
            if (sez === 'dati') return this.eProprietario();
            // Eventi e Newsletter non passano dai ruoli: chi e' abilitato puo' anche operare
            if (sez === 'eventi') return puoVedereEventi();
            if (sez === 'newsletter') return puoVedereNewsletter();
            if (sez === 'richieste') return this.puoUsareRichieste();
            return this.accessoSezione(sez) === 'scrittura';
        },
        puoUsareRichieste() {
            const r = this.ruoloCorrente();
            return !!r && !r.soloSondaggio && !r.sconosciuto;
        },
        /* null = tutte le regioni. Solo coordinatore e vice sono limitati: alle regioni
           coordinate indicate sulla LORO scheda in Aderenti Revilaw (agganciata per email).
           La Regione della scheda NON conta piu' da sola: e' la residenza, e valeva come
           territorio senza che nessuno l'avesse scelta. Scheda mancante o senza alcuna
           regione coordinata = nessun incarico visibile (fail-closed): si sistema
           spuntando le regioni sulla scheda. */
        regioniConsentite() {
            const r = this.ruoloCorrente();
            if (!r || !r.coordinatore) return null;
            const p = this.personaCorrente();
            if (!p) return [];
            // chiave normalizzata: grafie diverse della stessa regione (accenti, trattini) coincidono
            return Array.from(new Set(regioniCoperte(p).map(chiaveRegione).filter(Boolean)));
        },
        vedeIncarico(inc) {
            const reg = this.regioniConsentite();
            if (!reg) return true;
            return reg.includes(chiaveRegione((inc && inc.regione) || ''));
        }
    };

    /* Le regioni a cui e' limitato il ruolo collegato, nella grafia della scheda:
       null = il ruolo vede tutto, [] = e' limitato ma non ha alcuna regione spuntata.
       Le viste di riepilogo la usano per dichiarare su quale perimetro sono calcolati i
       numeri: senza, un coordinatore poteva leggere i totali del proprio territorio come
       se fossero quelli dello studio. */
    function regioniDelRuolo() {
        if (!Auth.regioniConsentite()) return null;
        const p = Auth.personaCorrente();
        return p ? regioniCoperte(p) : [];
    }

    /* =========================================================
       CLOUD (Firebase: accesso reale via email e dati condivisi)
       Attivo solo se window.RV_FIREBASE_CONFIG e' compilato.
    ========================================================= */
    const Cloud = {
        attivo: false,
        pronto: false,
        fb: null, app: null, auth: null, db: null,
        sottoscrizioni: [],
        DOC_SYNC: null,

        async init() {
            const config = window.RV_FIREBASE_CONFIG;
            if (!config || !config.apiKey) return;
            try {
                const V = '11.6.1';
                const [appMod, authMod, fsMod] = await Promise.all([
                    import('https://www.gstatic.com/firebasejs/' + V + '/firebase-app.js'),
                    import('https://www.gstatic.com/firebasejs/' + V + '/firebase-auth.js'),
                    import('https://www.gstatic.com/firebasejs/' + V + '/firebase-firestore.js')
                ]);
                this.fb = { appMod, authMod, fsMod };
                this.app = appMod.initializeApp(config);
                this.auth = authMod.getAuth(this.app);
                // email di Firebase (reimpostazione password) in italiano
                this.auth.languageCode = 'it';
                // sessione limitata alla scheda, come in modalita demo
                // sessione persistente (sopravvive ai reload); l'inattivita di
                // 30 minuti viene fatta rispettare dall'app, anche dopo un riavvio
                try { await authMod.setPersistence(this.auth, authMod.browserLocalPersistence); } catch (e) { }
                this.db = fsMod.getFirestore(this.app);
                this.DOC_SYNC = {};
                this.DOC_SYNC[CHIAVI.incarichi] = 'incarichi';
                this.DOC_SYNC[CHIAVI.persone] = 'persone';
                this.DOC_SYNC[CHIAVI.audit] = 'audit';
                this.DOC_SYNC[CHIAVI.fatture] = 'fattureStato';
                this.DOC_SYNC[CHIAVI.allerte] = 'allerte';
                this.DOC_SYNC[CHIAVI.comunicazioni] = 'comunicazioni';
                this.DOC_SYNC[CHIAVI.sondaggi] = 'sondaggi';
                this.DOC_SYNC[CHIAVI.sondaggiConfig] = 'sondaggiConfig';
                this.DOC_SYNC[CHIAVI.eventiConfig] = 'eventiConfig';
                this.DOC_SYNC[CHIAVI.eventiPresenze] = 'eventiPresenze';
                this.DOC_SYNC[CHIAVI.newsletter] = 'newsletter';
                this.DOC_SYNC[CHIAVI.newsletterContatti] = 'newsletterContatti';
                this.DOC_SYNC[CHIAVI.newsletterConfig] = 'newsletterConfig';
                this.DOC_SYNC[CHIAVI.richieste] = 'richieste';
                this.DOC_SYNC[CHIAVI.rating] = 'rating';
                this.DOC_SYNC[CHIAVI.controlliQualita] = 'controlliQualita';
                this.DOC_SYNC[CHIAVI.ruoli] = 'ruoli';
                this.attivo = true;
                // svuota la coda di scritture prima che la scheda venga chiusa
                // o messa in background (evita perdite silenziose su Firestore)
                const teardown = () => { if (this._timerFlush) { clearTimeout(this._timerFlush); this._timerFlush = null; } this._flush(); };
                window.addEventListener('pagehide', teardown);
                document.addEventListener('visibilitychange', () => { if (document.visibilityState === 'hidden') teardown(); });
            } catch (e) {
                console.error('Firebase non inizializzato, resto in modalita dimostrativa:', e);
                this.attivo = false;
            }
        },

        async docUtente(email) {
            const { doc, getDoc } = this.fb.fsMod;
            const snap = await getDoc(doc(this.db, 'utenti', email.toLowerCase()));
            return snap.exists() ? snap.data() : null;
        },

        /* sessione gia aperta (ricarica pagina) */
        async utenteDaSessione() {
            const { onAuthStateChanged, signOut } = this.fb.authMod;
            const utenteFb = await new Promise(risolvi => {
                const stacca = onAuthStateChanged(this.auth, u => { stacca(); risolvi(u); });
            });
            if (!utenteFb || !utenteFb.email) return null;
            // sessione persistente ma scaduta per inattivita: si esce
            if (sessioneScaduta()) { try { await signOut(this.auth); } catch (e) { } return null; }
            try {
                const dati = await this.docUtente(utenteFb.email);
                if (!dati || dati.attivo === false) { await signOut(this.auth); return null; }
                await this.avviaSync(dati.ruolo, utenteFb.email);
                return { email: utenteFb.email.toLowerCase(), nome: dati.nome || utenteFb.email, ruolo: dati.ruolo || 'procuratore', eventi: dati.eventi === true, newsletter: dati.newsletter === true };
            } catch (e) { return null; }
        },

        async accedi(email, password) {
            const { signInWithEmailAndPassword, signOut } = this.fb.authMod;
            try {
                await signInWithEmailAndPassword(this.auth, email, password);
            } catch (e) {
                return { ok: false, msg: this.msgErrore(e) };
            }
            let dati = null;
            try { dati = await this.docUtente(email); } catch (e) { /* lettura negata = non abilitato */ }
            if (!dati || dati.attivo === false) {
                await signOut(this.auth);
                return { ok: false, msg: 'Utenza non abilitata: chiedi all\'amministratore di aggiungerti all\'elenco utenti.' };
            }
            try {
                await this.avviaSync(dati.ruolo, email);
            } catch (e) {
                try { await signOut(this.auth); } catch (e2) { }
                return { ok: false, msg: 'Accesso verificato ma dati non raggiungibili (' + this.msgErrore(e) + '). Riprova tra poco.' };
            }
            Auth.utenteCorrente = { email: email.toLowerCase(), nome: dati.nome || email, ruolo: dati.ruolo || 'procuratore', eventi: dati.eventi === true, newsletter: dati.newsletter === true };
            this.salvaUtente(email, { ultimoAccesso: Date.now() }).catch(() => {});
            Audit.registra(Auth.utenteCorrente, 'Accesso effettuato', 'utente', email.toLowerCase(), null, null);
            return { ok: true, mustChange: false };
        },

        // invia tramite il servizio email dedicato, se configurato
        async inviaTramiteServizio(email, tipo) {
            const url = window.RV_EMAIL_SERVICE_URL;
            if (!url) return null; // non configurato: si usa l'invio standard
            try {
                const r = await fetch(url, {
                    method: 'POST', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ email, tipo })
                });
                const data = await r.json().catch(() => ({}));
                if (!r.ok || (data && data.ok === false)) return { ok: false, msg: (data && data.msg) || ('Servizio email non disponibile (' + r.status + ').') };
                // saltato = il servizio ha risposto ok ma NON ha inviato (limite anti-abuso per l'indirizzo)
                return { ok: true, viaEmail: true, saltato: !!(data && data.saltato), msg: (data && data.msg) || null };
            } catch (e) {
                return { ok: false, msg: 'Servizio email non raggiungibile.' };
            }
        },

        // Invia una comunicazione libera: passa l'ID token dell'utente loggato,
        // che il server verifica (solo utenti abilitati possono inviare).
        async inviaComunicazione(oggetto, testo, destinatari, formato) {
            let url = window.RV_COMUNICAZIONI_URL;
            if (!url && window.RV_EMAIL_SERVICE_URL) url = window.RV_EMAIL_SERVICE_URL.replace(/invia-email(\/?)$/, 'invia-comunicazione$1');
            if (!url) return { ok: false, msg: 'Servizio di invio non configurato.' };
            if (!this.auth || !this.auth.currentUser) return { ok: false, msg: 'Sessione scaduta: rientra e riprova.' };
            let idToken;
            try { idToken = await this.auth.currentUser.getIdToken(); }
            catch (e) { return { ok: false, msg: 'Sessione scaduta: rientra e riprova.' }; }
            const mittenteNome = Auth.utenteCorrente ? Auth.utenteCorrente.nome : '';
            try {
                const r = await fetch(url, {
                    method: 'POST', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ idToken, oggetto, testo, destinatari, mittenteNome, formato })
                });
                const data = await r.json().catch(() => ({}));
                if (!r.ok || !data.ok) return { ok: false, msg: (data && data.msg) || ('Invio non riuscito (' + r.status + ').'), falliti: (data && data.falliti) || [] };
                return { ok: true, inviati: data.inviati, falliti: (data && data.falliti) || [] };
            } catch (e) {
                return { ok: false, msg: 'Servizio di invio non raggiungibile.' };
            }
        },

        /* Legge un documento dell'archivio DIRETTAMENTE dal server, senza passare dalla
           copia locale: serve alla diagnostica, per capire se un salvataggio e davvero
           arrivato a Firestore oppure e rimasto solo nel browser di chi l'ha fatto. */
        async leggiArchivioRemoto(nomeDoc) {
            if (!this.attivo || !this.db) return { ok: false, msg: 'accesso cloud non attivo' };
            try {
                const { doc, getDoc } = this.fb.fsMod;
                const snap = await getDoc(doc(this.db, 'archivio', nomeDoc));
                if (!snap.exists()) return { ok: true, esiste: false };
                const d = snap.data() || {};
                return { ok: true, esiste: true, json: d.json, da: d.da || '', aggiornato: d.aggiornato || null };
            } catch (e) {
                return { ok: false, msg: (e && e.code) || (e && e.message) || 'errore di lettura' };
            }
        },

        /* Iscrizioni a un evento, lette dal foglio Google tramite il servizio (che
           verifica chi chiama e filtra le righe dell'evento). Nessun dato personale
           finisce nel repository: arriva a video e resta su Firestore. */
        async iscrizioniEvento(evento, idEvento, tutti, forza) {
            let url = window.RV_ISCRIZIONI_URL;
            if (!url && window.RV_EMAIL_SERVICE_URL) url = window.RV_EMAIL_SERVICE_URL.replace(/invia-email(\/?)$/, 'iscrizioni$1');
            if (!url) return { ok: false, msg: 'Servizio iscrizioni non configurato.' };
            if (!this.auth || !this.auth.currentUser) return { ok: false, msg: 'Sessione scaduta: rientra e riprova.' };
            let idToken;
            try { idToken = await this.auth.currentUser.getIdToken(); }
            catch (e) { return { ok: false, msg: 'Sessione scaduta: rientra e riprova.' }; }
            try {
                const r = await fetch(url, {
                    method: 'POST', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ idToken, evento, idEvento, tutti: !!tutti, filtri: tutti ? FILTRI_EVENTI : [], forza: !!forza })
                });
                const data = await r.json().catch(() => ({}));
                if (!r.ok || !data.ok) return { ok: false, msg: (data && data.msg) || ('Lettura non riuscita (' + r.status + ').') };
                return { ok: true, iscrizioni: data.iscrizioni || [], presenze: data.presenze || {}, aggiornato: data.aggiornato || Date.now() };
            } catch (e) {
                return { ok: false, msg: 'Servizio iscrizioni non raggiungibile.' };
            }
        },

        /* Stato, nota e cancellazione di un iscritto: decide il servizio, non le
           regole di Firestore, cosi' funziona per tutti gli abilitati alla sezione. */
        async operaPresenza(corpo) {
            let url = window.RV_PRESENZE_URL;
            if (!url && window.RV_EMAIL_SERVICE_URL) url = window.RV_EMAIL_SERVICE_URL.replace(/invia-email(\/?)$/, 'presenze$1');
            if (!url) return { ok: false, msg: 'Servizio non configurato.' };
            if (!this.auth || !this.auth.currentUser) return { ok: false, msg: 'Sessione scaduta: rientra e riprova.' };
            let idToken;
            try { idToken = await this.auth.currentUser.getIdToken(); }
            catch (e) { return { ok: false, msg: 'Sessione scaduta: rientra e riprova.' }; }
            try {
                const r = await fetch(url, {
                    method: 'POST', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ idToken, ...corpo })
                });
                const data = await r.json().catch(() => ({}));
                if (!r.ok || !data.ok) return { ok: false, msg: (data && data.msg) || ('Operazione non riuscita (' + r.status + ').') };
                // la risposta passa INTERA: oltre a presenza ci viaggiano l'esito
                // della mail di conferma, l'id della scheda creata e i conteggi
                // dell'invito B2B (inviate, giaInvitate, falliti...)
                return { ...data, ok: true, presenza: data.presenza || null };
            } catch (e) {
                /* Stesso indirizzo delle aziende: se cade qui, cade tutto il
                   servizio, non una sezione. Vale la pena saperlo subito. */
                return { ok: false, msg: await this._perche(url, e) };
            }
        },

        /* Importazione una tantum: csv vuoto = leggi direttamente dal foglio. */
        async importaIscrizioni(csv, pagina, dataPredefinita) {
            let url = window.RV_IMPORTA_ISCRIZIONI_URL;
            if (!url && window.RV_EMAIL_SERVICE_URL) url = window.RV_EMAIL_SERVICE_URL.replace(/invia-email(\/?)$/, 'importa-iscrizioni$1');
            if (!url) return { ok: false, msg: 'Servizio non configurato.' };
            if (!this.auth || !this.auth.currentUser) return { ok: false, msg: 'Sessione scaduta: rientra e riprova.' };
            let idToken;
            try { idToken = await this.auth.currentUser.getIdToken(); }
            catch (e) { return { ok: false, msg: 'Sessione scaduta: rientra e riprova.' }; }
            try {
                const r = await fetch(url, {
                    method: 'POST', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ idToken, csv: csv || '', pagina: pagina || '', dataPredefinita: dataPredefinita || '' })
                });
                const data = await r.json().catch(() => ({}));
                if (!r.ok || !data.ok) return { ok: false, msg: (data && data.msg) || ('Importazione non riuscita (' + r.status + ').') };
                return { ok: true, lette: data.lette || 0, importate: data.importate || 0, saltate: data.saltate || 0, fonte: data.fonte || '' };
            } catch (e) {
                return { ok: false, msg: 'Servizio non raggiungibile.' };
            }
        },

        /* PERCHE' la chiamata non e' arrivata a destinazione.
           "Servizio non raggiungibile" da solo non dice nulla, e il motivo e'
           una crudelta' del browser: quando la risposta gli arriva SENZA i
           permessi per leggerla (CORS), solleva esattamente lo stesso errore
           che solleva quando dall'altra parte non risponde nessuno. Due
           guasti opposti, una frase sola, e si finisce a indovinare.

           Qui si separano, con due sonde:

           1. Un GET semplice: non porta intestazioni sue, quindi il browser
              NON manda la richiesta di permesso preventiva e va dritto alla
              funzione. Se torna un 405 leggibile, la funzione e' viva, le
              intestazioni CORS ci sono, e il guasto sta piu' avanti (nella
              richiesta di permesso o nel POST).
           2. Un GET "no-cors": non chiede permessi, quindi RIESCE se
              dall'altra parte risponde qualcuno, comunque risponda. Se
              riesce mentre il primo fallisce, il servizio c'e' ma sta
              rispondendo senza permessi: la funzione si interrompe prima di
              scriverli. Se fallisce anche questo, non risponde nessuno.

           Il verdetto finisce a schermo cosi' com'e': meglio una riga lunga
           che si legge, di una corta che costringe ad aprire la console. */
        async _perche(url, err) {
            const dettaglio = ' [' + ((err && err.message) ? String(err.message).slice(0, 120) : 'errore non descritto') + ' - ' + url + ']';
            try {
                const r = await fetch(url, { method: 'GET', cache: 'no-store' });
                return 'Il servizio risponde (' + r.status + ') alle richieste semplici, ma rifiuta questa: '
                    + 'il permesso preventivo del browser non passa.' + dettaglio;
            } catch (e1) { /* si prova la seconda sonda */ }
            try {
                await fetch(url, { method: 'GET', mode: 'no-cors', cache: 'no-store' });
                return 'Il servizio c\'è e risponde, ma la risposta arriva senza i permessi per questa pagina. '
                    + 'O la funzione si interrompe prima di scriverli, oppure sul servizio ALLOWED_ORIGIN '
                    + 'non corrisponde a ' + (location.origin || '(origine ignota)') + '.' + dettaglio;
            } catch (e2) { /* nessuno risponde */ }
            return 'Nessuna risposta dal servizio: indirizzo sbagliato, rilascio assente o rete bloccata.' + dettaglio;
        },

        /* Aziende da invitare a un evento: elenco, caricamento e invio
           dell'invito (email ordinaria o PEC). Un solo servizio con piu'
           azioni, come le presenze. Chi puo' fare cosa lo decide il
           servizio, non queste righe. */
        async aziendeInvito(corpo) {
            /* Stesso indirizzo delle presenze, non uno suo. Il piano Hobby di
               Vercel ammetteva 12 funzioni per rilascio e in api/ ce n'erano
               gia' 12: la tredicesima faceva fallire la distribuzione. Sul
               piano Pro il tetto non c'e' piu', ma finche' il servizio devia
               le richieste da presenze questo indirizzo resta quello giusto.
               La sezione distingue le richieste, perche' i nomi delle azioni
               si somigliano (aggiungi, modifica, cancella stanno da entrambe
               le parti). */
            let url = window.RV_PRESENZE_URL;
            if (!url && window.RV_EMAIL_SERVICE_URL) url = window.RV_EMAIL_SERVICE_URL.replace(/invia-email(\/?)$/, 'presenze$1');
            if (!url) return { ok: false, msg: 'Servizio non configurato.' };
            if (!this.auth || !this.auth.currentUser) return { ok: false, msg: 'Sessione scaduta: rientra e riprova.' };
            let idToken;
            try { idToken = await this.auth.currentUser.getIdToken(); }
            catch (e) { return { ok: false, msg: 'Sessione scaduta: rientra e riprova.' }; }
            try {
                const r = await fetch(url, {
                    method: 'POST', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ idToken, sezione: 'aziende', ...corpo })
                });
                const data = await r.json().catch(() => ({}));
                if (!r.ok || !data.ok) return { ...data, ok: false, msg: (data && data.msg) || ('Operazione non riuscita (' + r.status + ').') };
                return { ...data, ok: true };
            } catch (e) {
                return { ok: false, msg: await this._perche(url, e) };
            }
        },

        /* --- NEWSLETTER ---
           Un unico servizio per l'elenco dei destinatari raccolti dal sito
           (tutte le pagine, non solo gli eventi) e per le disiscrizioni. */
        _urlNewsletter(nome) {
            let url = window['RV_' + nome.toUpperCase().replace(/-/g, '_') + '_URL'];
            if (!url && window.RV_EMAIL_SERVICE_URL) url = window.RV_EMAIL_SERVICE_URL.replace(/invia-email(\/?)$/, nome + '$1');
            return url || '';
        },
        async _chiamaNewsletter(nome, corpo) {
            const url = this._urlNewsletter(nome);
            if (!url) return { ok: false, msg: 'Servizio newsletter non configurato.' };
            if (!this.auth || !this.auth.currentUser) return { ok: false, msg: 'Sessione scaduta: rientra e riprova.' };
            let idToken;
            try { idToken = await this.auth.currentUser.getIdToken(); }
            catch (e) { return { ok: false, msg: 'Sessione scaduta: rientra e riprova.' }; }
            try {
                const r = await fetch(url, {
                    method: 'POST', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ idToken, ...corpo })
                });
                const data = await r.json().catch(() => ({}));
                /* Anche quando va male si riporta indietro quello che il servizio ha
                   detto (per esempio "rimasti": gli indirizzi che NON sono partiti).
                   Sapere che un lotto non e' partito affatto e' diverso dal non
                   sapere niente: nel primo caso quelle persone vanno rimesse in coda,
                   nel secondo vanno saltate per non rischiare il doppione. */
                if (!r.ok || !data.ok) return { ...data, ok: false, msg: (data && data.msg) || ('Operazione non riuscita (' + r.status + ').') };
                return { ok: true, ...data };
            } catch (e) {
                // il servizio non ha risposto affatto: non si sa cosa sia successo
                return { ok: false, senzaRisposta: true, msg: 'Servizio newsletter non raggiungibile.' };
            }
        },
        /* Elenco completo: iscritti dai moduli del sito + chi si e' disiscritto. */
        async elencoNewsletter(forza) {
            return this._chiamaNewsletter('newsletter', { azione: 'elenco', forza: !!forza });
        },
        /* Disiscrizione (o riattivazione) registrata a mano dalla sezione. */
        async disiscriviNewsletter(email, riattiva) {
            return this._chiamaNewsletter('newsletter', { azione: riattiva ? 'riattiva' : 'disiscrivi', email: email });
        },
        /* Invio di un lotto: l'HTML arriva gia' pronto, il servizio ci mette
           dentro il collegamento personale di disiscrizione. */
        async inviaLottoNewsletter(corpo) {
            return this._chiamaNewsletter('invia-newsletter', corpo);
        },
        /* Come sono andati uno o piu' invii: si mandano solo le etichette di giro
           e la data di partenza, il servizio risponde con soli numeri. */
        async andamentoNewsletter(blocchi, forza) {
            return this._chiamaNewsletter('andamento-newsletter', { blocchi: blocchi, forza: !!forza });
        },
        /* Invio programmato: si mette in coda il contenuto GIA' COSTRUITO e
           l'elenco dei destinatari. Da quel momento il browser non serve piu'. */
        async programmaNewsletter(corpo) {
            return this._chiamaNewsletter('programma-newsletter', Object.assign({ azione: 'programma' }, corpo));
        },
        async annullaProgrammazione(campagna) {
            return this._chiamaNewsletter('programma-newsletter', { azione: 'annulla', campagna: campagna });
        },
        async statoProgrammate(campagne) {
            return this._chiamaNewsletter('programma-newsletter', { azione: 'stato', campagne: campagne });
        },

        /* prima password: crea l'account se manca (su una app secondaria,
           senza toccare la sessione corrente) e invia l'email con il
           collegamento per impostare la password */
        async primaPassword(email) {
            const { createUserWithEmailAndPassword, sendPasswordResetEmail, signOut, getAuth } = this.fb.authMod;
            const { initializeApp, getApps, getApp } = this.fb.appMod;
            try {
                const nomeApp = 'rv-secondaria';
                const appSec = getApps().some(a => a.name === nomeApp) ? getApp(nomeApp) : initializeApp(window.RV_FIREBASE_CONFIG, nomeApp);
                const authSec = getAuth(appSec);
                try {
                    await createUserWithEmailAndPassword(authSec, email, generaPasswordTemporanea() + generaPasswordTemporanea());
                    await signOut(authSec);
                } catch (e) { /* account gia esistente: si prosegue con l'email */ }
                // l'account ora esiste: se c'e il servizio dedicato, invia da li
                const viaServizio = await this.inviaTramiteServizio(email, 'attivazione');
                if (viaServizio) return viaServizio;
                await sendPasswordResetEmail(this.auth, email);
                return { ok: true, viaEmail: true };
            } catch (e) {
                return { ok: false, msg: this.msgErrore(e) };
            }
        },

        /* Invita al sondaggio via email. Per gli ESTERNI (non ancora utenti) crea un
           accesso limitato "solo sondaggio" (documento utenti + account + email per
           impostare la password); agli utenti gia' esistenti manda un'email di invito.
           Invia l'admin loggato (il suo ID token autentica il servizio). I limiti
           anti-spam del servizio possono far fallire qualche invio su elenchi grandi:
           i falliti vengono riportati per un nuovo tentativo. */
        /* Testo dell'email di invito al sondaggio. tipo: 'compila' | 'risultati';
           nuovo=true per chi deve ancora impostare la password (arriva in una email a parte). */
        /* Corpo HTML dell'email di invito al sondaggio (formato 'html': il servizio lo
           incornicia con l'intestazione e la firma Revilaw). Un testo unico per nuovi e
           gia utenti: la nota di accesso copre entrambi i casi. */
        _testoInvitoSondaggio(tipo, scadenzaTxt) {
            const link = (window.APP_BASE_URL || 'https://nextgenerationbusiness.it') + '/area-riservata/';
            const p = t => '<p style="margin:0 0 14px;">' + t + '</p>';
            const h = t => '<h2 style="color:#0A2844;font-size:18px;margin:0 0 12px;">' + t + '</h2>';
            // pulsante + indirizzo in chiaro: cosi il link resta visibile anche nella versione
            // testo semplice della mail (dove il servizio rimuove i tag <a> tenendo solo il testo)
            const btn = '<p style="text-align:center;margin:22px 0 8px;"><a href="' + link + '" style="background:#164068;color:#ffffff;text-decoration:none;padding:12px 28px;border-radius:8px;font-weight:600;display:inline-block;">Vai all\'area riservata</a></p>'
                + '<p style="font-size:12px;color:#64748B;margin:0 0 14px;text-align:center;">oppure apri: <span style="word-break:break-all;">' + esc(link) + '</span></p>';
            const intro = p('Accanto alla revisione legale, Revilaw sta sviluppando un percorso di consulenza integrata su sei aree: <b>adeguati assetti organizzativi</b>, <b>ESG e sostenibilità</b>, <b>compliance</b> con Tax Control Framework e Modello 231, <b>finanza agevolata</b>, <b>crisi d\'impresa e risanamento</b>, <b>wealth management</b>. Per ciascuna nasce un "gruppo di specialisti".');
            const accesso = '<table role="presentation" cellpadding="0" cellspacing="0" width="100%" style="background:#F1F5F9;border-radius:8px;margin:0 0 14px;"><tr><td style="padding:12px 16px;font-size:13px;color:#334155;line-height:1.55;">'
                + '<b>Come accedere:</b> usa le tue credenziali dell\'area riservata. Se è il tuo primo accesso, imposta prima la password dal link che trovi nella nostra email <b>"Imposta la tua password"</b> (controlla anche la posta indesiderata / spam).'
                + '</td></tr></table>';
            if (tipo === 'compila') {
                const scad = scadenzaTxt ? p('<b>C\'è tempo fino al ' + esc(scadenzaTxt) + '</b> (entro le 23:59).') : '';
                return h('Sei invitato a compilare il questionario')
                    + p('Gentile collega,')
                    + intro
                    + p('Ti chiediamo di indicare le <b>due aree</b> nelle quali vorresti entrare a far parte del gruppo e, per ciascuna, il tuo <b>livello di competenza</b>. Bastano un paio di minuti.')
                    + btn + accesso
                    + p('Poi apri la sezione <b>"Sondaggi"</b> e invia la tua risposta.')
                    + scad;
            }
            return h('Puoi consultare i risultati del questionario')
                + p('Gentile collega,')
                + intro
                + p('Sei stato abilitato alla <b>sola visualizzazione</b> dei risultati: potrai vedere le aree scelte dai colleghi e le competenze dichiarate. Non devi compilare nulla.')
                + btn + accesso
                + p('Poi apri la sezione <b>"Sondaggi"</b>, scheda <b>"Riepilogo risultati"</b>.');
        },
        async invitaSondaggio(comp, vis, utenti, ruoli, scadenzaTxt, onProgress) {
            if (!this.attivo) return { ok: false, msg: 'Accesso cloud non attivo.' };
            comp = comp || []; vis = vis || [];
            const accessoDi = {}; (utenti || []).forEach(u => { accessoDi[String(u.email).toLowerCase()] = u.ultimoAccesso || 0; });
            const esistenti = new Set(Object.keys(accessoDi));
            let creati = 0, inviati = 0; const falliti = [];
            const nomeDi = {};
            try { Persone.tutte().forEach(p => { if (p.email) nomeDi[String(p.email).toLowerCase()] = (p.nomeProprio ? p.nomeProprio + ' ' : '') + p.nome; }); } catch (e) { }
            const ruoloDi = e => comp.indexOf(e) >= 0 ? ruoli.compila : ruoli.risultati;
            // Link per la password: lo ricevono i nuovi (account da creare) e i gia utenti che
            // non sono mai entrati (glielo ri-inviamo, cosi possono finalmente accedere).
            const tuttiInvitati = Array.from(new Set(comp.concat(vis)));
            const pwFalliti = [];
            for (const e of tuttiInvitati) {
                const nuovo = !esistenti.has(e);
                if (!nuovo && !!accessoDi[e]) continue; // gia utente e gia entrato: usa le sue credenziali
                try {
                    if (nuovo) await this.salvaUtente(e, { nome: nomeDi[e] || e, ruolo: ruoloDi(e), attivo: true, creato: Date.now(), creatoDa: 'invito sondaggio' });
                    const r = await this.primaPassword(e);
                    if (r && r.ok) { if (nuovo) creati++; } else { falliti.push(e); pwFalliti.push({ email: e, motivo: (r && r.msg) || 'invio password non riuscito' }); }
                } catch (ex) { falliti.push(e); pwFalliti.push({ email: e, motivo: (ex && ex.message) || 'errore' }); }
            }
            // Email esplicativa dell'invito: UN solo invio per gruppo (compilatori / visualizzatori),
            // con un testo unico per nuovi e gia utenti. Il servizio email accetta un invio ogni
            // ~20s per mittente: quindi tra un gruppo e l'altro attendiamo, per non farci rifiutare
            // il secondo con "troppi invii ravvicinati".
            const PAUSA_MS = 21000;
            const pausa = ms => new Promise(r => setTimeout(r, ms));
            const oggetto = tipo => tipo === 'compila'
                ? 'Questionario Revilaw: gruppi di specialisti'
                : 'Risultati del questionario Revilaw: gruppi di specialisti';
            const jobs = [];
            if (comp.length) jobs.push({ tipo: 'compila', dest: comp });
            if (vis.length) jobs.push({ tipo: 'risultati', dest: vis });
            const esitoTipo = {};
            for (let i = 0; i < jobs.length; i++) {
                const j = jobs[i];
                if (i > 0) {
                    if (onProgress) { try { onProgress({ fase: 'attesa', secondi: Math.round(PAUSA_MS / 1000) }); } catch (e) { } }
                    await pausa(PAUSA_MS);
                }
                if (onProgress) { try { onProgress({ fase: 'invio', tipo: j.tipo, n: i + 1, tot: jobs.length }); } catch (e) { } }
                const destObj = j.dest.map(e => ({ email: e }));
                let r;
                try { r = await this.inviaComunicazione(oggetto(j.tipo), this._testoInvitoSondaggio(j.tipo, scadenzaTxt), destObj, 'html'); }
                catch (e) { r = { ok: false, msg: 'Servizio di invio non raggiungibile.' }; }
                if (r && r.ok) {
                    const fal = (r.falliti || []).map(f => (f && f.email) ? f : { email: f, motivo: 'rifiutato dal server di posta' });
                    const nInv = (typeof r.inviati === 'number') ? r.inviati : (destObj.length - fal.length);
                    inviati += nInv;
                    fal.forEach(f => falliti.push(f.email));
                    esitoTipo[j.tipo] = { destinatari: j.dest.length, inviati: nInv, falliti: fal };
                } else {
                    // il servizio, quando tutto fallisce, restituisce anche il motivo REALE per
                    // ogni indirizzo (es. l'errore SMTP di Aruba): mostriamo quello, non il generico
                    const msgGen = (r && r.msg) || 'invio non riuscito';
                    const falMap = {}; ((r && r.falliti) || []).forEach(f => { if (f && f.email) falMap[String(f.email).toLowerCase()] = f.motivo || msgGen; });
                    j.dest.forEach(e => falliti.push(e));
                    esitoTipo[j.tipo] = { destinatari: j.dest.length, inviati: 0, falliti: j.dest.map(e => ({ email: e, motivo: falMap[e] || msgGen })) };
                }
            }
            const dettaglio = {
                ts: Date.now(),
                scadenza: scadenzaTxt || '',
                password: { inviati: creati, falliti: pwFalliti.slice(0, 50) },
                compila: esitoTipo.compila || { destinatari: comp.length, inviati: 0, falliti: [] },
                risultati: esitoTipo.risultati || { destinatari: vis.length, inviati: 0, falliti: [] }
            };
            // un indirizzo puo fallire sia sull'email password sia su quella di invito: conta le
            // persone distinte, non i tentativi (il conteggio "non riusciti" mostrato all'utente)
            const fallitiDistinti = Array.from(new Set(falliti));
            return { ok: true, creati, inviati, falliti: fallitiDistinti, dettaglio };
        },

        async recuperaPassword(email) {
            try {
                const viaServizio = await this.inviaTramiteServizio(email, 'recupero');
                if (viaServizio) return viaServizio;
                await this.fb.authMod.sendPasswordResetEmail(this.auth, email);
                return { ok: true, viaEmail: true };
            } catch (e) { return { ok: false, msg: this.msgErrore(e) }; }
        },

        async cambiaPassword(email, nuova) {
            const controllo = Auth.validaPassword(nuova);
            if (controllo) return { ok: false, msg: controllo };
            try {
                await this.fb.authMod.updatePassword(this.auth.currentUser, nuova);
                return { ok: true };
            } catch (e) { return { ok: false, msg: this.msgErrore(e) }; }
        },

        esci() {
            this.fermaPresenza();
            this.sottoscrizioni.forEach(s => { try { s(); } catch (e) { } });
            this.sottoscrizioni = [];
            // invia subito le scritture ancora in coda (transazione) PRIMA di uscire
            if (this._timerFlush) { clearTimeout(this._timerFlush); this._timerFlush = null; }
            const eseguiSignOut = () => { try { this.fb.authMod.signOut(this.auth); } catch (e) { } };
            const chiudi = () => {
                this.pronto = false;
                this._sync = null;
                // attende le scritture in corso (es. la voce "Uscita" del registro)
                try { this.fb.fsMod.waitForPendingWrites(this.db).then(eseguiSignOut, eseguiSignOut); }
                catch (e) { eseguiSignOut(); }
            };
            Promise.resolve(this._flush()).then(chiudi, chiudi);
        },

        /* --- dati condivisi: un documento Firestore per archivio --- */
        _sync: null,
        archiviNonLetti: [],   // archivi che il server ha rifiutato in LETTURA
        archiviNonScritti: {}, // archivi che il server ha rifiutato in SCRITTURA, con il motivo
        _tentativi: {},        // tentativi di scrittura falliti per archivio
        // ruolo ed email arrivano da fuori perche' qui Auth.utenteCorrente NON e' ancora
        // valorizzato: viene impostato solo DOPO che questa promessa si e' risolta.
        avviaSync(ruolo, email) {
            // memoizzata: chiamate concorrenti condividono la stessa promessa
            if (!this._sync) {
                this._sync = this._eseguiSync(ruolo, email).catch(e => { this._sync = null; throw e; });
            }
            return this._sync;
        },
        async _eseguiSync(ruolo, email) {
            if (this.pronto) return;
            this.archiviNonLetti = [];
            const { doc, getDoc, setDoc, onSnapshot, serverTimestamp } = this.fb.fsMod;
            // gli utenti "solo sondaggio" possono leggere SOLO i documenti del sondaggio:
            // le regole Firestore negano gli altri archivi, quindi non vanno nemmeno richiesti
            // (altrimenti il permission-denied farebbe fallire tutta la sincronizzazione).
            // NB: qui NON si aggiunge eventiConfig. Le regole (FIREBASE-SETUP.md) concedono
            // archivio/{documento} al solo staff pieno: un "solo sondaggio" verrebbe respinto
            // e si vedrebbe l'avviso dei permessi a ogni accesso. Per abilitarlo agli Eventi
            // va prima cambiato il suo ruolo (la finestra "Gestisci accessi" lo segnala).
            const chiaviSync = eRuoloSoloSondaggio(ruolo)
                ? [CHIAVI.sondaggi, CHIAVI.sondaggiConfig].filter(k => this.DOC_SYNC[k])
                : Object.keys(this.DOC_SYNC);
            for (const chiave of chiaviSync) {
                const rif = doc(this.db, 'archivio', this.DOC_SYNC[chiave]);
                // Un singolo archivio non leggibile (regole Firestore non aggiornate dopo
                // l'aggiunta di un nuovo archivio) NON deve far fallire tutta la
                // sincronizzazione: prima bastava un permission-denied per lasciare
                // l'utente con i soli dati vecchi gia' presenti nel browser.
                let snap;
                try {
                    snap = await getDoc(rif);
                } catch (e) {
                    const codice = (e && e.code) || (e && e.message) || 'errore';
                    this.archiviNonLetti.push({ doc: this.DOC_SYNC[chiave], codice: codice, testo: this.DOC_SYNC[chiave] + ': ' + codice });
                    continue;
                }
                if (snap.exists() && typeof snap.data().json === 'string') {
                    localStorage.setItem(chiave, snap.data().json);
                    this._baseRemoto[chiave] = snap.data().json;
                } else if (!_senzaBootstrap(chiave)) {
                    // Configurazioni e presenze non si ripubblicano mai da una copia locale:
                    // se il documento sul server manca, una copia vecchia rimasta in un
                    // browser riporterebbe indietro dati gia' aggiornati altrove (il
                    // bootstrap scrive tutto, non fonde). Li crea il salvataggio vero.
                    // primo avvio del progetto: i dati locali fanno da base,
                    // ma gli incarichi dimostrativi non vengono caricati
                    let locale = localStorage.getItem(chiave);
                    if (locale && chiave === CHIAVI.incarichi) {
                        try {
                            const reali = JSON.parse(locale).filter(i => !(i.creato && i.creato.da === 'sistema (dati demo)'));
                            locale = reali.length ? JSON.stringify(reali) : null;
                        } catch (e) { locale = null; }
                    }
                    if (locale) {
                        // archivio/ruoli e scrivibile solo dall'amministratore (regole Firestore):
                        // un non-admin NON deve tentare questo bootstrap, altrimenti il permission-denied
                        // farebbe fallire tutta la sincronizzazione e lo bloccherebbe al login.
                        const sonoAdmin = ruolo === 'admin' || String(email || '').toLowerCase() === PROPRIETARIO;
                        if (!(chiave === CHIAVI.ruoli && !sonoAdmin)) {
                            try { await setDoc(rif, { json: locale, aggiornato: serverTimestamp(), da: 'bootstrap' }); this._baseRemoto[chiave] = locale; }
                            catch (e) { /* scrittura non consentita: si prosegue, i dati arrivano via onSnapshot */ }
                        }
                    }
                }
            }
            this.pronto = true;
            chiaviSync.forEach(chiave => {
                const rif = doc(this.db, 'archivio', this.DOC_SYNC[chiave]);
                const stacca = onSnapshot(rif, snap => {
                    if (!snap.exists()) return;
                    const remoto = snap.data().json;
                    if (typeof remoto !== 'string') return;
                    // Se ho modifiche locali non ancora inviate, le riporto SOPRA il
                    // nuovo remoto (fusione) invece di perderle sovrascrivendo tutto.
                    let nuovoLocale = remoto;
                    if (this._pendenti[chiave] != null) {
                        const forma = _formaDati(chiave);
                        nuovoLocale = _applicaDelta(remoto, _deltaDati(this._baseRemoto[chiave], this._pendenti[chiave], forma), forma);
                        this._pendenti[chiave] = nuovoLocale;
                    }
                    this._baseRemoto[chiave] = remoto;
                    if (nuovoLocale !== localStorage.getItem(chiave)) {
                        localStorage.setItem(chiave, nuovoLocale);
                        // niente ricarica dentro il wizard: si perderebbero i dati digitati
                        ridisegnaDaSync();
                    }
                }, () => { });
                this.sottoscrizioni.push(stacca);
            });
            // Se il server ha negato qualche archivio l'utente deve saperlo: prima restava
            // muto e sembrava semplicemente che una sezione "non ci fosse". Il messaggio
            // DICE QUALI archivi, altrimenti non si riesce a capire cosa correggere.
            if (this.archiviNonLetti.length) {
                console.warn('Archivi non leggibili:', this.archiviNonLetti.map(a => a.testo).join(' | '));
                const nomi = this.archiviNonLetti.map(a => nomeArchivio(a.doc)).join(', ');
                const soloPermessi = this.archiviNonLetti.every(a => a.codice === 'permission-denied');
                const msg = soloPermessi
                    ? 'Il server non consente a questa utenza di leggere: ' + nomi + '. Riferiscilo all\'amministratore (regole di sicurezza da aggiornare).'
                    : 'Non sono stati caricati: ' + nomi + '. Se il problema resta, riferiscilo all\'amministratore.';
                setTimeout(() => toast(msg, 'rosso'), 1500);
            }
        },

        // sincronizzazione coalescente: scritture ripetute sulla stessa chiave
        // (es. una modifica di massa) vengono unite in un'unica scrittura del
        // valore finale, cosi non si esaurisce la coda di scritture di Firestore
        _pendenti: {},
        _baseRemoto: {},   // ultimo valore remoto visto per chiave (base della fusione)
        _timerFlush: null,
        _erroreMostrato: {},   // ultimo avviso mostrato, per archivio
        sincronizza(chiave, valore) {
            if (!this.attivo || !this.pronto || !this.DOC_SYNC || !this.DOC_SYNC[chiave]) return;
            // gli utenti "solo sondaggio" possono scrivere UNICAMENTE le risposte del
            // sondaggio (e solo il ruolo "compila"): evita scritture negate dalle regole
            // (es. archivio/audit) che genererebbero errori e tentativi a vuoto in loop.
            const rc = Auth.ruoloCorrente ? Auth.ruoloCorrente() : null;
            if (rc && rc.soloSondaggio && !(rc.sondaggioRuolo === 'compila' && chiave === CHIAVI.sondaggi)) return;
            this._pendenti[chiave] = JSON.stringify(valore);
            if (this._timerFlush) return;
            this._timerFlush = setTimeout(() => this._flush(), 400);
        },
        // Scrive le modifiche in coda con una TRANSAZIONE che fonde per-record il
        // mio valore locale con lo stato remoto attuale: due utenti che salvano
        // record diversi non si sovrascrivono piu (niente perdita di dati).
        async _flush() {
            this._timerFlush = null;
            // La coda si svuota SOLO se si puo' davvero scrivere. Prima veniva svuotata
            // comunque e poi ci si fermava: le modifiche in attesa sparivano per sempre,
            // senza errore e senza un nuovo tentativo. Si riprova finche' la sessione e'
            // aperta; a utente uscito si smette, altrimenti si ritenterebbe all'infinito.
            if (!this.pronto) {
                const restano = Object.keys(this._pendenti).length > 0;
                const sessioneAperta = this.attivo && this.auth && this.auth.currentUser;
                if (restano && sessioneAperta) this._timerFlush = setTimeout(() => this._flush(), 2500);
                return;
            }
            const pendenti = this._pendenti;
            this._pendenti = {};
            const { doc, runTransaction, serverTimestamp } = this.fb.fsMod;
            const email = Auth.utenteCorrente ? Auth.utenteCorrente.email : 'sconosciuto';
            for (const chiave of Object.keys(pendenti)) {
                const rif = doc(this.db, 'archivio', this.DOC_SYNC[chiave]);
                const localStr = pendenti[chiave];
                const baseStr = this._baseRemoto[chiave];
                try {
                    const fuso = await runTransaction(this.db, async (tx) => {
                        const snap = await tx.get(rif);
                        const remoteStr = (snap.exists() && typeof snap.data().json === 'string') ? snap.data().json : null;
                        const merged = (remoteStr == null) ? localStr : _fondiDati(chiave, baseStr, localStr, remoteStr);
                        tx.set(rif, { json: merged, aggiornato: serverTimestamp(), da: email });
                        return merged;
                    });
                    this._baseRemoto[chiave] = fuso;
                    delete this.archiviNonScritti[this.DOC_SYNC[chiave]];
                    this._tentativi[chiave] = 0;
                    if (fuso !== localStorage.getItem(chiave)) {
                        localStorage.setItem(chiave, fuso);
                        ridisegnaDaSync();
                    }
                } catch (e) {
                    const nomeDoc = this.DOC_SYNC[chiave];
                    const codice = (e && e.code) || (e && e.message) || 'errore';
                    console.error('Sincronizzazione non riuscita (' + nomeDoc + '):', e);
                    // si tiene traccia dell'archivio e del MOTIVO: senza, un rifiuto del
                    // server restava un messaggio generico e non si capiva cosa correggere
                    this.archiviNonScritti[nomeDoc] = codice;
                    this._tentativi[chiave] = (this._tentativi[chiave] || 0) + 1;
                    // "Rinuncia" vuol dire SOLO smettere di riprovare da soli a raffica: il
                    // valore resta SEMPRE in coda, altrimenti una rete ballerina (cinque
                    // tentativi a vuoto) farebbe sparire la modifica al rientro successivo.
                    // Con una scrittura andata a buon fine la coda riparte da sola.
                    if (this._pendenti[chiave] == null) this._pendenti[chiave] = localStr;
                    const rinuncia = codice === 'permission-denied' || this._tentativi[chiave] >= 5;
                    if (!rinuncia && !this._timerFlush && this.pronto) {
                        this._timerFlush = setTimeout(() => this._flush(), 2500);
                    }
                    // avviso per ARCHIVIO, non uno solo per tutti: due archivi salvati
                    // insieme (presenze e registro attivita) si zittivano a vicenda
                    if (!this._erroreMostrato[nomeDoc]) {
                        this._erroreMostrato[nomeDoc] = true;
                        const coda = ' La modifica resta su questo computer e verrà reinviata al prossimo salvataggio.';
                        toast(!rinuncia
                            ? 'Salvataggio di "' + nomeArchivio(nomeDoc) + '" non ancora condiviso, nuovo tentativo in corso.'
                            : (codice === 'permission-denied'
                                ? 'Il server ha RIFIUTATO il salvataggio di "' + nomeArchivio(nomeDoc) + '" (permessi). Riferiscilo all\'amministratore.' + coda
                                : 'Salvataggio di "' + nomeArchivio(nomeDoc) + '" non riuscito dopo più tentativi (' + codice + ').' + coda), 'rosso');
                        setTimeout(() => { this._erroreMostrato[nomeDoc] = false; }, 5000);
                    }
                }
            }
        },

        /* --- Presenza: mostra sempre gli utenti connessi ---
           Ogni scheda aggiorna il proprio "ultimoAccesso" a intervalli (heartbeat,
           l'unico campo che le regole consentono di aggiornare da soli) e ascolta
           l'intera collezione "utenti" in tempo reale: e "connesso" chi ha un
           battito negli ultimi ~2 minuti. Nessuna modifica alle regole Firestore. */
        _presenzaAvviata: false,
        _presenzaTimer: null,
        _presenzaPubTimer: null,
        _presenzaTick: 0,
        _visibHandler: null,
        _pageHideHandler: null,
        _pageShowHandler: null,
        _presenzaUltima: [],
        _msgMostrati: null,
        _inbox: [],
        _msgNonLetti: 0,
        _primoSmista: false,
        _presenzaRef() { const { doc } = this.fb.fsMod; return doc(this.db, 'archivio', 'presenza'); },
        _msgRef(email) { const { doc } = this.fb.fsMod; return doc(this.db, 'messaggi', String(email).toLowerCase()); },
        avviaPresenza() {
            if (!this.attivo || !this.pronto || this._presenzaAvviata) return;
            // gli utenti "solo sondaggio" (esterni) non vedono la presenza dello staff
            const rc = Auth.ruoloCorrente ? Auth.ruoloCorrente() : null;
            if (rc && rc.soloSondaggio) return;
            const email = Auth.utenteCorrente ? Auth.utenteCorrente.email : null;
            if (!email) return;
            // stato messaggi per QUESTO utente: su browser condiviso l'utente successivo non deve
            // vedere i messaggi del precedente. Dedup per id (persistito per utente), non per timestamp.
            this._inbox = []; this._msgNonLetti = 0;
            this._msgMostrati = new Set(this._caricaSeen(email));
            this._primoSmista = true;
            this._presenzaAvviata = true;
            const { onSnapshot } = this.fb.fsMod;
            // heartbeat 30s (solo a scheda visibile); ~ogni 5 min rinfresca anche
            // "ultimoAccesso" (visto come Ultimo accesso nella vista Utenti). La reattivita
            // vera arriva dagli eventi (naviga, apertura/chiusura editor, ritorno visibile).
            const battito = () => {
                if (typeof document !== 'undefined' && document.hidden) return;
                this._presenzaTick++;
                if (this._presenzaTick % 10 === 0) this.salvaUtente(email, { ultimoAccesso: Date.now() }).catch(() => { });
                this.pubblicaPresenza();
            };
            this.pubblicaPresenza();
            this.salvaUtente(email, { ultimoAccesso: Date.now() }).catch(() => { });
            this._presenzaTimer = setInterval(battito, 30000);
            this._visibHandler = () => { if (!document.hidden) this.pubblicaPresenza(); };
            document.addEventListener('visibilitychange', this._visibHandler);
            // pagehide: scompari subito dagli altri (lapide) ma NON smontare, cosi al ritorno da
            // bfcache la presenza riprende; pageshow ri-pubblica il proprio slot.
            this._pageHideHandler = () => { this._scriviLapide(); };
            window.addEventListener('pagehide', this._pageHideHandler);
            this._pageShowHandler = () => { if (this._presenzaAvviata) this.pubblicaPresenza(); };
            window.addEventListener('pageshow', this._pageShowHandler);
            const emailKey = email.toLowerCase();
            const stacca = onSnapshot(this._presenzaRef(), snap => {
                const dati = (snap && snap.data && snap.data()) || {};
                const stati = dati.stati || {};
                const ora = Date.now();
                const connessi = Object.keys(stati).map(k => Object.assign({ email: k }, stati[k]))
                    .filter(s => s && s.ts && (ora - s.ts) < 90000)
                    .sort((a, b) => String(a.nome || a.email).localeCompare(String(b.nome || b.email), 'it'));
                Cloud._presenzaUltima = connessi;
                aggiornaPresenza(connessi);
                // posta di ripiego: messaggi recapitati qui quando il documento privato del
                // destinatario non era scrivibile (regole non aggiornate). Si mostrano subito
                // e si toglie SOLO cio che si e ricevuto (arrayRemove), cosi un messaggio
                // arrivato nel frattempo non viene cancellato per sbaglio.
                const inArrivo = ((dati.posta || {})[emailKey]) || [];
                if (inArrivo.length) {
                    Cloud._smistaMessaggi(inArrivo, emailKey, false);
                    try {
                        const { setDoc, arrayRemove } = Cloud.fb.fsMod;
                        setDoc(Cloud._presenzaRef(), { posta: { [emailKey]: arrayRemove.apply(null, inArrivo) } }, { merge: true }).catch(() => { });
                    } catch (e) { }
                }
            }, () => { });
            this.sottoscrizioni.push(stacca);
            // messaggi privati: ognuno legge SOLO il proprio documento messaggi/<email> (le regole
            // Firestore lo consentono al solo destinatario), cosi le conversazioni non sono visibili a tutti.
            const staccaMsg = onSnapshot(this._msgRef(emailKey), snap => {
                const lista = (((snap && snap.data && snap.data()) || {}).lista) || [];
                const primoGiro = Cloud._primoSmista; Cloud._primoSmista = false;
                Cloud._smistaMessaggi(lista, emailKey, primoGiro);
                if (lista.length > 60) Cloud._potaMessaggi(emailKey);
            }, () => { });
            this.sottoscrizioni.push(staccaMsg);
            // pulizia una tantum: i messaggi storici stavano nel doc presenza condiviso (leggibile
            // da tutto lo staff). Ora sono privati per destinatario: rimuovo il vecchio campo cosi
            // non resta piu una copia leggibile da tutti. Idempotente (best-effort).
            try { const { setDoc, deleteField } = this.fb.fsMod; setDoc(this._presenzaRef(), { messaggi: deleteField() }, { merge: true }).catch(() => { }); } catch (e) { }
        },
        // pubblica il proprio slot di presenza; debounce per accorpare naviga+focus+battito
        pubblicaPresenza() {
            if (!this._presenzaAvviata || !this.attivo || !this.pronto) return;
            if (this._presenzaPubTimer) return;
            this._presenzaPubTimer = setTimeout(() => {
                this._presenzaPubTimer = null;
                const u = Auth.utenteCorrente; if (!u || !u.email) return;
                try {
                    const { setDoc } = this.fb.fsMod;
                    const slot = { nome: u.nome || u.email, ts: Date.now(), vista: presenzaVistaCorrente(), modifica: statoModifica || null };
                    setDoc(this._presenzaRef(), { stati: { [u.email.toLowerCase()]: slot } }, { merge: true }).catch(() => { });
                } catch (e) { }
            }, 250);
        },
        fermaPresenza() {
            this._presenzaAvviata = false;
            if (this._presenzaTimer) { clearInterval(this._presenzaTimer); this._presenzaTimer = null; }
            if (this._presenzaPubTimer) { clearTimeout(this._presenzaPubTimer); this._presenzaPubTimer = null; }
            if (this._visibHandler) { try { document.removeEventListener('visibilitychange', this._visibHandler); } catch (e) { } this._visibHandler = null; }
            if (this._pageHideHandler) { try { window.removeEventListener('pagehide', this._pageHideHandler); } catch (e) { } this._pageHideHandler = null; }
            if (this._pageShowHandler) { try { window.removeEventListener('pageshow', this._pageShowHandler); } catch (e) { } this._pageShowHandler = null; }
            this._presenzaUltima = [];
            // svuota i messaggi in memoria e i popup aperti: l'utente successivo su questo browser non deve vederli
            this._inbox = []; this._msgNonLetti = 0; this._msgMostrati = null;
            try { const area = document.getElementById('msg-popup-area'); if (area) area.innerHTML = ''; } catch (e) { }
            this._scriviLapide();
            aggiornaPresenza([]);
        },
        // lapide: ts=0 mi fa sparire subito dagli altri, senza cancellare la chiave
        _scriviLapide() {
            const u = Auth.utenteCorrente;
            if (!u || !u.email || !this.attivo || !this.pronto) return;
            try { const { setDoc } = this.fb.fsMod; setDoc(this._presenzaRef(), { stati: { [u.email.toLowerCase()]: { nome: u.nome || u.email, ts: 0, vista: null, modifica: null } } }, { merge: true }).catch(() => { }); } catch (e) { }
        },
        // notifica: popup con risposta per i messaggi nuovi a me destinati. Dedup per ID
        // (persistito per utente), non per timestamp: cosi non si perdono messaggi con clock
        // sfasati o su browser condiviso, e l'utente successivo non eredita lo stato del precedente.
        // silenzioso = primo giro dopo il login: il pregresso si segna senza popup, ma i messaggi
        // degli ultimi 10 minuti si mostrano comunque (inviati un attimo prima dell'accesso).
        _smistaMessaggi(messaggi, mia, silenzioso) {
            if (!mia) return;
            if (!this._msgMostrati) this._msgMostrati = new Set(this._caricaSeen(mia));
            let cambiato = false, nuovi = 0;
            const ora = Date.now();
            (messaggi || []).forEach(m => {
                if (!m || !m.id || String(m.a || '').toLowerCase() !== mia) return;
                if (this._msgMostrati.has(m.id)) return;
                this._msgMostrati.add(m.id); cambiato = true;
                if (silenzioso && !(m.ts && (ora - m.ts) < 600000)) return;
                this._inbox.unshift(m); this._inbox = this._inbox.slice(0, 20);
                this._msgNonLetti++; nuovi++;
                mostraPopupMessaggio(m);
            });
            if (cambiato) this._salvaSeen(mia);
            // il contatore "Messaggi" nella sidebar si aggiorna subito, non al prossimo battito
            if (nuovi) aggiornaPresenza(this._presenzaUltima || []);
        },
        _caricaSeen(email) { try { const a = JSON.parse(localStorage.getItem('rvArea.msgSeen.' + String(email).toLowerCase()) || '[]'); return Array.isArray(a) ? a : []; } catch (e) { return []; } },
        _salvaSeen(email) { try { localStorage.setItem('rvArea.msgSeen.' + String(email).toLowerCase(), JSON.stringify(Array.from(this._msgMostrati).slice(-80))); } catch (e) { } },
        async inviaMessaggio(aEmail, testo) {
            const u = Auth.utenteCorrente; if (!u || !u.email) return false;
            const t = String(testo || '').trim().slice(0, 500);
            const dest = String(aEmail || '').toLowerCase();
            if (!t || !dest) return false;
            const { setDoc, arrayUnion } = this.fb.fsMod;
            const msg = { id: 'm_' + uid(), da: u.email.toLowerCase(), daNome: u.nome || u.email, a: dest, testo: t, ts: Date.now() };
            // recapito nel documento privato del destinatario (che solo lui puo leggere)
            try {
                await setDoc(this._msgRef(dest), { lista: arrayUnion(msg) }, { merge: true });
                return true;
            } catch (e) { }
            // ripiego: se le regole Firestore pubblicate non hanno ancora il blocco
            // messaggi/{email} la scrittura sopra viene rifiutata e il messaggio non
            // partirebbe mai. Lo scomparto "posta" del documento di presenza e coperto
            // dalla regola base archivio/* (staff), quindi funziona con qualunque
            // installazione; il destinatario lo svuota appena riceve. Meno riservato
            // del documento privato, ma il recapito e garantito.
            try {
                await setDoc(this._presenzaRef(), { posta: { [dest]: arrayUnion(msg) } }, { merge: true });
                return true;
            } catch (e) { return false; }
        },
        // potatura opportunistica della PROPRIA casella (il mittente non puo leggere quella altrui):
        // se i messaggi superano ~60, tiene gli ultimi 40 (transazione con retry)
        async _potaMessaggi(email) {
            const e = String(email || (Auth.utenteCorrente && Auth.utenteCorrente.email) || '').toLowerCase();
            if (!e) return;
            try {
                const { runTransaction } = this.fb.fsMod;
                const ref = this._msgRef(e);
                await runTransaction(this.db, async tx => {
                    const s = await tx.get(ref);
                    const arr = (s.exists() && s.data() && s.data().lista) || [];
                    if (arr.length > 60) tx.update(ref, { lista: arr.slice(-40) });
                });
            } catch (e2) { }
        },

        /* --- gestione utenti abilitati (Firestore, solo admin) --- */
        async listaUtenti() {
            const { collection, getDocs } = this.fb.fsMod;
            const snap = await getDocs(collection(this.db, 'utenti'));
            const out = [];
            // l'identita' vera e' l'ID del documento (l'indirizzo con cui si entra): va messo
            // DOPO i campi, altrimenti un eventuale campo "email" dentro il documento lo
            // sostituirebbe e si finirebbe per abilitare un indirizzo diverso da quello reale
            snap.forEach(d => out.push({ ...d.data(), email: d.id }));
            return out.sort((a, b) => a.email.localeCompare(b.email));
        },
        async salvaUtente(email, dati) {
            const { doc, setDoc } = this.fb.fsMod;
            await setDoc(doc(this.db, 'utenti', email.toLowerCase()), dati, { merge: true });
        },
        /* Eliminazione definitiva dell'utente: rimuove il documento dalla collezione
           "utenti". Da quel momento l'indirizzo non supera piu abilitato() e perde ogni
           accesso. L'account Firebase Authentication (se mai attivato) non e toccabile
           dal client: eventuali residui si rimuovono da Authentication > Users. */
        async eliminaUtente(email) {
            const { doc, deleteDoc } = this.fb.fsMod;
            await deleteDoc(doc(this.db, 'utenti', email.toLowerCase()));
        },

        msgErrore(e) {
            const codice = (e && e.code) || '';
            if (codice.includes('invalid-credential') || codice.includes('wrong-password') || codice.includes('user-not-found')) return 'Credenziali non valide.';
            if (codice.includes('too-many-requests')) return 'Troppi tentativi: riprova tra qualche minuto.';
            if (codice.includes('invalid-email')) return 'Indirizzo email non valido.';
            if (codice.includes('requires-recent-login')) return 'Per cambiare la password esegui di nuovo l\'accesso.';
            if (codice.includes('network')) return 'Problema di rete: riprova.';
            return 'Operazione non riuscita' + (codice ? ' (' + codice + ')' : '') + '.';
        }
    };

    /* =========================================================
       MODELLI PDF (le lettere di incarico originali, archiviate
       su Firestore a blocchi e usate per generare i PDF compilati)
    ========================================================= */
    const Modelli = {
        TIPI: { triennale: 'Revisione legale triennale', volontaria: 'Revisione limitata volontaria annuale' },
        _cache: {},

        _b64DaBytes(bytes) {
            let bin = '';
            for (let i = 0; i < bytes.length; i += 0x8000) {
                bin += String.fromCharCode.apply(null, bytes.subarray(i, i + 0x8000));
            }
            return btoa(bin);
        },
        _bytesDaB64(b64) {
            const bin = atob(b64);
            const bytes = new Uint8Array(bin.length);
            for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
            return bytes;
        },

        // id di un blocco: con versione (nuovo schema) o legacy (primo schema)
        _idChunk(tipo, versione, i) {
            return versione ? tipo + '_' + versione + '_' + i : tipo + '_' + i;
        },

        async carica(tipo, file) {
            if (!Cloud.attivo || !Cloud.pronto) throw new Error('I modelli PDF richiedono l\'accesso al cloud condiviso.');
            const bytes = new Uint8Array(await file.arrayBuffer());
            if (bytes.length > 9 * 1024 * 1024) throw new Error('File troppo grande (massimo 9 MB).');
            const b64 = this._b64DaBytes(bytes);
            const DIM = 750000; // caratteri base64 per documento Firestore (limite 1 MB)
            const chunks = Math.ceil(b64.length / DIM);
            const { doc, setDoc, deleteDoc, serverTimestamp } = Cloud.fb.fsMod;
            const vecchioMeta = await this.info(tipo);
            // versione univoca: i blocchi nuovi non sovrascrivono i vecchi, quindi
            // un'interruzione a meta upload lascia intatto il modello attualmente valido
            const versione = 'v' + (vecchioMeta && vecchioMeta.versione ? (parseInt(String(vecchioMeta.versione).slice(1)) || 0) + 1 : 1) + '_' + uid().slice(-6);
            for (let i = 0; i < chunks; i++) {
                await setDoc(doc(Cloud.db, 'modelli', this._idChunk(tipo, versione, i)), { b64: b64.slice(i * DIM, (i + 1) * DIM) });
            }
            // il meta, scritto per ultimo, e cio che rende "attivo" il nuovo modello
            await setDoc(doc(Cloud.db, 'modelli', tipo + '_meta'), {
                nome: file.name, dimensione: bytes.length, chunks, versione,
                aggiornato: serverTimestamp(), da: Auth.utenteCorrente.email
            });
            this._cache[tipo] = { bytes, dimensione: bytes.length, versione };
            // solo ora si rimuovono i blocchi della versione precedente (orfani innocui se falliscono)
            if (vecchioMeta) {
                for (let i = 0; i < (vecchioMeta.chunks || 0); i++) {
                    try { await deleteDoc(doc(Cloud.db, 'modelli', this._idChunk(tipo, vecchioMeta.versione, i))); } catch (e) { }
                }
            }
            Audit.registra(Auth.utenteCorrente, 'Modello lettera caricato', 'sistema', tipo, null,
                Modelli.TIPI[tipo] + ': ' + file.name + ' (' + Math.round(bytes.length / 1024) + ' KB, ' + chunks + ' blocchi)');
        },

        async info(tipo) {
            if (!Cloud.attivo || !Cloud.pronto) return null;
            const { doc, getDoc } = Cloud.fb.fsMod;
            const snap = await getDoc(doc(Cloud.db, 'modelli', tipo + '_meta'));
            return snap.exists() ? snap.data() : null;
        },

        async leggi(tipo) {
            const meta = await this.info(tipo);
            if (!meta) return null;
            // la cache vale solo se il modello remoto non e stato sostituito
            const inCache = this._cache[tipo];
            if (inCache && inCache.dimensione === meta.dimensione && inCache.versione === meta.versione) return inCache.bytes;
            const { doc, getDoc } = Cloud.fb.fsMod;
            let b64 = '';
            for (let i = 0; i < meta.chunks; i++) {
                const snap = await getDoc(doc(Cloud.db, 'modelli', this._idChunk(tipo, meta.versione, i)));
                if (!snap.exists()) throw new Error('Modello incompleto su Firestore: ricaricalo da Dati e backup.');
                b64 += snap.data().b64;
            }
            const bytes = this._bytesDaB64(b64);
            if (bytes.length !== meta.dimensione) throw new Error('Modello non coerente su Firestore: ricaricalo da Dati e backup.');
            this._cache[tipo] = { bytes, dimensione: bytes.length, versione: meta.versione };
            return bytes;
        }
    };

    /* =========================================================
       FIRME GRAFICHE dei responsabili di incarico: l'immagine
       autografa inserita nel PDF della lettera sotto REVILAW.
       Un documento per responsabile in archivio/ (scrivibile da
       tutto lo staff), con copia nel browser come riserva.
    ========================================================= */
    const Firme = {
        _cache: {},
        _chiave(resp) {
            return String(resp || '').trim().toLowerCase()
                .normalize('NFD').replace(/\p{M}+/gu, '')
                .replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '') || 'senza_nome';
        },
        async leggi(resp) {
            const k = this._chiave(resp);
            if (k in this._cache) return this._cache[k];
            let dataUrl = null;
            if (Cloud.attivo && Cloud.pronto) {
                try {
                    const { doc, getDoc } = Cloud.fb.fsMod;
                    const snap = await getDoc(doc(Cloud.db, 'archivio', 'firmaResp_' + k));
                    if (snap.exists()) dataUrl = snap.data().dataUrl || null;
                } catch (e) { console.warn('Firma non leggibile dal cloud:', e); }
            }
            if (!dataUrl) { try { dataUrl = localStorage.getItem('rvArea.firma.' + k) || null; } catch (e) { } }
            this._cache[k] = dataUrl;
            return dataUrl;
        },
        async salva(resp, dataUrl) {
            const k = this._chiave(resp);
            if (Cloud.attivo && Cloud.pronto) {
                const { doc, setDoc, serverTimestamp } = Cloud.fb.fsMod;
                await setDoc(doc(Cloud.db, 'archivio', 'firmaResp_' + k), {
                    dataUrl, responsabile: String(resp || ''),
                    aggiornato: serverTimestamp(), da: Auth.utenteCorrente.email
                });
            }
            try { localStorage.setItem('rvArea.firma.' + k, dataUrl); } catch (e) { }
            this._cache[k] = dataUrl;
            Audit.registra(Auth.utenteCorrente, 'Firma grafica del responsabile aggiornata', 'sistema', k, null, String(resp || ''));
        }
    };

    /* =========================================================
       CALCOLO COMPENSO (stessa logica del simulatore compensi)
    ========================================================= */
    const SETTORI = [
        { val: 1.0, nome: 'Produzione / Altro (standard)' },
        { val: 0.5, nome: 'Immobiliare (-50%)' },
        { val: 0.85, nome: 'Commerciale / Servizi (-15%)' },
        { val: 1.1, nome: 'Lavori su commessa (+10%)' }
    ];
    const RISCHI = [
        { val: 1.0, nome: 'Basso (standard)' },
        { val: 1.2, nome: 'Moderato (+20%)' },
        { val: 1.4, nome: 'Alto (+40%)' }
    ];

    function oreBaseDaMedia(media) {
        if (media <= 0) return 0;
        if (media <= 2000000) return 80;
        if (media <= 5000000) return 130;
        if (media <= 7000000) return 160;
        if (media <= 10000000) return 180;
        if (media <= 15000000) return 220;
        if (media <= 20000000) return 250;
        if (media <= 30000000) return 310;
        if (media <= 40000000) return 360;
        return 400;
    }

    function calcolaCompenso(p) {
        const attivo = p.attivo || 0, ricavi = p.ricavi || 0;
        const media = (attivo + ricavi) / 2;
        const oreBase = oreBaseDaMedia(media);
        const oltre50M = media > 50000000;
        const extra50 = oltre50M ? Math.max(0, Math.round(p.extra50 || 0)) : 0;
        const orePlus = Math.max(0, Math.round(p.orePlus || 0));
        const oreBaseEff = oreBase + orePlus + extra50;
        const oreCorrette = oreBaseEff * (p.moltSettore || 1) * (p.moltRischio || 1);
        const oreLegale = Math.ceil(oreCorrette);
        const extraRicorrenti = (p.hConsolidato || 0) + (p.hIfrs || 0) + (p.hIt || 0) + (p.hAltro || 0);
        const extraSoloAnno1 = (p.hVolontaria || 0) + (p.hPrimoAnno || 0);
        const oreAnno1 = oreLegale + extraRicorrenti + extraSoloAnno1;
        const oreAnni23 = oreLegale + extraRicorrenti;
        const tariffa = p.tariffa || 0;
        return {
            media, oreBase, oltre50M, extra50, orePlus, oreBaseEff, oreCorrette,
            oreLegale, extraRicorrenti, extraSoloAnno1, oreAnno1, oreAnni23, tariffa,
            compensoAnno1: oreAnno1 * tariffa,
            compensoAnni23: oreAnni23 * tariffa
        };
    }

    /* Ore CONCORDATE: vengono dal calcolo del compenso fatto nel wizard, dove chi segue
       l'incarico ha scelto settore e rischio e ha visto il risultato prima di salvarlo.
       Sono queste, e solo queste, che finiscono nella proposta di incarico e nel PDF.
       La revisione volontaria vale un esercizio solo (ore anno 1), la legale va a regime. */
    function oreDaCalcolo(inc) {
        const c = inc && inc.calc;
        if (!c) return 0;
        const primo = c.oreAnno1 || 0;
        return inc.tipo === 'volontaria' ? primo : (c.oreAnni23 || primo || 0);
    }

    /* Ore STIMATE per l'analisi (report): il calcolo del wizard se c'e', altrimenti la stima
       ricavata dai bilanci caricati (inc.stima). La stima resta fuori dalle lettere: un numero
       calcolato in blocco con i correttivi predefiniti non puo' finire in un documento
       contrattuale al posto del trattino da compilare.
       Con l'anno si distingue il primo esercizio (ore piu' alte) dal regime: senza, il primo
       anno sembrerebbe pagato meglio di quanto e'. Torna 0 = ore non stimabili. */
    function oreStimatePerAnno(inc, anno) {
        if (!inc) return 0;
        const c = inc.calc, haCalc = c && (c.oreAnni23 || c.oreAnno1);
        const f = haCalc ? c : (inc.stima || null);
        if (!f) return 0;
        const a1 = f.oreAnno1 || 0, regime = f.oreAnni23 || a1 || 0;
        if (inc.tipo === 'volontaria') return a1;
        const primo = inc.dataInizio ? Number(String(inc.dataInizio).slice(0, 4)) : null;
        return (anno && primo && anno === primo) ? (a1 || regime) : regime;
    }

    /* =========================================================
       INCARICHI
    ========================================================= */
    const Incarichi = {
        tutti() { return Store.leggi(CHIAVI.incarichi, []); },
        // gli incarichi che l'utente collegato PUO' vedere (filtro per regione del ruolo).
        // Usare questo nelle viste; tutti() resta per storage, import, backup e integrita' dati.
        visibili() {
            const reg = Auth.regioniConsentite();
            const tutti = this.tutti();
            if (!reg) return tutti;
            return tutti.filter(i => reg.includes(chiaveRegione(i.regione || '')));
        },
        salva(lista) { Store.scrivi(CHIAVI.incarichi, lista); },
        trova(id) { return this.tutti().find(i => i.id === id) || null; },

        crea(dati, utente) {
            const lista = this.tutti();
            const nuovo = {
                id: uid(), stato: 'attivo', ...dati,
                creato: { da: utente.nome + ' <' + utente.email + '>', il: Date.now() },
                modificato: null
            };
            lista.push(nuovo);
            this.salva(lista);
            Audit.registra(utente, 'Nuovo incarico', 'incarico', nuovo.id, nuovo.cliente,
                Audit.confronta(null, nuovo, CAMPI_TRACCIATI));
            return nuovo;
        },

        aggiorna(id, dati, utente, azione) {
            const lista = this.tutti();
            const idx = lista.findIndex(i => i.id === id);
            if (idx < 0) return null;
            const prima = JSON.parse(JSON.stringify(lista[idx]));
            const dopo = { ...lista[idx], ...dati, modificato: { da: utente.nome + ' <' + utente.email + '>', il: Date.now() } };
            lista[idx] = dopo;
            this.salva(lista);
            const diff = Audit.confronta(prima, dopo, CAMPI_TRACCIATI);
            Audit.registra(utente, azione || 'Modifica incarico', 'incarico', id, dopo.cliente, diff.length ? diff : null);
            return dopo;
        },

        /* Eliminazione definitiva. Toglie l'incarico e con lui i dati che vivono attaccati
           al suo id e che altrimenti resterebbero orfani in archivio: stati delle rate,
           rimborsi spese (entrambi con chiave "<id incarico>|...") e allerte aperte.
           Il registro modifiche NON si tocca: dell'incarico eliminato deve restare traccia. */
        elimina(id, utente) {
            const lista = this.tutti();
            const inc = lista.find(i => i.id === id);
            if (!inc) return null;
            this.salva(lista.filter(i => i.id !== id));
            const prefisso = id + '|';
            const ripulisci = chiave => {
                const mappa = Store.leggi(chiave, {}) || {};
                const tolte = Object.keys(mappa).filter(k => k.indexOf(prefisso) === 0);
                if (!tolte.length) return 0;
                tolte.forEach(k => { delete mappa[k]; });
                Store.scrivi(chiave, mappa);
                return tolte.length;
            };
            const rate = ripulisci(CHIAVI.fatture);
            const rimborsi = ripulisci(CHIAVI.rimborsi);
            const allerte = Allerte.tutte();
            const allerteTolte = allerte.filter(a => a.incaricoId === id).length;
            if (allerteTolte) Allerte.salva(allerte.filter(a => a.incaricoId !== id));
            const coda = [
                rate ? rate + (rate === 1 ? ' stato rata' : ' stati rata') : '',
                rimborsi ? rimborsi + (rimborsi === 1 ? ' rimborso spese' : ' rimborsi spese') : '',
                allerteTolte ? allerteTolte + (allerteTolte === 1 ? ' allerta' : ' allerte') : ''
            ].filter(Boolean).join(', ');
            Audit.registra(utente, 'Eliminazione incarico', 'incarico', id, inc.cliente,
                'Incarico rimosso definitivamente' + (coda ? ' insieme a: ' + coda : ''));
            return inc;
        },

        // congela il calcolo del compenso: i valori concordati non cambiano piu
        congela(id, utente) {
            const lista = this.tutti();
            const idx = lista.findIndex(i => i.id === id);
            if (idx < 0) return null;
            lista[idx].calcoloCongelato = true;
            lista[idx].congelamento = { da: utente.nome + ' <' + utente.email + '>', il: Date.now() };
            this.salva(lista);
            Audit.registra(utente, 'Calcolo congelato', 'incarico', id, lista[idx].cliente,
                'Compenso e ore bloccati alla stampa del mandato');
            return lista[idx];
        },

        // sblocca il calcolo: richiede un messaggio di allerta al titolare
        scongela(id, utente, messaggio) {
            const lista = this.tutti();
            const idx = lista.findIndex(i => i.id === id);
            if (idx < 0) return null;
            const inc = lista[idx];
            inc.calcoloCongelato = false;
            inc.congelamento = null;
            this.salva(lista);
            Allerte.aggiungi({
                tipo: 'sblocco-calcolo', incaricoId: id, cliente: inc.cliente,
                da: utente.nome + ' <' + utente.email + '>', messaggio: messaggio
            });
            Audit.registra(utente, 'Allerta: sblocco calcolo congelato', 'incarico', id, inc.cliente,
                [{ campo: 'Messaggio di allerta', prima: '', dopo: messaggio }]);
            return inc;
        },

        // termina l'incarico: passa allo stato "cessato" (mostrato come "terminato") e finisce nella sezione dedicata
        termina(id, utente) {
            const lista = this.tutti();
            const idx = lista.findIndex(i => i.id === id);
            if (idx < 0) return null;
            const inc = lista[idx];
            const prima = inc.stato || 'attivo';
            inc.stato = 'cessato';
            inc.terminato = { da: utente.nome + ' <' + utente.email + '>', il: Date.now() };
            inc.modificato = { da: utente.nome + ' <' + utente.email + '>', il: Date.now() };
            this.salva(lista);
            Audit.registra(utente, 'Incarico terminato', 'incarico', id, inc.cliente, [{ campo: 'Stato', prima: prima, dopo: 'terminato' }]);
            return inc;
        },

        /* Dimissioni dall'incarico: il revisore si dimette a una certa data. L'incarico esce
           dall'elenco degli attivi e finisce nella scheda "Dismessi" (riattivabile). */
        dimetti(id, dataDimissioni, utente) {
            const lista = this.tutti();
            const idx = lista.findIndex(i => i.id === id);
            if (idx < 0) return null;
            const inc = lista[idx];
            const prima = inc.stato || 'attivo';
            inc.stato = 'dimesso';
            inc.dimissioni = { data: dataDimissioni || null, da: utente.nome + ' <' + utente.email + '>', il: Date.now() };
            inc.modificato = { da: utente.nome + ' <' + utente.email + '>', il: Date.now() };
            this.salva(lista);
            Audit.registra(utente, 'Dimissioni dall\'incarico', 'incarico', id, inc.cliente,
                [{ campo: 'Stato', prima: prima, dopo: 'dimesso' }].concat(dataDimissioni ? [{ campo: 'Data dimissioni', prima: '', dopo: fmtData(dataDimissioni) }] : []));
            return inc;
        },

        // conferma una proposta: l'incarico diventa attivo e da questo momento entra
        // nei totali di compensi e fatturazione
        conferma(id, utente) {
            const lista = this.tutti();
            const idx = lista.findIndex(i => i.id === id);
            if (idx < 0) return null;
            const inc = lista[idx];
            inc.stato = 'attivo';
            inc.confermato = { da: utente.nome + ' <' + utente.email + '>', il: Date.now() };
            inc.modificato = { da: utente.nome + ' <' + utente.email + '>', il: Date.now() };
            this.salva(lista);
            Audit.registra(utente, 'Incarico confermato', 'incarico', id, inc.cliente, [{ campo: 'Stato', prima: 'proposta', dopo: 'attivo' }]);
            return inc;
        },

        // proposta non accettata dal cliente: esce dalle proposte in attesa di conferma
        // e finisce nella scheda "Non accettati" della sezione Incarichi
        nonAccetta(id, utente, nota) {
            const lista = this.tutti();
            const idx = lista.findIndex(i => i.id === id);
            if (idx < 0) return null;
            const inc = lista[idx];
            const prima = inc.stato || 'attivo';
            inc.stato = 'nonAccettato';
            inc.nonAccettato = { da: utente.nome + ' <' + utente.email + '>', il: Date.now(), nota: nota || '' };
            inc.modificato = { da: utente.nome + ' <' + utente.email + '>', il: Date.now() };
            this.salva(lista);
            Audit.registra(utente, 'Incarico non accettato', 'incarico', id, inc.cliente,
                [{ campo: 'Stato', prima: prima, dopo: 'non accettato' }].concat(nota ? [{ campo: 'Motivo', prima: '', dopo: nota }] : []));
            return inc;
        },

        // riporta in proposta un incarico non accettato: cosi' lo si puo' modificare,
        // rigenerare il PDF della lettera e ripetere la fase di conferma
        riproponi(id, utente) {
            const lista = this.tutti();
            const idx = lista.findIndex(i => i.id === id);
            if (idx < 0) return null;
            const inc = lista[idx];
            inc.stato = 'proposta';
            inc.nonAccettato = null;
            inc.confermato = null;
            inc.modificato = { da: utente.nome + ' <' + utente.email + '>', il: Date.now() };
            this.salva(lista);
            Audit.registra(utente, 'Incarico riportato in proposta', 'incarico', id, inc.cliente,
                [{ campo: 'Stato', prima: 'non accettato', dopo: 'proposta' }]);
            return inc;
        },

        // riattiva un incarico terminato o dimesso: torna attivo e rientra nell'elenco principale
        riattiva(id, utente) {
            const lista = this.tutti();
            const idx = lista.findIndex(i => i.id === id);
            if (idx < 0) return null;
            const inc = lista[idx];
            const prima = inc.stato === 'dimesso' ? 'dimesso' : 'terminato';
            inc.stato = 'attivo';
            inc.terminato = null;
            inc.dimissioni = null;
            inc.modificato = { da: utente.nome + ' <' + utente.email + '>', il: Date.now() };
            this.salva(lista);
            Audit.registra(utente, 'Incarico riattivato', 'incarico', id, inc.cliente, [{ campo: 'Stato', prima: prima, dopo: 'attivo' }]);
            return inc;
        },

        statoScadenza(inc) {
            const fine = inc.rinnovo || inc.dataFine;
            if (inc.stato === 'proposta') return { classe: 'proposta', testo: 'Proposta' };
            if (inc.stato === 'nonAccettato') return { classe: 'neutro', testo: 'Non accettato' };
            if (inc.stato === 'dimesso') return { classe: 'neutro', testo: 'Dimesso' + (inc.dimissioni && inc.dimissioni.data ? ' ' + fmtData(inc.dimissioni.data) : '') };
            if (inc.stato === 'cessato') return { classe: 'neutro', testo: 'Terminato' };
            if (!fine) return { classe: 'neutro', testo: 'Senza scadenza' };
            // valori non in formato data (note testuali) non sono confrontabili
            if (!/^\d{4}-\d{2}-\d{2}$/.test(fine)) return { classe: 'neutro', testo: String(fine) };
            const oggi = oggiISO();
            if (fine < oggi) return { classe: 'rosso', testo: 'Scaduto ' + fmtData(fine) };
            // +6 mesi senza trabocco di fine mese (es. 31/08 -> 28/02, non 03/03)
            const seiMesi = new Date();
            const giornoOggi = seiMesi.getDate();
            seiMesi.setDate(1);
            seiMesi.setMonth(seiMesi.getMonth() + 6);
            seiMesi.setDate(Math.min(giornoOggi, new Date(seiMesi.getFullYear(), seiMesi.getMonth() + 1, 0).getDate()));
            const limite = seiMesi.getFullYear() + '-' + String(seiMesi.getMonth() + 1).padStart(2, '0') + '-' + String(seiMesi.getDate()).padStart(2, '0');
            if (fine <= limite) return { classe: 'ambra', testo: 'In scadenza ' + fmtData(fine) };
            return { classe: 'verde', testo: 'Attivo fino al ' + fmtData(fine) };
        },

        compensoAnno(inc, anno) {
            return (inc.compensi && inc.compensi[anno]) ? Number(inc.compensi[anno]) : 0;
        },

        /* Gli anni servono alle viste: selettori, assi dei grafici, colonne del CSV.
           Si guardano quindi gli incarichi VISIBILI, non tutti: a un ruolo limitato per
           regione l'elenco completo faceva comparire anni in cui il suo territorio non ha
           un solo compenso - barre a zero nel grafico del cruscotto, e la rivelazione che
           altrove qualcosa c'e'. Per i ruoli senza limite visibili() e' tutti(): per loro
           non cambia niente. */
        anniConCompensi() {
            const anni = new Set();
            this.visibili().forEach(i => Object.keys(i.compensi || {}).forEach(a => anni.add(Number(a))));
            const lista = Array.from(anni).sort();
            return lista.length ? lista : [annoCorrente()];
        }
    };

    const TIPI = {
        legale: 'Revisione legale (triennale)',
        volontaria: 'Revisione volontaria (annuale)',
        collegio: 'Collegio sindacale',
        assistenza: 'Assistenza esterna'
    };

    /* Classe CSS e badge sicuri anche con valori di "tipo" arbitrari
       provenienti da un file importato */
    function classeTipo(tipo) {
        return Object.prototype.hasOwnProperty.call(TIPI, tipo) ? tipo : 'assistenza';
    }
    function nomeTipo(tipo, breve) {
        const nome = TIPI[tipo] || String(tipo || 'n.d.');
        return breve ? nome.split(' (')[0] : nome;
    }
    function badgeTipo(tipo) {
        return '<span class="badge ' + classeTipo(tipo) + '">' + esc(nomeTipo(tipo, true)) + '</span>';
    }

    /* =========================================================
       FATTURAZIONE
    ========================================================= */
    const Fatture = {
        stati() { return Store.leggi(CHIAVI.fatture, {}); },
        salvaStati(s) { Store.scrivi(CHIAVI.fatture, s); },

        /* Genera il piano rate di un incarico per un anno.
           Se l'incarico ha un PIANO CONCORDATO per quell'esercizio (righe scadenza +
           importo decise nel wizard) comanda quello; altrimenti le rate si ricavano
           dalla periodicita, come e sempre stato per gli incarichi importati. */
        rate(inc, anno) {
            const stati = this.stati();
            const righe = inc.piano && inc.piano[anno];
            if (Array.isArray(righe)) {
                return righe.map((r, i) => {
                    const scad = /^\d{4}-\d{2}-\d{2}$/.test(r.scadenza || '') ? r.scadenza : (anno + '-12-31');
                    // la riga nata da una rata automatica conserva la sua chiave: stato ed
                    // eventuale rimborso restano attaccati alla scadenza giusta
                    const chiave = r.chiave || (inc.id + '|' + anno + '|p|' + (r.id || (i + 1)));
                    return {
                        chiave, incarico: inc, anno, numero: i + 1, totale: righe.length,
                        mese: Number(scad.slice(5, 7)) || 12, scadenza: scad,
                        importo: Math.round((Number(r.importo) || 0) * 100) / 100,
                        stato: stati[chiave] || 'da emettere'
                    };
                });
            }
            const compenso = Incarichi.compensoAnno(inc, anno);
            if (!compenso) return [];
            const periodicita = inc.fatturazione || 'annuale';

            // modalita "data specifica": una sola scadenza, nell'esercizio che coincide con la data
            if (periodicita === 'specifica') {
                if (!inc.fattData) return [];
                const d = new Date(inc.fattData);
                if (isNaN(d.getTime()) || d.getFullYear() !== anno) return [];
                const mese = d.getMonth() + 1;
                const chiave = inc.id + '|' + anno + '|specifica|' + inc.fattData;
                return [{
                    chiave, incarico: inc, anno, numero: 1, totale: 1, mese,
                    scadenza: anno + '-' + String(mese).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0'),
                    importo: compenso, stato: stati[chiave] || 'da emettere'
                }];
            }

            const nBase = periodicita === 'mensile' ? 12 : (periodicita === 'trimestrale' ? 4 : 1);
            const mesi = [];
            for (let i = 1; i <= nBase; i++) mesi.push(nBase === 12 ? i : (nBase === 4 ? i * 3 : 12));
            // finestra inizio/fine (se impostata): tiene solo le scadenze (anno,mese) dentro [inizio, fine]
            const dentro = m => {
                if (inc.fattInizio && (anno < inc.fattInizio.anno || (anno === inc.fattInizio.anno && m < inc.fattInizio.mese))) return false;
                if (inc.fattFine && (anno > inc.fattFine.anno || (anno === inc.fattFine.anno && m > inc.fattFine.mese))) return false;
                return true;
            };
            const mesiAttivi = mesi.filter(dentro);
            if (!mesiAttivi.length) return [];
            const n = mesiAttivi.length;
            const importoRata = Math.round((compenso / n) * 100) / 100;
            // senza finestra la chiave resta identica a prima (stati esistenti preservati);
            // con finestra si aggiunge una firma cosi gli stati non si riattaccano a rate diverse
            const finestra = (inc.fattInizio || inc.fattFine)
                ? '|w' + (inc.fattInizio ? inc.fattInizio.anno + '-' + inc.fattInizio.mese : '') + '-' + (inc.fattFine ? inc.fattFine.anno + '-' + inc.fattFine.mese : '')
                : '';
            const out = [];
            mesiAttivi.forEach((mese, k) => {
                const i = k + 1;
                let importo = importoRata;
                if (i === n) importo = Math.round((compenso - importoRata * (n - 1)) * 100) / 100;
                const chiave = inc.id + '|' + anno + '|' + periodicita + '|' + i + finestra;
                out.push({
                    chiave, incarico: inc, anno, numero: i, totale: n, mese,
                    scadenza: anno + '-' + String(mese).padStart(2, '0') + '-' + (nBase === 1 ? '31' : '28'),
                    importo, stato: stati[chiave] || 'da emettere'
                });
            });
            return out;
        },

        tutteAnno(anno) {
            const out = [];
            // gli incarichi in proposta non entrano nel piano di fatturazione finche' non
            // sono confermati (per un rinnovo resta escluso solo il nuovo periodo)
            Incarichi.visibili().forEach(inc => { if (!propostaEscludeAnno(inc, anno)) out.push(...this.rate(inc, anno)); });
            return out.sort((a, b) => a.mese - b.mese || a.incarico.cliente.localeCompare(b.incarico.cliente));
        },

        cambiaStato(chiave, nuovo, utente, cliente) {
            if (!Auth.puoScrivere('fatturazione')) return;      // sola lettura: nessuna scrittura
            const s = this.stati();
            const prima = s[chiave] || 'da emettere';
            s[chiave] = nuovo;
            this.salvaStati(s);
            Audit.registra(utente, 'Stato fattura aggiornato', 'fattura', chiave, cliente,
                [{ campo: 'Stato rata', prima, dopo: nuovo }]);
        },

        /* Rimborsi spese per rata (importo + campo congelabile). Storage locale per rata (chiave). */
        rimborsi() { return Store.leggi(CHIAVI.rimborsi, {}); },
        rimborso(chiave) { const r = this.rimborsi()[chiave]; return { importo: (r && Number(r.importo)) || 0, congelato: !!(r && r.congelato) }; },
        salvaRimborso(chiave, importo, utente, cliente) {
            if (!Auth.puoScrivere('fatturazione')) return false; // sola lettura: nessuna scrittura
            const m = this.rimborsi();
            const cur = m[chiave] || { importo: 0, congelato: false };
            if (cur.congelato) return false;                    // campo congelato: non modificabile
            const prima = Number(cur.importo) || 0;
            const nuovo = Math.round((Number(importo) || 0) * 100) / 100;
            m[chiave] = { importo: nuovo, congelato: false };
            Store.scrivi(CHIAVI.rimborsi, m);
            if (prima !== nuovo) Audit.registra(utente, 'Rimborso spese aggiornato', 'fattura', chiave, cliente,
                [{ campo: 'Rimborso spese', prima: String(prima), dopo: String(nuovo) }]);
            return true;
        },
        congelaRimborso(chiave, congelato, utente, cliente) {
            if (!Auth.puoScrivere('fatturazione')) return;      // sola lettura: nessuna scrittura
            const m = this.rimborsi();
            const cur = m[chiave] || { importo: 0, congelato: false };
            cur.congelato = !!congelato;
            m[chiave] = cur;
            Store.scrivi(CHIAVI.rimborsi, m);
            Audit.registra(utente, congelato ? 'Rimborso spese congelato' : 'Rimborso spese sbloccato', 'fattura', chiave, cliente, null);
        }
    };

    /* Piano di fatturazione PROPOSTO per gli esercizi indicati: le stesse scadenze che
       genererebbe la periodicita scelta, ma come righe modificabili una per una.
       "base" e un incarico (o l'anteprima del wizard) SENZA piano, altrimenti si
       ricopierebbe il piano invece di riproporlo. */
    function pianoProposto(base, anni) {
        const piano = {};
        (anni || []).forEach(anno => {
            piano[anno] = Fatture.rate(base, anno).map((r, i) => ({
                id: 'r' + (i + 1), scadenza: r.scadenza, importo: r.importo,
                // incarico gia salvato: la riga eredita la chiave della rata automatica
                chiave: base.id && base.id !== 'anteprima' ? r.chiave : null
            }));
        });
        return piano;
    }
    // totale degli onorari di un esercizio del piano
    function totalePiano(righe) {
        if (!Array.isArray(righe)) return 0;
        return Math.round(righe.reduce((s, r) => s + (Number(r.importo) || 0), 0) * 100) / 100;
    }
    // etichetta breve del periodo di una riga, in base alla periodicita
    function etichettaRigaPiano(scadenza, periodicita, numero) {
        const m = Number(String(scadenza || '').slice(5, 7)) || 0;
        if (periodicita === 'mensile' && m) return MESI_IT[m - 1].charAt(0).toUpperCase() + MESI_IT[m - 1].slice(1);
        if (periodicita === 'trimestrale' && m) return Math.ceil(m / 3) + '° trimestre';
        return 'Rata ' + numero;
    }

    /* =========================================================
       INTERFACCIA - infrastruttura
    ========================================================= */
    const $vista = () => document.getElementById('vista');

    function toast(msg, tipo) {
        const area = document.getElementById('toast-area');
        const el = document.createElement('div');
        el.className = 'toast' + (tipo ? ' ' + tipo : '');
        el.textContent = msg;
        area.appendChild(el);
        setTimeout(() => el.remove(), 4200);
    }

    /* Esegue un'azione mostrando SEMPRE il caricamento sul pulsante: spinner +
       testo, pulsante disabilitato, con guardia anti doppio-click. Ripristina
       tutto (anche in caso di errore) al termine. Un tempo minimo garantisce
       che lo spinner sia percepibile anche per le operazioni istantanee, cosi
       si capisce sempre quando l'app sta elaborando. */
    async function conAttesa(btn, fn, opts) {
        if (!btn) return typeof fn === 'function' ? fn() : undefined;
        if (btn.dataset.attesa === '1') return; // gia in corso: ignora il click
        const htmlOrig = btn.innerHTML;
        const testo = (opts && opts.testo) || btn.textContent || '';
        const minMs = opts && typeof opts.min === 'number' ? opts.min : 300;
        btn.dataset.attesa = '1';
        btn.classList.add('caricamento');
        btn.disabled = true;
        btn.innerHTML = '<span class="btn-spinner" aria-hidden="true"></span><span>' + esc(testo) + '</span>';
        const avvio = performance.now();
        try {
            return await fn();
        } finally {
            const resta = minMs - (performance.now() - avvio);
            if (resta > 0) await new Promise(r => setTimeout(r, resta));
            delete btn.dataset.attesa;
            btn.classList.remove('caricamento');
            btn.disabled = false;
            btn.innerHTML = htmlOrig;
        }
    }

    /* Testo pulito di una cella (per filtri ed export). */
    function _testoCella(cella) {
        return cella ? cella.textContent.trim().replace(/\s+/g, ' ') : '';
    }

    /* Esporta in CSV le righe VISIBILI (rispetta i filtri) di una tabella "dati",
       saltando le colonne d'azione (intestazione vuota). Formato come l'export
       incarichi: BOM, virgolette, separatore ";", guardia anti-formula Excel. */
    function esportaTabellaCsv(tabella, nomeFile) {
        if (!tabella || !tabella.tHead || !tabella.tBodies[0]) return;
        const ths = Array.from(tabella.tHead.rows[0].cells);
        const colonne = [];
        ths.forEach((th, i) => { if (th.textContent.trim() !== '') colonne.push(i); });
        const righe = [colonne.map(i => ths[i].textContent.trim())];
        Array.from(tabella.tBodies[0].rows).forEach(tr => {
            if (tr.style.display === 'none') return;
            righe.push(colonne.map(i => _testoCella(tr.cells[i])));
        });
        const csv = righe.map(r => r.map(v => {
            let s = String(v).replace(/"/g, '""');
            if (/^[=+\-@\t\r]/.test(s)) s = "'" + s; // niente formule in Excel
            return '"' + s + '"';
        }).join(';')).join('\r\n');
        const blob = new Blob(['﻿' + csv], { type: 'text/csv;charset=utf-8' });
        const a = document.createElement('a');
        a.href = URL.createObjectURL(blob);
        a.download = (nomeFile || 'tabella') + '_' + oggiISO() + '.csv';
        a.click();
        URL.revokeObjectURL(a.href);
        toast('CSV esportato (' + (righe.length - 1) + ' righe).', 'verde');
        Audit.registra(Auth.utenteCorrente, 'Esportazione CSV', 'sistema', null, null, nomeFile || null);
    }

    /* Attrezza una tabella "dati" con una barra strumenti professionale: un filtro
       PER COLONNA (tendina per le colonne categoriali, casella di testo per le
       altre) e un pulsante "Esporta CSV". Generico, guidato dai dati della tabella.
       opts: { nomeFile, filtri = true }. */
    /* Filtro "combinato" riusabile: campo di testo con suggerimenti (datalist).
       Si digita liberamente O si sceglie dall'elenco; vuoto = tutti.
       Chi lo usa confronta con "contiene" (minuscole), cosi' il suggerimento
       scelto per intero coincide e il testo parziale filtra comunque. */
    function comboFiltro(id, etichetta, valori, valore) {
        const dl = id + '-dl';
        return '<div class="campo"><label>' + esc(etichetta) + '</label>'
            + '<input type="search" id="' + id + '" list="' + dl + '" placeholder="Tutti" value="' + esc(valore || '') + '">'
            + '<datalist id="' + dl + '">' + (valori || []).map(v => '<option value="' + esc(v) + '"></option>').join('') + '</datalist></div>';
    }
    // confronto standard dei filtri combinati
    const filtroCorrisponde = (testoCella, digitato) => {
        const q = String(digitato || '').trim().toLowerCase();
        return !q || String(testoCella || '').toLowerCase().includes(q);
    };

    function attrezzaTabella(elOrScope, opts) {
        opts = opts || {};
        const tabella = (elOrScope && elOrScope.tagName === 'TABLE') ? elOrScope : (elOrScope && elOrScope.querySelector('table.dati'));
        if (!tabella || !tabella.tHead || !tabella.tBodies[0]) return;
        const ancora = tabella.closest('.tabella-wrap') || tabella;
        if (ancora.previousElementSibling && ancora.previousElementSibling.classList.contains('barra-tabella')) return;
        const ths = Array.from(tabella.tHead.rows[0].cells);
        const corpo = tabella.tBodies[0];
        // la ricerca globale guarda solo le colonne con intestazione (esclude la colonna azioni: Apri/Duplica/Elimina)
        const idxCerca = ths.map((th, i) => (th.textContent.trim() ? i : -1)).filter(i => i >= 0);
        const barra = document.createElement('div');
        barra.className = 'barra-tabella';

        const controlli = [];
        let ricercaEl = null;
        if (opts.ricerca) {
            const campo = document.createElement('div');
            campo.className = 'campo ricerca';
            campo.innerHTML = '<label>Ricerca</label><input type="search" placeholder="Cerca in tutte le colonne...">';
            ricercaEl = campo.querySelector('input');
            barra.appendChild(campo);
        }
        if (opts.filtri !== false) {
            ths.forEach((th, i) => {
                const nome = th.textContent.trim();
                if (!nome) return; // colonna d'azione
                const valori = new Set();
                Array.from(corpo.rows).forEach(tr => { const v = _testoCella(tr.cells[i]); if (v) valori.add(v); });
                if (valori.size === 0) return; // colonna vuota
                const distinti = Array.from(valori);
                if (distinti.length < 2) return; // un solo valore distinto: filtro inutile
                // Filtro "combinato": si puo' digitare liberamente E scegliere un suggerimento
                // dall'elenco (datalist). Vuoto = tutti; il confronto e' "contiene".
                distinti.sort((a, b) => a.localeCompare(b, 'it', { numeric: true }));
                const dlId = 'dl-' + uid();
                const campo = document.createElement('div');
                campo.className = 'campo';
                campo.innerHTML = '<label>' + esc(nome) + '</label><input type="search" list="' + dlId + '" placeholder="Tutti">'
                    + '<datalist id="' + dlId + '">' + distinti.map(v => '<option value="' + esc(v) + '"></option>').join('') + '</datalist>';
                controlli.push({ i: i, tipo: 'testo', el: campo.querySelector('input') });
                barra.appendChild(campo);
            });
        }

        const azioni = document.createElement('div');
        azioni.className = 'barra-tabella-azioni';
        azioni.innerHTML = '<span class="filtro-conteggio" aria-live="polite"></span>'
            + '<button type="button" class="btn btn-sm btn-secondary" data-esporta>'
            + '<svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg>Esporta CSV</button>';
        barra.appendChild(azioni);
        const conteggio = azioni.querySelector('.filtro-conteggio');
        ancora.parentElement.insertBefore(barra, ancora);

        const applica = () => {
            const righe = Array.from(corpo.rows);
            const q = ricercaEl ? ricercaEl.value.trim().toLowerCase() : '';
            let visibili = 0;
            righe.forEach(tr => {
                let ok = true;
                if (q && !idxCerca.map(i => _testoCella(tr.cells[i])).join(' ').toLowerCase().includes(q)) ok = false;
                if (ok) for (const c of controlli) {
                    const testo = _testoCella(tr.cells[c.i]);
                    if (c.tipo === 'select') { if (c.el.value && testo !== c.el.value) { ok = false; break; } }
                    else { const qc = c.el.value.trim().toLowerCase(); if (qc && !testo.toLowerCase().includes(qc)) { ok = false; break; } }
                }
                tr.style.display = ok ? '' : 'none';
                if (ok) visibili++;
            });
            const filtrando = !!q || controlli.some(c => (c.el.value || '').trim());
            conteggio.textContent = filtrando ? (visibili + ' di ' + righe.length) : '';
        };
        controlli.forEach(c => c.el.addEventListener(c.tipo === 'select' ? 'change' : 'input', applica));
        if (ricercaEl) ricercaEl.addEventListener('input', applica);
        azioni.querySelector('[data-esporta]').addEventListener('click', () => esportaTabellaCsv(tabella, opts.nomeFile));
        return applica;
    }

    /* OGNI modale e' una finestra: barra del titolo blu con riduci, schermo
       intero e chiudi, come le finestre del sistema. Due taglie sole:
       - "finestra" (opts.finestra): l'area di lavoro, alta 86vh qualunque sia
         il contenuto - la usa chi ci lavora dentro a lungo (newsletter,
         aziende da invitare, fasi del rating);
       - "dialogo" (tutto il resto): alta quanto il suo contenuto, come i
         vecchi pop-up, ma vestita da finestra come tutto il resto.
       Il titolo nella barra: quello passato nelle opzioni oppure, per i
       dialoghi che aprivano con un <h2> in testa, proprio quel titolo, che
       sale nella barra invece di stare due volte a schermo.
       Un dialogo "bloccante" (il cambio password obbligatorio, l'avviso di
       ambito) ha la barra ma NESSUN pulsante: non c'e' niente da ridurre o
       chiudere finche' non si e' risposto.
       Niente chiusura col clic fuori, che era un comportamento da pop-up: una
       finestra si chiude con la X, con i suoi pulsanti, o con Esc (i dialoghi
       non bloccanti soltanto: su una finestra di lavoro un Esc distratto
       butterebbe via quello che c'e' dentro). */
    function apriModale(html, opts) {
        opts = opts || {};
        const cont = document.getElementById('modale-contenitore');
        const finestra = !!opts.finestra;
        const bloccante = !!opts.bloccante;
        const controlli = bloccante ? '' : '<span class="modale-controlli">'
            + '<button type="button" class="mw-btn mw-min" title="Riduci a barra" aria-label="Riduci">&#8211;</button>'
            + '<button type="button" class="mw-btn mw-max" title="A schermo intero" aria-label="A schermo intero">&#9633;</button>'
            + '<button type="button" class="mw-btn mw-close" title="Chiudi" aria-label="Chiudi">&#10005;</button>'
            + '</span>';
        const barra = '<div class="modale-barra">'
            + '<span class="modale-titolo">' + esc(opts.titolo || '') + '</span>' + controlli + '</div>';
        cont.innerHTML = '<div class="modale-sfondo modale-sfondo-finestra">'
            + '<div class="modale ' + (opts.classe || '') + ' modale-finestra' + (finestra ? '' : ' modale-dialogo')
            + '" role="dialog" aria-modal="true">' + barra + '<div class="modale-corpo">' + html + '</div></div></div>';
        const sfondo = cont.querySelector('.modale-sfondo');
        const modale = cont.querySelector('.modale');
        const corpo = modale.querySelector('.modale-corpo');
        // il titolo del dialogo sale nella barra: se il contenuto apre con un
        // <h2>, e' lui il titolo della finestra e in mezzo alla pagina non serve
        if (!opts.titolo) {
            const h2 = corpo.firstElementChild;
            if (h2 && h2.tagName === 'H2') {
                cont.querySelector('.modale-titolo').textContent = h2.textContent.trim();
                h2.remove();
            }
        }
        // il piede con i pulsanti esce dall'area scorrevole e diventa un footer fisso della finestra:
        // resta sempre visibile e non copre piu il contenuto finale (es. la sezione del periodo)
        const azioni = corpo.lastElementChild;
        if (azioni && azioni.classList && azioni.classList.contains('modale-azioni')) modale.appendChild(azioni);
        if (!bloccante) {
            const btnMax = cont.querySelector('.mw-max');
            // pulsante centrale: alterna "a schermo intero" e "rimpicciolisci" (icona e titolo seguono lo stato)
            const setMax = m => {
                modale.classList.toggle('massimizzata', m);
                btnMax.innerHTML = m ? '&#10697;' : '&#9633;';
                const t = m ? 'Rimpicciolisci' : 'A schermo intero';
                btnMax.title = t; btnMax.setAttribute('aria-label', t);
            };
            const setRidotta = r => { modale.classList.toggle('ridotta', r); sfondo.classList.toggle('sfondo-ridotto', r); };
            if (opts.massimizzata) setMax(true);
            cont.querySelector('.mw-close').addEventListener('click', chiudiModale);
            cont.querySelector('.mw-min').addEventListener('click', () => setRidotta(!modale.classList.contains('ridotta')));
            btnMax.addEventListener('click', () => { setRidotta(false); setMax(!modale.classList.contains('massimizzata')); });
            cont.querySelector('.modale-barra').addEventListener('dblclick', e => { if (!e.target.closest('.mw-btn')) { setRidotta(false); setMax(!modale.classList.contains('massimizzata')); } });
            cont.querySelector('.modale-titolo').addEventListener('click', () => { if (modale.classList.contains('ridotta')) setRidotta(false); });
            // Esc chiude i dialoghi: e' l'equivalente da finestra del clic
            // fuori con cui si chiudevano i pop-up di ieri. Le finestre di
            // lavoro no: un Esc distratto butterebbe via quello che c'e' dentro.
            if (!finestra) modale.setAttribute('data-esc', '1');
        }
        return cont;
    }
    /* Un solo ascoltatore per l'Esc, sempre attivo: i singoli dialoghi vanno e
       vengono (il contenitore si svuota a ogni chiusura), un ascoltatore per
       dialogo andrebbe rimesso ogni volta e scordarselo e' facile. Qui si
       guarda lo stato vero: c'e' un dialogo che accetta l'Esc, e sopra non c'e'
       una sotto-finestra (quella l'Esc ce l'ha suo e se lo tiene, ma solo se il
       fuoco le sta dentro: da fuori deciderebbe questo ascoltatore, e
       chiuderebbe il livello sbagliato). */
    document.addEventListener('keydown', e => {
        if (e.key !== 'Escape') return;
        const cont = document.getElementById('modale-contenitore');
        if (!cont || cont.querySelector('.modale-sfondo-sopra')) return;
        if (cont.querySelector('.modale[data-esc]')) chiudiModale();
    });
    function chiudiModale() {
        document.getElementById('modale-contenitore').innerHTML = '';
        // chiudendo la scheda persona non la sto piu modificando: aggiorna la presenza
        if (_modalePersonaAperta) { _modalePersonaAperta = false; statoModifica = null; if (typeof Cloud !== 'undefined' && Cloud.pubblicaPresenza) Cloud.pubblicaPresenza(); }
        // se un aggiornamento remoto era stato rimandato mentre la finestra era aperta, applicalo ora
        if (refreshSospeso && !staModificando()) {
            refreshSospeso = false;
            if (_timerRefresh) { clearInterval(_timerRefresh); _timerRefresh = null; }
            if (Auth.utenteCorrente && vistaCorrente !== 'wizard') naviga(vistaCorrente, parametriVista);
        }
    }

    /* Rende un livello inattivo mentre sopra c'e' una finestra: lo sfondo copre i clic, ma NON la
       tastiera, quindi senza questo con Tab/Invio si arriverebbe ancora ai pulsanti della finestra
       sotto (compreso "Invia"). "inert" fa tutto; sui browser che non ce l'hanno si tolgono a mano
       gli elementi dal giro del Tab. */
    const FOCUSABILI = 'a[href], button, input, select, textarea, [tabindex], [contenteditable="true"]';
    function rendiInerte(el, inerte) {
        if (!el || !el.querySelectorAll) return;
        if ('inert' in HTMLElement.prototype) { el.inert = inerte; return; }
        Array.from(el.querySelectorAll(FOCUSABILI)).forEach(f => {
            if (inerte) {
                if (!f.hasAttribute('data-ti-prec')) f.setAttribute('data-ti-prec', f.getAttribute('tabindex') || '');
                f.setAttribute('tabindex', '-1');
            } else if (f.hasAttribute('data-ti-prec')) {
                const p = f.getAttribute('data-ti-prec');
                if (p) f.setAttribute('tabindex', p); else f.removeAttribute('tabindex');
                f.removeAttribute('data-ti-prec');
            }
        });
    }

    /* Apre una vera finestra SOPRA quella corrente (es. Destinatari, Programma l'invio):
       la finestra sotto resta aperta ma diventa inattiva, questa si chiude con "Fatto" o con la X.
       Il contenuto si mette dentro .corpo (di solito spostandoci un pezzo di DOM gia' pronto,
       cosi' mantiene valori e listener). allaChiusura() serve a riprenderselo indietro. */
    function apriSottoFinestra(opts) {
        opts = opts || {};
        const cont = document.getElementById('modale-contenitore');
        const sotto = Array.from(cont.children);          // i livelli gia' aperti: da congelare
        const attivoPrima = document.activeElement;       // a chi ridare il focus alla chiusura
        const sfondo = document.createElement('div');
        sfondo.className = 'modale-sfondo modale-sfondo-finestra modale-sfondo-sopra';
        sfondo.innerHTML = '<div class="modale ' + (opts.classe || '') + ' modale-finestra" tabindex="-1" role="dialog" aria-modal="true">'
            + '<div class="modale-barra"><span class="modale-titolo">' + esc(opts.titolo || '') + '</span>'
            + '<span class="modale-controlli">'
            + '<button type="button" class="mw-btn mw-min" title="Riduci a barra" aria-label="Riduci">&#8211;</button>'
            + '<button type="button" class="mw-btn mw-max" title="A schermo intero" aria-label="A schermo intero">&#9633;</button>'
            + '<button type="button" class="mw-btn mw-close" title="Chiudi" aria-label="Chiudi">&#10005;</button>'
            + '</span></div>'
            + '<div class="modale-corpo"></div>'
            + '<div class="modale-azioni"><button type="button" class="btn btn-primary" data-sf-ok="1">' + esc(opts.ok || 'Fatto') + '</button></div>'
            + '</div>';
        cont.appendChild(sfondo);
        sotto.forEach(el => rendiInerte(el, true));
        const modale = sfondo.querySelector('.modale');
        let chiusa = false;
        const chiudi = () => {
            if (chiusa) return; chiusa = true;
            if (typeof opts.allaChiusura === 'function') opts.allaChiusura();
            sfondo.remove();
            sotto.forEach(el => rendiInerte(el, false));
            try { if (attivoPrima && attivoPrima.focus && attivoPrima.isConnected) attivoPrima.focus(); } catch (_) { }
        };
        sfondo.querySelector('.mw-close').addEventListener('click', chiudi);
        sfondo.querySelector('[data-sf-ok]').addEventListener('click', chiudi);
        /* Ridotta a barra: si vede la finestra sotto (che resta inerte finche'
           questa non si chiude), utile per controllare un dato senza perdere
           quello che si sta scrivendo qui. Il clic sul titolo la riapre. */
        const setRidottaSf = r => { modale.classList.toggle('ridotta', r); sfondo.classList.toggle('sfondo-ridotto', r); };
        sfondo.querySelector('.mw-min').addEventListener('click', () => setRidottaSf(!modale.classList.contains('ridotta')));
        sfondo.querySelector('.modale-titolo').addEventListener('click', () => { if (modale.classList.contains('ridotta')) setRidottaSf(false); });
        sfondo.querySelector('.mw-max').addEventListener('click', () => { setRidottaSf(false); modale.classList.toggle('massimizzata'); });
        sfondo.querySelector('.modale-barra').addEventListener('dblclick', e => { if (!e.target.closest('.mw-btn')) modale.classList.toggle('massimizzata'); });
        sfondo.addEventListener('keydown', e => { if (e.key === 'Escape') { e.stopPropagation(); chiudi(); } });
        try { modale.focus(); } catch (_) { }   // il focus entra nella finestra nuova
        return { sfondo: sfondo, corpo: sfondo.querySelector('.modale-corpo'), chiudi: chiudi };
    }

    /* Mostra nella sidebar gli utenti attualmente connessi (in tempo reale): chi sta modificando
       cosa, un pulsante per scrivergli e la casella dei messaggi ricevuti. Da PRESENZA_COMPATTA_DA
       utenti in su l'elenco parte richiuso (iniziali + "Vedi tutti"): un clic apre il menu completo. */
    const PRESENZA_COMPATTA_DA = 4;
    let presenzaEspansa = false;   // scelta dell'utente: elenco aperto anche se numeroso
    function aggiornaPresenza(connessi) {
        const box = document.getElementById('presenza-box');
        if (!box) return;
        if (!connessi || !connessi.length) { box.innerHTML = ''; return; }
        const mio = String((Auth.utenteCorrente && Auth.utenteCorrente.email) || '').toLowerCase();
        const nonLetti = (typeof Cloud !== 'undefined' && Cloud._msgNonLetti) || 0;
        const icoMatita = '<svg viewBox="0 0 24 24" width="12" height="12" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 20h9"/><path d="M16.5 3.5a2.12 2.12 0 0 1 3 3L7 19l-4 1 1-4z"/></svg>';
        const icoBusta = '<svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 4h16a1 1 0 0 1 1 1v14a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V5a1 1 0 0 1 1-1z"/><path d="m3 6 9 6 9-6"/></svg>';
        const icoFreccia = '<svg viewBox="0 0 24 24" width="12" height="12" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m6 9 6 6 6-6"/></svg>';
        const compatta = connessi.length >= PRESENZA_COMPATTA_DA && !presenzaEspansa;
        let corpo;
        if (compatta) {
            const inizialiDi = n => (String(n || '?').trim().split(/\s+/).slice(0, 2).map(p => p.charAt(0).toUpperCase()).join('') || '?');
            const chips = connessi.slice(0, 5).map(c => '<span class="pres-avatar" title="' + esc(c.nome || c.email) + '">' + esc(inizialiDi(c.nome || c.email)) + '</span>').join('')
                + (connessi.length > 5 ? '<span class="pres-avatar pres-avatar-extra">+' + (connessi.length - 5) + '</span>' : '');
            corpo = '<button type="button" class="presenza-riassunto" aria-expanded="false" title="Apri l\'elenco degli utenti connessi">'
                + '<span class="pres-avatars">' + chips + '</span>'
                + '<span class="pres-riass-apri">Vedi tutti' + icoFreccia + '</span></button>';
        } else {
            const voci = connessi.map(c => {
                const io = String(c.email).toLowerCase() === mio;
                const mod = (c.modifica && c.modifica.etichetta)
                    ? '<span class="pres-mod" title="Sta modificando in questo momento">' + icoMatita + '<span class="et">' + esc(troncaTesto(String(c.modifica.etichetta), 22)) + '</span></span>'
                    : '';
                const scrivi = io ? '' : '<button class="btn btn-sm btn-ghost pres-msg" data-email="' + esc(c.email) + '" data-nome="' + esc(c.nome || c.email) + '" title="Scrivi a ' + esc(c.nome || c.email) + '" aria-label="Scrivi a ' + esc(c.nome || c.email) + '">' + icoBusta + '</button>';
                return '<div class="presenza-utente' + (mod ? ' sta-modificando' : '') + '"><span class="pallino"></span>'
                    + '<span class="pres-corpo"><span class="pres-nome-riga"><span class="pres-nome">' + esc((c.nome || c.email) + (io ? ' (tu)' : '')) + '</span>' + scrivi + '</span>' + mod + '</span></div>';
            }).join('');
            const riduci = connessi.length >= PRESENZA_COMPATTA_DA
                ? '<button type="button" class="presenza-riduci" aria-expanded="true"><span class="freccia-su">' + icoFreccia + '</span><span>Riduci elenco</span></button>'
                : '';
            corpo = voci + riduci;
        }
        box.innerHTML = '<div class="presenza-pannello' + (compatta ? ' compatta' : '') + '">'
            + '<div class="presenza-titolo"><span>Connessi ora &middot; ' + connessi.length + '</span>'
            + '<button class="pres-inbox" title="Messaggi ricevuti" aria-label="Messaggi ricevuti">' + icoBusta + '<span>Messaggi</span>' + (nonLetti ? '<span class="pres-badge">' + nonLetti + '</span>' : '') + '</button></div>'
            + corpo + '</div>';
        box.querySelectorAll('.pres-msg').forEach(b => b.addEventListener('click', () => modaleInviaMessaggio(b.dataset.email, b.dataset.nome)));
        const bi = box.querySelector('.pres-inbox'); if (bi) bi.addEventListener('click', modaleCasellaMessaggi);
        const ba = box.querySelector('.presenza-riassunto'); if (ba) ba.addEventListener('click', () => { presenzaEspansa = true; aggiornaPresenza(connessi); });
        const br = box.querySelector('.presenza-riduci'); if (br) br.addEventListener('click', () => { presenzaEspansa = false; aggiornaPresenza(connessi); });
    }
    function modaleInviaMessaggio(email, nome) {
        apriModale('<h2>Scrivi a ' + esc(nome) + '</h2>'
            + '<div class="campo"><textarea id="msg-testo" rows="3" maxlength="500" placeholder="Messaggio..."></textarea></div>'
            + '<div class="modale-azioni"><button class="btn btn-ghost" id="m-annulla">Annulla</button><button class="btn btn-primary" id="m-invia">Invia</button></div>');
        document.getElementById('m-annulla').addEventListener('click', chiudiModale);
        const bt = document.getElementById('m-invia');
        bt.addEventListener('click', async () => {
            const t = document.getElementById('msg-testo').value.trim();
            if (!t) { toast('Scrivi un messaggio.', 'rosso'); return; }
            bt.disabled = true;
            const ok = (typeof Cloud !== 'undefined' && Cloud.inviaMessaggio) ? await Cloud.inviaMessaggio(email, t) : false;
            if (ok) { chiudiModale(); toast('Messaggio inviato a ' + nome, 'verde'); }
            // in caso di errore la finestra resta aperta: il testo scritto non si perde
            else { bt.disabled = false; toast('Invio non riuscito. Controlla la connessione e riprova.', 'rosso'); }
        });
        setTimeout(() => { const ta = document.getElementById('msg-testo'); if (ta) ta.focus(); }, 30);
    }
    function modaleCasellaMessaggi() {
        if (typeof Cloud !== 'undefined') Cloud._msgNonLetti = 0;
        const inbox = (typeof Cloud !== 'undefined' && Cloud._inbox) || [];
        const righe = inbox.length
            ? inbox.map(m => '<div class="riepilogo-riga"><span class="etichetta">' + esc(m.daNome || m.da || '') + '</span><span class="valore">' + esc(m.testo || '') + ' <span class="hint">' + fmtDataOra(m.ts) + '</span> <button type="button" class="btn btn-sm btn-ghost msg-rispondi" data-email="' + esc(m.da || '') + '" data-nome="' + esc(m.daNome || m.da || '') + '">Rispondi</button></span></div>').join('')
            : '<p class="descrizione">Nessun messaggio ricevuto in questa sessione.</p>';
        const cont = apriModale('<h2>Messaggi ricevuti</h2>' + righe + '<div class="modale-azioni"><button class="btn btn-primary" id="m-ok">Chiudi</button></div>', { classe: 'larga' });
        document.getElementById('m-ok').addEventListener('click', chiudiModale);
        cont.querySelectorAll('.msg-rispondi').forEach(b => b.addEventListener('click', () => modaleInviaMessaggio(b.dataset.email, b.dataset.nome)));
        aggiornaPresenza((typeof Cloud !== 'undefined' && Cloud._presenzaUltima) || []);
    }
    /* Popup del messaggio in arrivo: compare in basso a destra per OGNI utente connesso
       destinatario, senza rubare il focus e senza toccare le modali aperte (ha un suo
       contenitore). Da qui si risponde direttamente. */
    function areaPopupMessaggi() {
        let area = document.getElementById('msg-popup-area');
        if (!area) { area = document.createElement('div'); area.id = 'msg-popup-area'; document.body.appendChild(area); }
        return area;
    }
    function mostraPopupMessaggio(m) {
        const area = areaPopupMessaggi();
        while (area.children.length >= 3) area.firstElementChild.remove();   // al massimo 3 popup impilati
        const mitt = m.daNome || m.da || '';
        const card = document.createElement('div');
        card.className = 'msg-popup';
        card.setAttribute('role', 'alert');
        card.innerHTML = '<div class="msg-popup-testata"><span class="pallino"></span><strong>' + esc(mitt) + '</strong>'
            + '<span class="msg-popup-ora">' + fmtDataOra(m.ts) + '</span>'
            + '<button type="button" class="msg-popup-x" title="Chiudi" aria-label="Chiudi">&#10005;</button></div>'
            + '<div class="msg-popup-testo">' + esc(m.testo || '') + '</div>'
            + '<div class="msg-popup-risposta"><textarea rows="2" maxlength="500" placeholder="Rispondi a ' + esc(mitt) + '..."></textarea>'
            + '<div class="msg-popup-azioni"><button type="button" class="btn btn-sm btn-ghost mp-chiudi">Chiudi</button>'
            + '<button type="button" class="btn btn-sm btn-primary mp-rispondi">Rispondi</button></div></div>';
        area.appendChild(card);
        const ta = card.querySelector('textarea');
        const btn = card.querySelector('.mp-rispondi');
        const chiudi = () => card.remove();
        card.querySelector('.msg-popup-x').addEventListener('click', chiudi);
        card.querySelector('.mp-chiudi').addEventListener('click', chiudi);
        const rispondi = async () => {
            const t = ta.value.trim();
            if (!t) { ta.focus(); return; }
            btn.disabled = true;
            const ok = (typeof Cloud !== 'undefined' && Cloud.inviaMessaggio) ? await Cloud.inviaMessaggio(m.da, t) : false;
            if (ok) { toast('Risposta inviata a ' + mitt, 'verde'); chiudi(); }
            else { btn.disabled = false; toast('Invio non riuscito. Controlla la connessione e riprova.', 'rosso'); }
        };
        btn.addEventListener('click', rispondi);
        ta.addEventListener('keydown', e => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); rispondi(); } });
    }

    /* =========================================================
       NAVIGAZIONE
    ========================================================= */
    const VOCI_NAV = [
        { id: 'dashboard', nome: 'Cruscotto', icona: 'M3 13h8V3H3zm10 8h8V11h-8zM3 21h8v-6H3zm10-18v6h8V3z' },
        { id: 'incarichi', nome: 'Incarichi', icona: 'M4 6h16M4 12h16M4 18h10' },
        /* La via di servizio per far correggere un dato sbagliato: la vedono tutti,
           perche' e' proprio chi NON puo' modificare (coordinatori, vice, ruoli in sola
           lettura) ad avere bisogno di chiederlo. Sta qui, subito sotto gli Incarichi,
           perche' e' li' che il dato sbagliato si incontra. */
        { id: 'richieste', nome: 'Richieste di correzione', icona: 'M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2zM8 9h8M8 13h5' },
        /* MACROAREA DEGLI ADERENTI. L'anagrafica e le due viste che ne derivano
           (chi coordina un territorio, chi e' responsabile di qualita o incarico)
           sono la stessa scheda letta in tre modi: stanno insieme, cosi' si vede
           subito che i dati di Coordinatori e Responsabili si cambiano da qui.
           Vengono prima dei Compensi: sono le persone a fare gli incarichi, e i
           compensi si leggono dopo, quando c'e' da fatturarli. */
        { id: 'persone', nome: 'Aderenti Revilaw', gruppo: 'Gestione aderenti', icona: 'M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z' },
        { id: 'coordinatori', nome: 'Coordinatori e vice', gruppo: 'Gestione aderenti', icona: 'M12 21s-6-5.3-6-10a6 6 0 1 1 12 0c0 4.7-6 10-6 10zM12 13a2.5 2.5 0 1 0 0-5 2.5 2.5 0 0 0 0 5z' },
        { id: 'responsabili', nome: 'Responsabili', gruppo: 'Gestione aderenti', icona: 'M9 12l2 2 4-4M12 3l7 4v5c0 4-3 7-7 8-4-1-7-4-7-8V7z' },
        /* MACROAREA DEI COMPENSI. Fatturazione e Report compensi guardano gli
           stessi importi da due lati: quando si incassano e quanto valgono. Sotto
           un'intestazione sola si capisce che sono due letture della stessa cosa. */
        { id: 'fatturazione', nome: 'Fatturazione', gruppo: 'Compensi', icona: 'M9 14l2 2 4-4M5 3h14a1 1 0 011 1v16l-3-2-2 2-3-2-2 2-3-2-3 2V4a1 1 0 011-1z' },
        { id: 'report', nome: 'Report compensi', gruppo: 'Compensi', icona: 'M4 20V10m6 10V4m6 16v-7m4 7H2' },
        /* MACROAREA DEL MERITO CREDITIZIO. La versione di lavoro del simulatore
           pubblico di rating: qui le verifiche si salvano per cliente, con
           questionario, banche e report firmato da stampare in PDF. */
        { id: 'rating', nome: 'Verifica merito creditizio', gruppo: 'Merito creditizio', icona: 'M3 21h18M4 18h16M6 18v-8m4 8v-8m4 8v-8m4 8v-8M2 10l10-6 10 6' },
        /* MACROAREA DELLA QUALITA'. Il monitoraggio dei controlli di qualita:
           l'elenco degli incarichi con i semafori delle aree e, per ogni cliente,
           la scheda con gli avanzamenti periodici. Ogni responsabile della
           qualita vede SOLO gli incarichi in cui e' lui il responsabile. */
        { id: 'controlloQualita', nome: 'Controlli qualità', gruppo: 'Qualità', icona: 'M12 3l7 3v5c0 4.5-3 8.5-7 10-4-1.5-7-5.5-7-10V6zM9 12l2 2 4-4' },
        /* MACROAREA DELLE COMUNICAZIONI. Le tre sezioni che mandano messaggi fuori
           stavano sparse nell'elenco, con i Sondaggi in mezzo: una accanto
           all'altra, sotto un'intestazione, si capisce a colpo d'occhio che sono
           tre canali diversi della stessa cosa, e non tre funzioni scollegate.
           I nomi dicono a CHI si scrive, che e' la domanda vera: ai team di
           revisione, ai contatti commerciali, agli iscritti degli eventi. */
        { id: 'comunicazioni', nome: 'Comunicazione teams di revisione', gruppo: 'Comunicazioni', icona: 'M3 8l9 6 9-6M5 5h14a2 2 0 012 2v10a2 2 0 01-2 2H5a2 2 0 01-2-2V7a2 2 0 012-2z' },
        { id: 'newsletter', nome: 'Newsletter commerciali', gruppo: 'Comunicazioni', icona: 'M4 6h12a2 2 0 012 2v11H6a2 2 0 01-2-2zm14 3h2a2 2 0 012 2v6a2 2 0 01-2 2h-2M7 9h6M7 13h6' },
        { id: 'eventi', nome: 'Iscrizioni Eventi NGB', gruppo: 'Comunicazioni', icona: 'M8 2v4m8-4v4M3 10h18M5 4h14a2 2 0 012 2v13a2 2 0 01-2 2H5a2 2 0 01-2-2V6a2 2 0 012-2z' },
        { id: 'sondaggi', nome: 'Sondaggi', icona: 'M9 5H7a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V7a2 2 0 0 0-2-2h-2M9 5a2 2 0 0 0 2 2h2a2 2 0 0 0 2-2M9 5a2 2 0 0 1 2-2h2a2 2 0 0 1 2 2M9 13l2 2 4-4' },
        { id: 'registro', nome: 'Registro modifiche', icona: 'M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z' },
        { id: 'utenti', nome: 'Utenti', icona: 'M17 21v-2a4 4 0 00-4-4H5a4 4 0 00-4 4v2m20 0v-2a4 4 0 00-3-3.87M16 3.13a4 4 0 010 7.75M12 7a4 4 0 11-8 0 4 4 0 018 0z', soloAdmin: true },
        { id: 'ruoli', nome: 'Ruoli e permessi', icona: 'M12 15a3 3 0 100-6 3 3 0 000 6zM12 1v2m0 18v2m11-11h-2M3 12H1m17.66 6.66l-1.42-1.42M6.76 6.76 5.34 5.34m12.32 0-1.42 1.42M6.76 17.24l-1.42 1.42', soloAdmin: true },
        { id: 'dati', nome: 'Dati e backup', icona: 'M4 7c0-1.1 3.6-2 8-2s8 .9 8 2-3.6 2-8 2-8-.9-8-2zm0 0v10c0 1.1 3.6 2 8 2s8-.9 8-2V7', soloProprietario: true }
    ];

    let vistaCorrente = 'dashboard';
    let parametriVista = null;
    let refreshSospeso = false;   // ridisegno da sincronizzazione rimandato perche l'utente sta editando
    let _timerRefresh = null;
    let statoModifica = null;        // {tipo,id,etichetta} di cio che sto modificando ora (per la presenza)
    let _modalePersonaAperta = false; // per azzerare statoModifica alla chiusura della scheda persona
    // sottopagine di un incarico: entrarci da una sezione (es. Aderenti Revilaw) fa ricordare dove tornare
    const SOTTOVISTE = ['dettaglio', 'wizard', 'lettera', 'ratingScheda', 'ratingReport', 'ratingMetodo', 'ratingVerbale', 'controlloQualitaScheda'];
    let origineNav = null;           // {vista, parametri, scrollY} della sezione da cui si e entrati nel flusso

    // dettaglio/wizard/lettera sono sottopagine degli incarichi: valgono il permesso "incarichi".
    // La sezione Coordinatori e' una vista dell'anagrafica: valgono i permessi di "persone".
    const SEZIONE_DI_VISTA = { dettaglio: 'incarichi', wizard: 'incarichi', lettera: 'incarichi', coordinatori: 'persone', responsabili: 'persone', ratingScheda: 'rating', ratingReport: 'rating', ratingMetodo: 'rating', ratingVerbale: 'rating', controlloQualitaScheda: 'controlloQualita' };
    function primaVistaVisibile() { const v = VOCI_NAV.find(x => Auth.puoVedere(SEZIONE_DI_VISTA[x.id] || x.id)); return v ? v.id : null; }

    /* =========================================================
       SOTTO-MENU DI SEZIONE
       Alcune sezioni non sono un elenco solo: sono piu' blocchi con un titolo,
       uno sotto l'altro, e su uno schermo non ci stanno (il Report ha tre
       grafici, Dati e backup sei riquadri). Scorrere a cercare quello giusto e'
       la parte noiosa; questa barra elenca i blocchi, ci porta con un clic e
       dice a che punto della pagina si e'.
       Non e' scritta a mano sezione per sezione: si costruisce da sola da cio'
       che la vista ha davvero disegnato. Percio' compare dove serve e sparisce
       dove non serve, oggi e anche fra sei mesi, senza che nessuno se ne ricordi.
    ========================================================= */
    /* Che cos'e' un "blocco": un riquadro di PRIMO livello con un suo titolo.
       Il primo livello conta: le schede dei ruoli hanno un h2 a testa ma stanno
       affiancate dentro una griglia, e un elenco di collegamenti non aiuterebbe
       a scorrerle - si vedono gia' tutte insieme. */
    const SOTTOMENU_MIN_BLOCCHI = 3;
    let _scorrimentoSottoMenu = null;

    function bloccoTitolo(card) {
        return card.querySelector(':scope > h2') || card.querySelector(':scope > .s-sez-tit');
    }

    function costruisciSottoMenu() {
        const vista = $vista();
        if (!vista) return;
        if (_scorrimentoSottoMenu) {
            window.removeEventListener('scroll', _scorrimentoSottoMenu);
            window.removeEventListener('resize', _scorrimentoSottoMenu);
            _scorrimentoSottoMenu = null;
        }
        const vecchio = vista.querySelector(':scope > .sotto-menu');
        if (vecchio) vecchio.remove();

        const blocchi = Array.from(vista.children)
            .filter(el => el.classList && el.classList.contains('card'))
            .map(card => ({ card, tit: bloccoTitolo(card) }))
            .filter(b => b.tit && b.tit.textContent.trim());
        if (blocchi.length < SOTTOMENU_MIN_BLOCCHI) return;
        /* Se la pagina ci sta tutta sotto gli occhi non c'e' niente da scorrere,
           e la barra sarebbe solo una riga in piu' da leggere. */
        if (document.documentElement.scrollHeight <= window.innerHeight + 200) return;

        const nav = document.createElement('nav');
        nav.className = 'sotto-menu';
        nav.setAttribute('aria-label', 'Blocchi di questa sezione');
        blocchi.forEach((b, i) => {
            if (!b.card.id) b.card.id = 'blocco-' + vistaCorrente + '-' + i;
            /* il titolo del riquadro puo' contenere pastiglie e numeri: nella
               barra va il solo testo, e non troppo lungo */
            const testo = (b.tit.textContent || '').trim().replace(/\s+/g, ' ');
            const voce = document.createElement('button');
            voce.type = 'button';
            voce.className = 'sotto-menu-voce';
            voce.textContent = testo.length > 42 ? testo.slice(0, 41).trimEnd() + '\u2026' : testo;
            if (testo.length > 42) voce.title = testo;
            voce.dataset.blocco = b.card.id;
            voce.addEventListener('click', () => {
                /* La barra e' appiccicata in cima: portando il riquadro a filo
                   pagina il suo titolo finirebbe proprio sotto la barra. Si
                   scende fino a poco sopra, cosi' il titolo resta in vista. */
                const y = b.card.getBoundingClientRect().top + window.scrollY - nav.offsetHeight - 14;
                window.scrollTo({ top: Math.max(0, y), behavior: 'smooth' });
            });
            nav.appendChild(voce);
        });

        /* La barra va SOTTO l'intestazione della sezione (titolo e pulsanti):
           quella si legge una volta, i collegamenti servono mentre si scorre. */
        const testata = vista.querySelector(':scope > header');
        if (testata && testata.nextSibling) vista.insertBefore(nav, testata.nextSibling);
        else if (testata) vista.appendChild(nav);
        else vista.insertBefore(nav, vista.firstChild);

        /* Quale blocco si sta guardando: l'ULTIMO il cui inizio e' gia' passato
           sotto la barra. E' un criterio deterministico e si spiega in una riga,
           al contrario di "quello che occupa piu' schermo", che con un grafico
           alto accanto a una tabella lunga fa saltare l'accensione avanti e
           indietro mentre si scorre.
           Caso a parte il fondo pagina: l'ultimo blocco puo' essere troppo corto
           per arrivare mai sotto la barra, e resterebbe l'unico che non si
           accende mai. Arrivati in fondo, quello e'. */
        const voci = Array.from(nav.querySelectorAll('.sotto-menu-voce'));
        let acceso = null;
        const accendi = id => {
            if (id === acceso) return;
            acceso = id;
            voci.forEach(v => {
                const suo = v.dataset.blocco === id;
                v.classList.toggle('attiva', suo);
                if (suo) v.setAttribute('aria-current', 'true'); else v.removeAttribute('aria-current');
            });
        };
        const quale = () => {
            const doc = document.documentElement;
            if (window.innerHeight + window.scrollY >= doc.scrollHeight - 4)
                return blocchi[blocchi.length - 1].card.id;
            /* Un blocco diventa "quello che si sta guardando" quando il suo
               titolo e' sceso nel quarto alto dello schermo, non appena tocca
               il bordo della barra: altrimenti, con un blocco che riempie lo
               schermo, resta accesa la voce di quello precedente e la barra
               sembra in ritardo. */
            const soglia = nav.getBoundingClientRect().bottom + window.innerHeight * 0.25;
            let corrente = blocchi[0].card.id;
            blocchi.forEach(b => { if (b.card.getBoundingClientRect().top <= soglia) corrente = b.card.id; });
            return corrente;
        };
        /* Un solo calcolo per fotogramma: lo scorrimento genera decine di eventi
           al secondo e leggere le posizioni a ogni evento fa scattare il
           ricalcolo del foglio di stile ogni volta. */
        let inCoda = false;
        _scorrimentoSottoMenu = () => {
            if (inCoda) return;
            inCoda = true;
            requestAnimationFrame(() => { inCoda = false; accendi(quale()); });
        };
        window.addEventListener('scroll', _scorrimentoSottoMenu, { passive: true });
        window.addEventListener('resize', _scorrimentoSottoMenu);
        accendi(quale());
    }

    function naviga(id, parametri, ripristinaScroll) {
        statoModifica = null;   // cambiando vista non sto piu modificando (il wizard lo re-imposta)
        const viste = {
            dashboard: vistaDashboard,
            incarichi: vistaIncarichi,
            dettaglio: vistaDettaglio,
            wizard: vistaWizard,
            fatturazione: vistaFatturazione,
            report: vistaReport,
            persone: vistaPersone,
            coordinatori: vistaCoordinatori,
            responsabili: vistaResponsabili,
            comunicazioni: vistaComunicazioni,
            richieste: vistaRichieste,
            sondaggi: vistaSondaggi,
            eventi: vistaEventi,
            newsletter: vistaNewsletter,
            registro: vistaRegistro,
            utenti: vistaUtenti,
            ruoli: vistaRuoli,
            dati: vistaDati,
            lettera: vistaLettera,
            rating: vistaRating,
            ratingScheda: vistaRatingScheda,
            ratingReport: vistaRatingReport,
            ratingMetodo: vistaRatingMetodo,
            ratingVerbale: vistaRatingVerbale,
            controlloQualita: vistaControlliQualita,
            controlloQualitaScheda: vistaControlloQualitaScheda
        };
        // guardia permessi: la sezione richiesta deve essere consentita dal ruolo
        const sez = SEZIONE_DI_VISTA[id] || id;
        if (!Auth.puoVedere(sez)) {
            const alt = primaVistaVisibile();
            if (!alt) { vistaCorrente = id; parametriVista = null; disegnaNav(); vistaSenzaAccesso(); return; }
            id = alt; parametri = null;
        }
        // creare un incarico e' scrittura: chi ha gli incarichi in sola lettura non entra nel wizard
        if (id === 'wizard' && !Auth.puoScrivere('incarichi')) { id = 'incarichi'; parametri = null; }
        // compilare una verifica di rating e' scrittura: in sola lettura resta il report
        if (id === 'ratingScheda' && !Auth.puoScrivere('rating')) {
            if (parametri && parametri.id) { id = 'ratingReport'; }
            else { id = 'rating'; parametri = null; }
        }
        // ricorda l'origine quando si entra in dettaglio/wizard/lettera da una sezione reale;
        // uscendo verso una sezione reale il ricordo si azzera
        const entraSotto = SOTTOVISTE.includes(id), eroSotto = SOTTOVISTE.includes(vistaCorrente);
        if (entraSotto && !eroSotto) origineNav = { vista: vistaCorrente, parametri: parametriVista, scrollY: window.scrollY };
        else if (!entraSotto) origineNav = null;
        vistaCorrente = id;
        parametriVista = parametri || null;
        disegnaNav();
        (viste[id] || vistaDashboard)();
        costruisciSottoMenu();
        window.scrollTo(0, ripristinaScroll || 0);
        if (typeof Cloud !== 'undefined' && Cloud.pubblicaPresenza) Cloud.pubblicaPresenza();
    }
    /* Torna alla sezione da cui si e entrati nel flusso di un incarico, ripristinando lo
       scorrimento (la scheda della sezione, es. il tab di Aderenti Revilaw, e gia persistente). */
    function tornaOrigine(fallback) {
        if (origineNav && !SOTTOVISTE.includes(origineNav.vista)) {
            const o = origineNav; origineNav = null;
            naviga(o.vista, o.parametri, o.scrollY);
        } else if (typeof fallback === 'function') fallback();
        else naviga('incarichi');
    }

    /* true se l'utente sta editando qualcosa (finestra aperta o campo a fuoco): in quel caso
       un ridisegno da sincronizzazione remota lo butterebbe fuori dalla schermata. */
    function staModificando() {
        const cont = document.getElementById('modale-contenitore');
        if (cont && cont.innerHTML.trim() !== '') return true;
        const el = document.activeElement;
        if (!el || el === document.body) return false;
        const tag = (el.tagName || '').toLowerCase();
        return tag === 'input' || tag === 'select' || tag === 'textarea' || el.isContentEditable === true;
    }
    /* Ridisegna la vista corrente per riflettere dati arrivati dalla sincronizzazione, ma solo
       se l'utente non sta editando: altrimenti rimanda finche non ha finito (niente "salto"
       della schermata mentre si compila un campo o una finestra). */
    function ridisegnaDaSync() {
        if (!Auth.utenteCorrente || vistaCorrente === 'wizard' || vistaCorrente === 'ratingScheda') return;
        if (staModificando()) {
            refreshSospeso = true;
            if (!_timerRefresh) _timerRefresh = setInterval(() => {
                if (staModificando()) return;
                clearInterval(_timerRefresh); _timerRefresh = null;
                if (refreshSospeso) { refreshSospeso = false; if (Auth.utenteCorrente && vistaCorrente !== 'wizard' && vistaCorrente !== 'ratingScheda') naviga(vistaCorrente, parametriVista); }
            }, 900);
            return;
        }
        refreshSospeso = false;
        naviga(vistaCorrente, parametriVista);
    }

    /* Descrittore della vista corrente per la presenza (cosa sto guardando). */
    function presenzaVistaCorrente() {
        if (vistaCorrente === 'dettaglio' && parametriVista && parametriVista.id) {
            const inc = (typeof Incarichi !== 'undefined') ? Incarichi.trova(parametriVista.id) : null;
            return { tipo: 'incarico', id: parametriVista.id, etichetta: inc ? (inc.cliente || '') : '' };
        }
        if ((vistaCorrente === 'ratingScheda' || vistaCorrente === 'ratingReport' || vistaCorrente === 'ratingVerbale') && parametriVista && parametriVista.id) {
            const ver = (typeof Rating !== 'undefined') ? Rating.trova(parametriVista.id) : null;
            return { tipo: 'rating', id: parametriVista.id, etichetta: ver ? (ver.cliente || '') : '' };
        }
        if (vistaCorrente === 'controlloQualitaScheda' && parametriVista && parametriVista.id) {
            const inc = (typeof Incarichi !== 'undefined') ? Incarichi.trova(parametriVista.id) : null;
            return { tipo: 'controlloQualita', id: parametriVista.id, etichetta: inc ? (inc.cliente || '') : '' };
        }
        const v = VOCI_NAV.find(x => x.id === vistaCorrente);
        return { tipo: 'sezione', id: vistaCorrente, etichetta: v ? v.nome : vistaCorrente };
    }
    /* Nome di chi (diverso da me) sta gia modificando questo tipo+id, tra i connessi recenti; else null. */
    function chiModificaGia(tipo, id) {
        const mio = String((Auth.utenteCorrente && Auth.utenteCorrente.email) || '').toLowerCase();
        const lista = (typeof Cloud !== 'undefined' && Cloud._presenzaUltima) || [];
        const c = lista.find(x => String(x.email).toLowerCase() !== mio && x.modifica && x.modifica.tipo === tipo && String(x.modifica.id) === String(id));
        return c ? (c.nome || c.email) : null;
    }
    /* Avvisa (senza bloccare) se un altro connesso sta gia modificando questo record. */
    function avvisaSeAltriModificano(tipo, id) {
        const chi = chiModificaGia(tipo, id);
        if (chi) toast('Attenzione: ' + chi + ' sta modificando ' + (tipo === 'incarico' ? 'questo incarico' : (tipo === 'controlloQualita' ? 'questa scheda di controllo qualità' : 'questa persona')) + ' in questo momento.', 'rosso');
    }

    function vistaSenzaAccesso() {
        $vista().innerHTML = '<header><div><h1>Nessuna sezione disponibile</h1>'
            + '<p class="descrizione">Il tuo ruolo non ha accesso ad alcuna sezione. Chiedi all\'amministratore di assegnarti i permessi.</p></div></header>';
    }

    /* Nome del ruolo nella barra laterale; per il coordinatore anche la regione, cosi' si
       capisce subito cosa si sta vedendo (e perche' tutto e' vuoto se la scheda in Aderenti Revilaw
       non ha la regione). Richiamata a ogni cambio vista: resta aggiornata anche quando
       l'anagrafica cambia mentre si e' collegati. */
    function aggiornaEtichettaUtente() {
        const el = document.getElementById('utente-ruolo');
        if (!el || !Auth.utenteCorrente) return;
        const etich = nomeRuolo(Auth.utenteCorrente.ruolo);
        // le regioni assegnate restano sempre sott'occhio, su una riga loro e con
        // l'etichetta che dice cosa sono: appese al ruolo dopo un punto separatore si
        // leggevano come parte del nome del ruolo
        const regioni = regioniDelRuolo();   // null = ruolo senza limite di territorio
        if (!regioni) { el.textContent = etich; return; }
        el.innerHTML = esc(etich) + '<span class="regioni-assegnate">' + (regioni.length
            ? 'Regioni assegnate: <strong>' + esc(regioni.join(', ')) + '</strong>'
            : '<span class="badge rosso">nessuna regione assegnata</span>') + '</span>';
    }

    function disegnaNav() {
        const nav = document.getElementById('nav-principale');
        aggiornaEtichettaUtente();
        /* Le voci con lo stesso "gruppo" si disegnano sotto un'intestazione. Il
           titolo compare solo la PRIMA volta che quel gruppo appare, e solo se
           l'utente vede almeno una delle sue voci: a chi ha i permessi per una
           sezione sola non deve comparire un'intestazione con sotto una riga. */
        let gruppoCorrente = '';
        // richieste di correzione in attesa di una mia risposta: il numero sta sulla voce
        // di menu, altrimenti una risposta arrivata mentre si lavora altrove passerebbe
        // inosservata
        const nuoveRichieste = richiesteDaRispondere();
        nav.innerHTML = VOCI_NAV
            .filter(v => Auth.puoVedere(SEZIONE_DI_VISTA[v.id] || v.id))
            .map(v => {
                let testa = '';
                const g = v.gruppo || '';
                if (g !== gruppoCorrente) {
                    gruppoCorrente = g;
                    if (g) testa = '<div class="nav-gruppo">' + esc(g) + '</div>';
                }
                const conta = (v.id === 'richieste' && nuoveRichieste)
                    ? '<span class="nav-conta" title="Richieste in attesa di una tua risposta">' + nuoveRichieste + '</span>' : '';
                /* Il nome sta in uno <span>: col menu ridotto a icone si nasconde
                   lui soltanto, e il "title" fa da etichetta al passaggio del mouse. */
                return testa
                    + '<button class="nav-voce' + (g ? ' in-gruppo' : '') + (vistaCorrente === v.id ? ' attiva' : '') + '" data-vista="' + v.id + '" title="' + esc(v.nome) + '">'
                    + '<svg class="icona" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="' + v.icona + '"/></svg>'
                    + '<span class="et">' + esc(v.nome) + '</span>' + conta + '</button>';
            }).join('');
        nav.querySelectorAll('.nav-voce').forEach(b =>
            b.addEventListener('click', () => { naviga(b.dataset.vista); chiudiMenuMobile(); }));
    }

    /* Menu ridotto alle sole icone (schermo largo): il contenuto si allarga di
       180px, che e' quanto basta alla tabella degli iscritti per stare comoda
       anche su un portatile. La scelta resta fra una sessione e l'altra. Passando
       il mouse sulla barra le voci ricompaiono per intero SOPRA il contenuto,
       senza spostarlo: si naviga senza dover riaprire il menu. */
    const CHIAVE_MENU_RIDOTTO = 'rvArea.menuRidotto';
    function menuRidotto() {
        try { return localStorage.getItem(CHIAVE_MENU_RIDOTTO) === '1'; } catch (e) { return false; }
    }
    function applicaMenuRidotto(ridotto) {
        const app = document.getElementById('app');
        if (app) app.classList.toggle('menu-ridotto', !!ridotto);
        const b = document.getElementById('nav-riduci');
        if (!b) return;
        const etich = ridotto ? 'Allarga il menu' : 'Riduci il menu';
        b.setAttribute('aria-pressed', ridotto ? 'true' : 'false');
        b.setAttribute('aria-label', etich);
        b.setAttribute('title', etich);
    }
    function collegaRiduciMenu() {
        const b = document.getElementById('nav-riduci');
        if (!b || b._collegato) return;
        b._collegato = true;
        applicaMenuRidotto(menuRidotto());
        b.addEventListener('click', () => {
            const nuovo = !menuRidotto();
            try { localStorage.setItem(CHIAVE_MENU_RIDOTTO, nuovo ? '1' : '0'); } catch (e) { }
            segnalaMovimentoBarra();
            applicaMenuRidotto(nuovo);
            /* Il grafico a barre e' disegnato su una tela la cui larghezza viene
               scritta in linea al momento del disegno: allargando il contenuto
               resterebbe della misura di prima, con una striscia bianca dentro
               la scheda. Si ridisegna solo dove c'e' davvero (il cruscotto):
               ridisegnare sempre costerebbe un rifacimento della vista a ogni
               clic, e sugli elenchi lunghi si vedrebbe. Il ridisegno aspetta
               che la barra abbia finito di muoversi. */
            ridisegnaGraficoTela();
        });
        collegaAperturaAlPassaggio(b);
    }

    /* La tela del grafico a barre (la sola dell'area: sta in Fatturazione) ha la
       larghezza scritta DENTRO l'elemento al momento del disegno, quindi
       cambiando la larghezza del contenuto resterebbe della misura di prima,
       con una striscia bianca dentro la scheda. Gli altri grafici sono in SVG e
       si adattano da soli: qui non c'e' niente da fare per loro.
       La condizione guarda se la tela C'E', non in quale sezione siamo: prima
       chiedeva "sono nel cruscotto", ma la tela sta in Fatturazione, quindi il
       ridisegno non e' mai scattato. Si rifa' la vista solo dove serve davvero:
       rifarla sempre, sugli elenchi lunghi, si vedrebbe.
       Il ritardo raggruppa i passaggi ravvicinati (entra ed esce dalla barra)
       in un ridisegno solo, e aspetta che la barra abbia finito di muoversi:
       rifare la vista mentre la transizione e' in corso costerebbe proprio i
       fotogrammi che la transizione serve a guadagnare. */
    let _timerTela = null;
    function ridisegnaGraficoTela() {
        if (!document.getElementById('grafico-mesi')) return;
        const vista = vistaCorrente, parametri = parametriVista;
        clearTimeout(_timerTela);
        _timerTela = setTimeout(() => {
            if (vistaCorrente === vista && document.getElementById('grafico-mesi'))
                naviga(vista, parametri, window.scrollY);
        }, DURATA_MOVIMENTO + 20);
    }

    /* APERTURA DELLA BARRA AL PASSAGGIO DEL MOUSE
       A menu ridotto, portando il mouse sulla barra questa si riapre per intero
       e il contenuto RIENTRA di altrettanto, invece di finirle sotto.
       Il ritardo di intenzione e' la parte che conta. Muovere la pagina si
       vede, e non deve succedere perche' il mouse ha sfiorato il bordo sinistro
       andando altrove (per esempio verso la casella di selezione della prima
       colonna, che sta proprio li'). Centodieci millisecondi separano il "ci
       sto andando" dal "ci sono passato sopra": abbastanza da non scattare per
       un passaggio di striscio, poco abbastanza da non farsi aspettare.
       In chiusura nessun ritardo, ma una condizione sola: che il mouse sia
       USCITO DAVVERO. Dentro la barra ci si puo' muovere, cliccare una
       sezione, aspettare che si ridisegni: finche' il puntatore e' li' sopra,
       la barra resta aperta.
       La tastiera ha una strada sua: chi arriva col tabulatore ha bisogno delle
       etichette subito, senza aspettare. */
    const RITARDO_APERTURA = 110;
    /* Dove si e' visto il puntatore l'ultima volta: serve a distinguere un
       fuoco che se ne va perche' si e' cliccato altrove da un fuoco che se ne
       va mentre il mouse e' fermo sulla barra. Due numeri e non un oggetto:
       si aggiornano a ogni movimento del mouse. */
    let puntX = -1, puntY = -1;
    /* Quanto dura il movimento: i 170ms della transizione (--durata-menu nel
       foglio di stile) piu' un margine, perche' la classe che alleggerisce il
       movimento vada via DOPO che si e' fermato, non un attimo prima. */
    const DURATA_MOVIMENTO = 230;
    let _timerMoto = null;
    /* La barra sta cambiando misura: per tutta la durata del movimento il
       foglio di stile dispone il contenuto della barra alla misura di arrivo e
       lo scopre man mano, e svincola la tabella degli iscritti dal contenitore,
       invece di rifare l'impaginazione a ogni fotogramma. Serve a ogni cambio
       di larghezza: il passaggio del mouse e anche il pulsante che riduce. */
    function segnalaMovimentoBarra() {
        const app = document.getElementById('app');
        if (!app) return;
        app.classList.add('barra-in-moto');
        clearTimeout(_timerMoto);
        _timerMoto = setTimeout(() => app.classList.remove('barra-in-moto'), DURATA_MOVIMENTO);
    }
    function collegaAperturaAlPassaggio(pulsante) {
        const barra = document.querySelector('.sidebar');
        const app = document.getElementById('app');
        if (!barra || !app || barra._passaggio) return;
        barra._passaggio = true;
        let timer = null;
        /* La barra e' fissata in alto a sinistra e alta quanto la finestra:
           per sapere se il puntatore ci sta sopra basta la sua larghezza.
           Si legge dalla variabile e si tiene da parte, invece di misurare
           l'elemento a ogni movimento del mouse: la variabile vale gia' la
           misura di ARRIVO anche mentre la barra si sta aprendo (le variabili
           non si animano, cambiano di colpo), quindi spostandosi verso destra
           dentro una barra ancora in movimento non si finisce "fuori" per un
           attimo, con la barra che si richiude e si riapre da sola. */
        let larghezzaAperta = 0;
        const dentroLaBarra = (x, y) =>
            x >= 0 && x < larghezzaAperta && y >= 0 && y < window.innerHeight;
        const apri = () => {
            if (app.classList.contains('barra-aperta')) return;
            segnalaMovimentoBarra();
            app.classList.add('barra-aperta');
            larghezzaAperta = parseFloat(getComputedStyle(app).getPropertyValue('--larghezza-menu')) || 0;
            ridisegnaGraficoTela();
        };
        const chiudi = () => {
            clearTimeout(timer); timer = null;
            if (!app.classList.contains('barra-aperta')) return;
            segnalaMovimentoBarra();
            app.classList.remove('barra-aperta');
            ridisegnaGraficoTela();
        };
        barra.addEventListener('mouseenter', () => {
            if (!app.classList.contains('menu-ridotto')) return;
            clearTimeout(timer);
            timer = setTimeout(apri, RITARDO_APERTURA);
        });
        /* CHIUSURA: si guarda DOV'E' il puntatore, non cosa dice l'evento.
           Ogni volta che le voci del menu vengono ridisegnate - un clic su una
           sezione, ma anche dati arrivati dalla sincronizzazione - il pulsante
           che sta sotto il mouse viene distrutto, e il browser manda un
           "mouseleave" alla barra anche se il mouse non si e' mosso di un
           pixel. Bastava a richiuderla proprio mentre la si stava usando: si
           sceglieva una sezione e il menu se ne andava sotto le dita. Se le
           coordinate dell'uscita cadono ancora dentro la barra, l'uscita e'
           finta e non si chiude niente. */
        barra.addEventListener('mouseleave', e => {
            if (!dentroLaBarra(e.clientX, e.clientY)) chiudi();
        });
        /* Rete di sicurezza per le uscite finte: dopo una di quelle il browser
           considera il mouse gia' fuori, quindi quando esce davvero non manda
           nessun altro "mouseleave" e la barra resterebbe aperta per sempre.
           Finche' e' aperta si guarda il movimento del mouse sulla pagina:
           appena esce dal rettangolo della barra, si chiude. Il primo controllo
           e' una classe, cioe' niente, per le altre novantanove volte su cento
           in cui la barra e' chiusa e il mouse si muove per i fatti suoi. */
        document.addEventListener('mousemove', e => {
            puntX = e.clientX; puntY = e.clientY;
            if (!app.classList.contains('barra-aperta')) return;
            if (!dentroLaBarra(puntX, puntY)) chiudi();
        }, { passive: true });
        /* Ultima rete: il mouse esce dalla finestra (la barra del browser, un
           altro programma, un altro schermo) mentre la barra e' aperta. Qui il
           "mouseleave" del documento si puo' usare senza guardare le
           coordinate, perche' ridisegnare le voci non lo fa scattare: il
           documento non viene distrutto, le voci si'. */
        document.addEventListener('mouseleave', chiudi);
        barra.addEventListener('focusin', () => { if (app.classList.contains('menu-ridotto')) apri(); });
        barra.addEventListener('focusout', e => {
            /* si chiude solo quando il fuoco esce DAVVERO dalla barra: passando
               da una voce all'altra il focusout scatta lo stesso. Se pero' il
               mouse e' rimasto sulla barra, la barra resta aperta: comanda chi
               ci sta sopra, non chi se n'e' andato. */
            if (barra.contains(e.relatedTarget)) return;
            if (dentroLaBarra(puntX, puntY)) return;
            chiudi();
        });
        /* Allargando il menu col pulsante la barra resta sotto il mouse: senza
           questo, la classe di passaggio resterebbe accesa e richiudendo il
           menu il contenuto non tornerebbe largo finche' il mouse non se ne va. */
        if (pulsante) pulsante.addEventListener('click', chiudi);
        /* Ridimensionando la finestra la misura della barra puo' cambiare
           (sotto i 901px il menu diventa quello a comparsa e la variabile va a
           zero): la misura tenuta da parte va rinfrescata, altrimenti la barra
           resterebbe aperta con un rettangolo che non esiste piu'. */
        window.addEventListener('resize', () => {
            if (app.classList.contains('barra-aperta'))
                larghezzaAperta = parseFloat(getComputedStyle(app).getPropertyValue('--larghezza-menu')) || 0;
        }, { passive: true });
    }

    /* menu a comparsa su smartphone */
    function chiudiMenuMobile() {
        const sidebar = document.querySelector('.sidebar');
        const ham = document.getElementById('nav-hamburger');
        if (sidebar) sidebar.classList.remove('menu-aperto');
        if (ham) ham.setAttribute('aria-expanded', 'false');
    }
    function collegaHamburger() {
        const ham = document.getElementById('nav-hamburger');
        if (!ham || ham._collegato) return;
        ham._collegato = true;
        ham.addEventListener('click', () => {
            const sidebar = document.querySelector('.sidebar');
            const aperto = sidebar.classList.toggle('menu-aperto');
            ham.setAttribute('aria-expanded', aperto ? 'true' : 'false');
        });
    }

    /* =========================================================
       VISTA: CRUSCOTTO
    ========================================================= */
    function vistaDashboard() {
        const incarichi = Incarichi.visibili();
        const anno = annoCorrente();
        /* Perimetro dei numeri: un ruolo limitato per regione (coordinatore e vice) vede
           qui solo il proprio territorio, e il cruscotto deve dirlo. Prima la descrizione
           parlava di "quadro generale" a chiunque: gli stessi riquadri sembravano i totali
           dello studio. Per gli altri ruoli non cambia nulla. */
        const regioniRuolo = regioniDelRuolo();
        const descrizioneAmbito = !regioniRuolo
            ? 'Quadro generale degli incarichi di revisione e dei compensi.'
            : regioniRuolo.length
                ? `Incarichi di revisione e compensi delle regioni che ti sono assegnate: <strong>${esc(regioniRuolo.join(', '))}</strong>. Gli incarichi delle altre regioni non entrano in questi riepiloghi.`
                : 'Il tuo ruolo è limitato alle regioni assegnate, ma sulla tua scheda non ne risulta spuntata nessuna: finché non le indica l\'amministratore non vedi alcun incarico.';
        // le proposte stanno fuori dagli attivi: sono in attesa di conferma e non contano nei totali
        const proposte = incarichi.filter(i => i.stato === 'proposta');
        const attivi = incarichi.filter(i => i.stato !== 'cessato' && i.stato !== 'dimesso' && i.stato !== 'proposta' && i.stato !== 'nonAccettato');
        // compensoContabile azzera gli anni in proposta: totali e confronto restano su cio' che e' confermato
        const totAnno = incarichi.reduce((s, i) => s + compensoContabile(i, anno), 0);
        const totPrec = incarichi.reduce((s, i) => s + compensoContabile(i, anno - 1), 0);
        const delta = totPrec ? ((totAnno - totPrec) / totPrec * 100) : null;
        const inScadenza = attivi.filter(i => Incarichi.statoScadenza(i).classe === 'ambra');
        const scaduti = attivi.filter(i => Incarichi.statoScadenza(i).classe === 'rosso');
        const volontarie = attivi.filter(i => i.tipo === 'volontaria').length;
        // valore delle proposte in attesa (per l'anno in corso), per la card di riepilogo
        const propostoTot = proposte.reduce((s, i) => s + Incarichi.compensoAnno(i, anno), 0);
        // allerte di sblocco calcolo: visibili solo al titolare
        const allerte = Auth.eProprietario() ? Allerte.attive() : [];
        const puoRinnovare = Auth.puoScrivere('incarichi');
        // fatturato dell'anno a rischio (incarichi in scadenza / scaduti)
        const scadenzaTot = inScadenza.reduce((s, i) => s + Incarichi.compensoAnno(i, anno), 0);
        const scadutoTot = scaduti.reduce((s, i) => s + Incarichi.compensoAnno(i, anno), 0);

        $vista().innerHTML = `
            <header>
                <div>
                    <h1>Cruscotto</h1>
                    <p class="descrizione">${descrizioneAmbito}</p>
                </div>
                <div class="header-azioni">
                    ${Auth.puoScrivere('incarichi') ? '<button class="btn btn-primary" id="btn-nuovo-incarico">+ Nuovo incarico</button>' : ''}
                </div>
            </header>
            ${allerte.length ? `<div class="card" style="border-left:4px solid var(--rosso);">
                <h2>${ICO_ALLERTA}Allerte (${allerte.length})</h2>
                ${allerte.slice(0, 20).map(a => `<div class="storia-voce" style="border-left-color:var(--rosso);">
                    <div class="quando">${fmtDataOra(a.ts)}</div>
                    <div><span class="chi">${esc(a.da || '')}</span> ha sbloccato il calcolo di <strong>${esc(a.cliente || '')}</strong></div>
                    <div class="campi">"${esc(a.messaggio || '')}"</div>
                    <button class="btn btn-sm btn-ghost a-letta" data-id="${esc(a.id)}" style="margin-top:4px;">Segna come letta</button>
                </div>`).join('')}
            </div>` : ''}
            <div class="kpi-griglia">
                <div class="kpi"><div class="etichetta">Incarichi attivi</div><div class="valore">${attivi.length}</div><div class="nota">${volontarie} volontari, ${attivi.length - volontarie} altri</div></div>
                <div class="kpi verde"><div class="etichetta">Compensi ${anno}</div><div class="valore">${eurFmt.format(totAnno)}</div><div class="nota">${delta == null ? 'nessun confronto disponibile' : (delta >= 0 ? '+' : '') + delta.toFixed(1) + '% rispetto al ' + (anno - 1)}</div></div>
                <div class="kpi ambra"><div class="etichetta">In scadenza (6 mesi)</div><div class="valore">${inScadenza.length}</div><div class="nota">${eurFmt.format(scadenzaTot)} di fatturato</div></div>
                <div class="kpi rosso"><div class="etichetta">Scaduti</div><div class="valore">${scaduti.length}</div><div class="nota">${eurFmt.format(scadutoTot)} di fatturato</div></div>
                ${proposte.length ? `<div class="kpi proposta"><div class="etichetta">Proposte da confermare</div><div class="valore">${proposte.length}</div><div class="nota">${eurFmt.format(propostoTot)} non ancora conteggiati</div></div>` : ''}
            </div>
            ${proposte.length ? `<div class="card card-proposte">
                <h2>${ICO_PROPOSTA}Proposte in attesa di conferma (${proposte.length})</h2>
                <p class="descrizione" style="margin-bottom:12px;">Questi incarichi sono nuovi o rinnovati e restano in <strong>proposta</strong>: <strong>non entrano in fatturazione e nei compensi</strong> finché non li confermi. Premi <strong>Conferma</strong> se il cliente ha accettato; <strong>Modifica</strong> per rielaborare la proposta e rigenerare il PDF della lettera; <strong>Non accettato</strong> se il cliente ha rifiutato (l'incarico finisce nella scheda "Non accettati" della sezione Incarichi).</p>
                <div class="tabella-wrap"><table class="dati a-schede"><thead><tr>
                    <th>Cliente</th><th>Tipo</th><th>Periodo</th><th class="num">Compenso proposto</th>${puoRinnovare ? '<th></th>' : ''}
                </tr></thead><tbody>${proposte.map(i => {
                const anniP = anniPeriodoProposto(i);
                const periodo = anniP && anniP.length ? (anniP.length > 1 ? anniP[0] + '-' + anniP[anniP.length - 1] : String(anniP[0])) : '';
                const compP = anniP && anniP.length ? anniP.reduce((s, a) => s + Incarichi.compensoAnno(i, a), 0) : 0;
                return `<tr class="cliccabile riga-proposta" data-apri="${esc(i.id)}">
                        <td class="cliente-cella" data-label="Cliente">${esc(i.cliente)}</td>
                        <td data-label="Tipo">${badgeTipo(i.tipo)}</td>
                        <td data-label="Periodo">${esc(periodo)}</td>
                        <td class="num" data-label="Compenso proposto">${compP ? eurFmt.format(compP) : ''}</td>
                        ${puoRinnovare ? `<td data-label="" class="td-azioni" style="white-space:nowrap;"><button class="btn btn-sm btn-secondary" data-modifica="${esc(i.id)}">Modifica</button> <button class="btn btn-sm btn-secondary" data-non-accettato="${esc(i.id)}">Non accettato</button> <button class="btn btn-sm btn-primary" data-conferma="${esc(i.id)}">Conferma</button></td>` : ''}
                    </tr>`;
            }).join('')}</tbody></table></div>
            </div>` : ''}
            <div class="card">
                <h2>Andamento compensi per anno</h2>
                <p class="hint" style="margin:-6px 0 10px;">Passa sopra le barre per il dettaglio. Nell'anno in corso il fatturato <span style="color:#C9A227;font-weight:600;">in scadenza</span> e <span style="color:#C0392B;font-weight:600;">scaduto</span> è evidenziato nella barra.</p>
                <div id="grafico-compensi"></div>
            </div>
            <div class="card" id="sez-scadenze-dash">
                <h2>Incarichi in scadenza o scaduti</h2>
                ${tabellaScadenze(scaduti.concat(inScadenza))}
            </div>`;

        { const bni = document.getElementById('btn-nuovo-incarico'); if (bni) bni.addEventListener('click', () => naviga('wizard', { modalita: 'nuovo' })); }
        $vista().querySelectorAll('.a-letta').forEach(b =>
            b.addEventListener('click', () => { Allerte.segnaLetta(b.dataset.id); vistaDashboard(); }));
        $vista().querySelectorAll('[data-apri]').forEach(r =>
            r.addEventListener('click', () => naviga('dettaglio', { id: r.dataset.apri })));
        $vista().querySelectorAll('[data-modifica]').forEach(b =>
            b.addEventListener('click', e => {
                e.stopPropagation();
                naviga('wizard', { modalita: 'modifica', id: b.dataset.modifica });
            }));
        $vista().querySelectorAll('[data-non-accettato]').forEach(b =>
            b.addEventListener('click', e => {
                e.stopPropagation();
                const inc = Incarichi.trova(b.dataset.nonAccettato);
                if (inc) modaleNonAccettatoIncarico(inc, () => vistaDashboard());
            }));
        $vista().querySelectorAll('[data-rinnova]').forEach(b =>
            b.addEventListener('click', e => {
                e.stopPropagation();
                naviga('wizard', { modalita: 'rinnovo', id: b.dataset.rinnova });
            }));
        $vista().querySelectorAll('[data-termina]').forEach(b =>
            b.addEventListener('click', e => {
                e.stopPropagation();
                const inc = Incarichi.trova(b.dataset.termina);
                if (inc) modaleTerminaIncarico(inc, () => vistaDashboard());
            }));
        $vista().querySelectorAll('[data-conferma]').forEach(b =>
            b.addEventListener('click', e => {
                e.stopPropagation();
                const inc = Incarichi.trova(b.dataset.conferma);
                if (inc) modaleConfermaIncarico(inc, () => vistaDashboard());
            }));
        const tScad = $vista().querySelector('#sez-scadenze-dash table.dati');
        if (tScad) attrezzaTabella(tScad, { ricerca: true, nomeFile: 'incarichi-in-scadenza' });
        disegnaGraficoCompensiSvg('grafico-compensi', anno);
    }

    function tabellaScadenze(lista) {
        if (!lista.length) return '<p class="tabella-vuota">Nessun incarico in scadenza nei prossimi sei mesi.</p>';
        const puoRinnovare = Auth.puoScrivere('incarichi');
        return `<div class="tabella-wrap"><table class="dati a-schede"><thead><tr>
            <th>Cliente</th><th>Tipo</th><th>Scadenza</th><th>Resp. incarico</th><th>Qualità</th><th>Stato</th>${puoRinnovare ? '<th></th>' : ''}
        </tr></thead><tbody>` + lista.map(i => {
            const s = Incarichi.statoScadenza(i);
            return `<tr class="cliccabile" data-apri="${esc(i.id)}">
                <td class="cliente-cella" data-label="Cliente">${esc(i.cliente)}</td>
                <td data-label="Tipo">${badgeTipo(i.tipo)}</td>
                <td data-label="Scadenza">${esc(fmtData(i.rinnovo || i.dataFine))}</td>
                <td data-label="Resp. incarico">${esc(i.respIncarico || '')}</td>
                <td data-label="Qualità">${esc(i.qualita || '')}</td>
                <td data-label="Stato"><span class="badge ${s.classe}">${esc(s.testo)}</span></td>
                ${puoRinnovare ? `<td data-label="" style="white-space:nowrap;"><button class="btn btn-sm btn-secondary" data-rinnova="${esc(i.id)}">Rinnova</button> <button class="btn btn-sm btn-secondary" data-termina="${esc(i.id)}">Termina</button></td>` : ''}
            </tr>`;
        }).join('') + '</tbody></table></div>';
    }

    /* =========================================================
       VISTA: ELENCO INCARICHI
    ========================================================= */
    const filtriIncarichi = { testo: '', tipo: '', area: '', regione: '', qualita: '', resp: '', stato: '', ordina: 'cliente', verso: 1 };
    let incarichiTab = 'attivi'; // scheda incarichi: 'attivi' | 'terminati' | 'dismessi' | 'nonaccettati'

    function annoRiferimento() {
        const anni = Incarichi.anniConCompensi();
        return Math.min(Math.max(annoCorrente(), anni[0]), anni[anni.length - 1]);
    }

    /* Unione tra roster e valori presenti negli incarichi (anche importati) */
    function valoriPresenti(campo, base) {
        const presenti = Incarichi.visibili().map(i => i[campo]).filter(Boolean);
        return Array.from(new Set((base || []).concat(presenti))).sort();
    }

    function vistaIncarichi() {
        const annoRif = annoRiferimento();
        const listaAree = valoriPresenti('area', RV_ROSTER.aree);
        const listaQualita = valoriPresenti('qualita', Persone.attiveEtichette('qualita'));
        const listaResp = valoriPresenti('respIncarico', Persone.attiveEtichette('respIncarico'));

        $vista().innerHTML = `
            <header>
                <div>
                    <h1>Incarichi</h1>
                    <p class="descrizione">Elenco completo degli incarichi con team, scadenze e compensi. Fai clic su una riga per aprire il dettaglio.</p>
                </div>
                <div class="header-azioni">
                    <button class="btn btn-secondary" id="btn-esporta-csv">Esporta CSV</button>
                    ${Auth.puoScrivere('incarichi') ? '<button class="btn btn-primary" id="btn-nuovo-incarico">+ Nuovo incarico</button>' : ''}
                </div>
            </header>
            <div class="filtri">
                <div class="campo ricerca"><label>Ricerca</label><input type="text" id="f-testo" placeholder="Cliente, codice fiscale, regione..." value="${esc(filtriIncarichi.testo)}"></div>
                ${comboFiltro('f-tipo', 'Tipo', Object.keys(TIPI).map(t => TIPI[t]), filtriIncarichi.tipo)}
                ${comboFiltro('f-area', 'Area', listaAree, filtriIncarichi.area)}
                ${comboFiltro('f-regione', 'Regione', valoriPresenti('regione', RV_ROSTER.regioni), filtriIncarichi.regione)}
                ${comboFiltro('f-qualita', 'Qualità', listaQualita, filtriIncarichi.qualita)}
                ${comboFiltro('f-resp', 'Resp. incarico', listaResp, filtriIncarichi.resp)}
                ${comboFiltro('f-stato', 'Stato', ['Attivi', 'In scadenza', 'Scaduti'], filtriIncarichi.stato)}
            </div>
            <div id="contenitore-tabella"></div>`;

        const aggiorna = () => {
            filtriIncarichi.testo = document.getElementById('f-testo').value;
            filtriIncarichi.tipo = document.getElementById('f-tipo').value;
            filtriIncarichi.area = document.getElementById('f-area').value;
            filtriIncarichi.regione = document.getElementById('f-regione').value;
            filtriIncarichi.qualita = document.getElementById('f-qualita').value;
            filtriIncarichi.resp = document.getElementById('f-resp').value;
            filtriIncarichi.stato = document.getElementById('f-stato').value;
            disegnaTabellaIncarichi(annoRif);
        };
        ['f-testo', 'f-tipo', 'f-area', 'f-regione', 'f-qualita', 'f-resp', 'f-stato'].forEach(id =>
            document.getElementById(id).addEventListener('input', aggiorna));
        { const bni = document.getElementById('btn-nuovo-incarico'); if (bni) bni.addEventListener('click', () => naviga('wizard', { modalita: 'nuovo' })); }
        document.getElementById('btn-esporta-csv').addEventListener('click', esportaCsvIncarichi);
        disegnaTabellaIncarichi(annoRif);
    }

    function incarichiFiltrati(annoRif, statoOverride) {
        const f = filtriIncarichi;
        const stato = statoOverride !== undefined ? statoOverride : f.stato;
        if (!annoRif) annoRif = annoRiferimento();
        let lista = Incarichi.visibili();
        if (f.testo) {
            const t = f.testo.toLowerCase();
            lista = lista.filter(i =>
                (i.cliente || '').toLowerCase().includes(t) ||
                (i.codiceFiscale || '').toLowerCase().includes(t) ||
                (i.regione || '').toLowerCase().includes(t) ||
                (i.referente || '').toLowerCase().includes(t) ||
                (i.team || '').toLowerCase().includes(t));
        }
        // i filtri sono "combinati": testo digitato o suggerimento scelto, confronto "contiene"
        if (f.tipo) lista = lista.filter(i => filtroCorrisponde(TIPI[i.tipo] || i.tipo, f.tipo));
        if (f.area) lista = lista.filter(i => filtroCorrisponde(i.area, f.area));
        if (f.regione) lista = lista.filter(i => filtroCorrisponde(i.regione, f.regione));
        if (f.qualita) lista = lista.filter(i => filtroCorrisponde(i.qualita, f.qualita));
        if (f.resp) lista = lista.filter(i => filtroCorrisponde(i.respIncarico, f.resp));
        // stato: dall'esterno arriva la chiave (es. 'cessato'); dal filtro arriva il testo
        // digitato, che puo' corrispondere a piu' voci (es. "sca" = In scadenza + Scaduti)
        const controllaStato = (i, st) => {
            const s = Incarichi.statoScadenza(i);
            // "neutro" su un incarico non cessato significa "senza scadenza": e attivo
            if (st === 'attivo') return i.stato !== 'cessato' && i.stato !== 'dimesso' && i.stato !== 'nonAccettato' && (s.classe === 'verde' || s.classe === 'neutro');
            if (st === 'scadenza') return s.classe === 'ambra';
            if (st === 'scaduto') return s.classe === 'rosso';
            if (st === 'cessato') return i.stato === 'cessato';
            if (st === 'dimesso') return i.stato === 'dimesso';
            if (st === 'nonAccettato') return i.stato === 'nonAccettato';
            return true;
        };
        if (statoOverride !== undefined) {
            if (statoOverride) lista = lista.filter(i => controllaStato(i, statoOverride));
        } else if (stato && String(stato).trim()) {
            const chiavi = [['attivo', 'Attivi'], ['scadenza', 'In scadenza'], ['scaduto', 'Scaduti']]
                .filter(([, etich]) => filtroCorrisponde(etich, stato)).map(([k]) => k);
            lista = lista.filter(i => chiavi.some(k => controllaStato(i, k)));
        }
        const chiave = f.ordina, verso = f.verso;
        lista.sort((a, b) => {
            let va, vb;
            if (chiave === 'compenso') { va = Incarichi.compensoAnno(a, annoRif); vb = Incarichi.compensoAnno(b, annoRif); }
            else if (chiave === 'scadenza') { va = a.rinnovo || a.dataFine || ''; vb = b.rinnovo || b.dataFine || ''; }
            else { va = (a[chiave] || '').toString().toLowerCase(); vb = (b[chiave] || '').toString().toLowerCase(); }
            return (va < vb ? -1 : va > vb ? 1 : 0) * verso;
        });
        return lista;
    }

    // chiude tutti i menu azioni a comparsa (clic altrove, scorrimento, ridimensionamento)
    function chiudiMenuAzioni() {
        document.querySelectorAll('.menu-azioni.aperto').forEach(m => m.classList.remove('aperto'));
        // il pulsante torna "chiuso": lo dicono sia il lettore di schermo sia l'evidenziazione
        document.querySelectorAll('.menu-azioni-apri[aria-expanded="true"]').forEach(b => b.setAttribute('aria-expanded', 'false'));
    }
    document.addEventListener('click', chiudiMenuAzioni);
    window.addEventListener('scroll', chiudiMenuAzioni, true);
    window.addEventListener('resize', chiudiMenuAzioni);

    function disegnaTabellaIncarichi(annoRif) {
        const cont = document.getElementById('contenitore-tabella');
        const puoRinnovare = Auth.puoScrivere('incarichi');
        // l'eliminazione definitiva e' di admin/titolare: puo' esserci la colonna azioni
        // anche per chi non ha la scrittura, con il solo pulsante Elimina
        const puoEliminare = Auth.puoEliminareIncarichi();
        const colAzioni = puoRinnovare || puoEliminare;
        const btnElimina = i => puoEliminare ? ` <button class="btn btn-sm btn-danger" data-elimina="${esc(i.id)}">Elimina</button>` : '';
        // modalita compatta: nella riga resta un solo pulsante, le azioni compaiono in un
        // menu a comparsa e la riga resta bassa. I tre puntini da soli non si leggevano
        // come un comando: ci vuole la parola "Azioni" e il bordo del pulsante.
        // L'intestazione della colonna resta vuota di proposito: attrezzaTabella e
        // l'esportazione CSV saltano le colonne senza titolo, ed e' cosi che la colonna
        // dei comandi non finisce tra i filtri e nel file esportato.
        const menuAzioni = bottoni => (bottoni && bottoni.trim())
            ? `<button class="btn btn-sm btn-secondary menu-azioni-apri" data-menu aria-haspopup="true" aria-expanded="false" title="Azioni disponibili su questo incarico">Azioni<span class="menu-azioni-punti" aria-hidden="true">&#8942;</span></button><div class="menu-azioni">${bottoni}</div>`
            : '';
        // attivi: rispetta il filtro di stato (attivo/scadenza/scaduto). terminati: ignora il filtro di stato
        // (che riguarda solo gli attivi) cosi restano sempre visibili nella loro scheda.
        const attivi = incarichiFiltrati(annoRif).filter(i => i.stato !== 'cessato' && i.stato !== 'dimesso' && i.stato !== 'nonAccettato');
        const terminati = incarichiFiltrati(annoRif, 'cessato');
        const dismessi = incarichiFiltrati(annoRif, 'dimesso');
        const nonAccettati = incarichiFiltrati(annoRif, 'nonAccettato');

        // ogni gruppo (attivi / terminati / dismessi / non accettati) ha la sua scheda invece di stare in sequenza
        const tabBar = `<div class="tab-dest" style="margin-bottom:16px;">
            <button class="tab-btn ${incarichiTab === 'attivi' ? 'attivo' : ''}" data-inctab="attivi">Attivi (${attivi.length})</button>
            <button class="tab-btn ${incarichiTab === 'terminati' ? 'attivo' : ''}" data-inctab="terminati">Terminati (${terminati.length})</button>
            <button class="tab-btn ${incarichiTab === 'dismessi' ? 'attivo' : ''}" data-inctab="dismessi">Dismessi (${dismessi.length})</button>
            <button class="tab-btn ${incarichiTab === 'nonaccettati' ? 'attivo' : ''}" data-inctab="nonaccettati">Non accettati (${nonAccettati.length})</button>
        </div>`;

        let corpo;
        if (incarichiTab === 'nonaccettati') {
            corpo = nonAccettati.length ? `<div class="card" id="sez-non-accettati">
                <p class="descrizione" style="margin:0 0 12px;">Proposte di incarico che il cliente <strong>non ha accettato</strong>: non entrano in fatturazione e nei compensi. Premi <strong>Riporta in proposta</strong> per rielaborare l'incarico (modificarlo e rigenerare il PDF della lettera) e ripetere la fase di conferma.</p>
                <div class="tabella-wrap"><table class="dati a-schede compatta"><thead><tr>
                    <th>Cliente</th><th>Tipo</th><th>Periodo proposto</th><th class="num">Compenso proposto</th><th>Non accettato il</th><th>Motivo</th>${colAzioni ? '<th></th>' : ''}
                </tr></thead><tbody>` +
                nonAccettati.map(i => {
                    const anniP = anniPeriodoProposto(i);
                    const periodo = anniP && anniP.length ? (anniP.length > 1 ? anniP[0] + '-' + anniP[anniP.length - 1] : String(anniP[0])) : '';
                    const compP = anniP && anniP.length ? anniP.reduce((s, a) => s + Incarichi.compensoAnno(i, a), 0) : 0;
                    return `<tr class="cliccabile" data-apri="${esc(i.id)}">
                    <td class="cliente-cella" data-label="Cliente">${esc(i.cliente)}</td>
                    <td data-label="Tipo">${badgeTipo(i.tipo)}</td>
                    <td data-label="Periodo proposto">${esc(periodo)}</td>
                    <td class="num" data-label="Compenso proposto">${compP ? eurFmt.format(compP) : ''}</td>
                    <td data-label="Non accettato il">${i.nonAccettato ? esc(fmtDataOra(i.nonAccettato.il)) : ''}</td>
                    <td data-label="Motivo">${esc((i.nonAccettato && i.nonAccettato.nota) || '')}</td>
                    ${colAzioni ? `<td data-label="" class="td-azioni td-menu">${menuAzioni((puoRinnovare ? `<button class="btn btn-sm btn-secondary" data-riproponi="${esc(i.id)}">Riporta in proposta</button>` : '') + btnElimina(i))}</td>` : ''}
                </tr>`;
                }).join('') +
                `</tbody></table></div></div>`
                : '<div class="card tabella-vuota">Nessuna proposta non accettata.</div>';
        } else if (incarichiTab === 'dismessi') {
            corpo = dismessi.length ? `<div class="card" id="sez-dismessi">
                <p class="descrizione" style="margin:0 0 12px;">Incarichi da cui il revisore si è dimesso, con la data delle dimissioni. Apri una riga per il dettaglio o premi <strong>Riattiva</strong> per riportarlo tra gli attivi.</p>
                <div class="tabella-wrap"><table class="dati a-schede compatta"><thead><tr>
                    <th>Cliente</th><th>Tipo</th><th>Regione</th><th>Resp. incarico</th><th>Data dimissioni</th><th>Registrate il</th>${colAzioni ? '<th></th>' : ''}
                </tr></thead><tbody>` +
                dismessi.map(i => `<tr class="cliccabile" data-apri="${esc(i.id)}">
                    <td class="cliente-cella" data-label="Cliente">${esc(i.cliente)}</td>
                    <td data-label="Tipo">${badgeTipo(i.tipo)}</td>
                    <td data-label="Regione">${esc(i.regione || '')}</td>
                    <td data-label="Resp. incarico">${esc(i.respIncarico || '')}</td>
                    <td data-label="Data dimissioni">${i.dimissioni && i.dimissioni.data ? esc(fmtData(i.dimissioni.data)) : ''}</td>
                    <td data-label="Registrate il">${i.dimissioni ? esc(fmtDataOra(i.dimissioni.il)) : ''}</td>
                    ${colAzioni ? `<td data-label="" class="td-azioni td-menu">${menuAzioni((puoRinnovare ? `<button class="btn btn-sm btn-secondary" data-riattiva="${esc(i.id)}">Riattiva</button>` : '') + btnElimina(i))}</td>` : ''}
                </tr>`).join('') +
                `</tbody></table></div></div>`
                : '<div class="card tabella-vuota">Nessun incarico dismesso.</div>';
        } else if (incarichiTab === 'terminati') {
            corpo = terminati.length ? `<div class="card" id="sez-terminati">
                <p class="descrizione" style="margin:0 0 12px;">Incarichi conclusi, tenuti fuori dall'elenco principale. Apri una riga per il dettaglio o premi <strong>Riattiva</strong> per riportarlo tra gli attivi.</p>
                <div class="tabella-wrap"><table class="dati a-schede compatta"><thead><tr>
                    <th>Cliente</th><th>Tipo</th><th>Regione</th><th>Fine</th><th>Resp. incarico</th><th>Terminato il</th>${colAzioni ? '<th></th>' : ''}
                </tr></thead><tbody>` +
                terminati.map(i => `<tr class="cliccabile" data-apri="${esc(i.id)}">
                    <td class="cliente-cella" data-label="Cliente">${esc(i.cliente)}</td>
                    <td data-label="Tipo">${badgeTipo(i.tipo)}</td>
                    <td data-label="Regione">${esc(i.regione || '')}</td>
                    <td data-label="Fine">${esc(fmtData(i.rinnovo || i.dataFine))}</td>
                    <td data-label="Resp. incarico">${esc(i.respIncarico || '')}</td>
                    <td data-label="Terminato il">${i.terminato ? esc(fmtDataOra(i.terminato.il)) : ''}</td>
                    ${colAzioni ? `<td data-label="" class="td-azioni td-menu">${menuAzioni((puoRinnovare ? `<button class="btn btn-sm btn-secondary" data-riattiva="${esc(i.id)}">Riattiva</button>` : '') + btnElimina(i))}</td>` : ''}
                </tr>`).join('') +
                `</tbody></table></div></div>`
                : '<div class="card tabella-vuota">Nessun incarico terminato.</div>';
        } else {
            // le proposte compaiono qui evidenziate, ma il loro compenso non entra nel totale
            const totale = attivi.reduce((s, i) => s + compensoContabile(i, annoRif), 0);
            const nProposte = attivi.filter(inProposta).length;
            const colonne = [
                { chiave: 'cliente', nome: 'Cliente' },
                { chiave: 'tipo', nome: 'Tipo' },
                { chiave: 'dataInizio', nome: 'Inizio' },
                { chiave: 'dataFine', nome: 'Fine' },
                { chiave: 'area', nome: 'Area' },
                { chiave: 'regione', nome: 'Regione' },
                { chiave: 'qualita', nome: 'Qualità' },
                { chiave: 'respIncarico', nome: 'Resp. incarico' },
                { chiave: 'team', nome: 'Team' },
                { chiave: 'compenso', nome: 'Compenso ' + annoRif, num: true },
                { chiave: 'scadenza', nome: 'Stato' }
            ];
            corpo = attivi.length ? (nProposte ? `<div class="avviso-proposta">${ICO_PROPOSTA}<span><strong>${nProposte} ${nProposte === 1 ? 'incarico è' : 'incarichi sono'} in proposta</strong> (righe evidenziate): compensi e scadenze non entrano nel totale finché non ${nProposte === 1 ? 'lo confermi' : 'li confermi'} con il pulsante <strong>Conferma</strong>.</span></div>` : '') + `<div class="tabella-wrap"><table class="dati a-schede compatta"><thead><tr>` +
                colonne.map(c => `<th class="${c.num ? 'num' : ''}" data-ordina="${c.chiave}">${c.nome}${filtriIncarichi.ordina === c.chiave ? (filtriIncarichi.verso > 0 ? ' ▲' : ' ▼') : ''}</th>`).join('') +
                (colAzioni ? '<th></th>' : '') +
                `</tr></thead><tbody>` +
                attivi.map(i => {
                    const s = Incarichi.statoScadenza(i);
                    const prop = inProposta(i);
                    return `<tr class="cliccabile${prop ? ' riga-proposta' : ''}" data-apri="${esc(i.id)}">
                        <td class="cliente-cella" data-label="Cliente">${esc(i.cliente)}</td>
                        <td data-label="Tipo">${badgeTipo(i.tipo)}</td>
                        <td data-label="Inizio">${i.dataInizio ? esc(fmtData(i.dataInizio)) : esc(i.dataInizioNote || '')}</td>
                        <td data-label="Fine">${esc(fmtData(i.rinnovo || i.dataFine))}</td>
                        <td data-label="Area">${esc(i.area || '')}</td>
                        <td data-label="Regione">${esc(i.regione || '')}</td>
                        <td data-label="Qualità">${esc(i.qualita || '')}</td>
                        <td data-label="Resp. incarico">${esc(i.respIncarico || '')}</td>
                        <td data-label="Team">${esc(i.team || '')}</td>
                        <td class="num" data-label="Compenso ${annoRif}">${Incarichi.compensoAnno(i, annoRif) ? eurFmt.format(Incarichi.compensoAnno(i, annoRif)) + (prop ? ' <span class="hint">(proposto)</span>' : '') : ''}</td>
                        <td data-label="Stato"><span class="badge ${s.classe}">${esc(s.testo)}</span></td>
                        ${colAzioni ? `<td data-label="" class="td-azioni td-menu">${menuAzioni((!puoRinnovare ? '' : (prop
                        ? `<button class="btn btn-sm btn-primary" data-conferma="${esc(i.id)}">Conferma</button><button class="btn btn-sm btn-secondary" data-modifica="${esc(i.id)}">Modifica</button><button class="btn btn-sm btn-secondary" data-non-accettato="${esc(i.id)}">Non accettato</button>`
                        : `<button class="btn btn-sm btn-secondary" data-modifica="${esc(i.id)}">Modifica</button><button class="btn btn-sm btn-secondary" data-rinnova="${esc(i.id)}">Rinnova</button><button class="btn btn-sm btn-secondary" data-termina="${esc(i.id)}">Termina</button><button class="btn btn-sm btn-secondary" data-dimetti="${esc(i.id)}">Dimissioni</button>`)) + btnElimina(i))}</td>` : ''}
                    </tr>`;
                }).join('') +
                `</tbody><tfoot><tr><td colspan="9">Totale (${attivi.length} incarichi${nProposte ? ', ' + nProposte + (nProposte === 1 ? ' in proposta escluso' : ' in proposta esclusi') + ' dal totale' : ''})</td><td class="num">${eurFmt.format(totale)}</td><td></td>${colAzioni ? '<td></td>' : ''}</tr></tfoot></table></div>`
                : '<div class="card tabella-vuota">Nessun incarico attivo corrisponde ai filtri.</div>';
        }

        cont.innerHTML = tabBar + corpo;

        // menu azioni a comparsa: si apre col pulsante "tre puntini" accanto alla riga
        cont.querySelectorAll('[data-menu]').forEach(b =>
            b.addEventListener('click', e => {
                e.stopPropagation();
                const menu = b.nextElementSibling;
                const apre = menu && !menu.classList.contains('aperto');
                chiudiMenuAzioni();
                if (apre) {
                    menu.classList.add('aperto');
                    b.setAttribute('aria-expanded', 'true');
                    const r = b.getBoundingClientRect();
                    menu.style.top = Math.max(8, Math.min(r.bottom + 4, window.innerHeight - menu.offsetHeight - 8)) + 'px';
                    menu.style.left = Math.max(8, r.right - menu.offsetWidth) + 'px';
                }
            }));
        cont.querySelectorAll('.menu-azioni').forEach(m => {
            // in cattura: chiude il menu prima che parta l'azione scelta
            m.addEventListener('click', () => chiudiMenuAzioni(), true);
            // il clic dentro il menu non deve aprire il dettaglio della riga
            m.addEventListener('click', e => e.stopPropagation());
        });
        cont.querySelectorAll('[data-non-accettato]').forEach(b =>
            b.addEventListener('click', e => {
                e.stopPropagation();
                const inc = Incarichi.trova(b.dataset.nonAccettato);
                if (inc) modaleNonAccettatoIncarico(inc, () => disegnaTabellaIncarichi(annoRif));
            }));
        cont.querySelectorAll('[data-inctab]').forEach(b =>
            b.addEventListener('click', () => { incarichiTab = b.dataset.inctab; disegnaTabellaIncarichi(annoRif); }));
        cont.querySelectorAll('[data-apri]').forEach(r =>
            r.addEventListener('click', () => naviga('dettaglio', { id: r.dataset.apri })));
        cont.querySelectorAll('[data-modifica]').forEach(b =>
            b.addEventListener('click', e => {
                e.stopPropagation();
                naviga('wizard', { modalita: 'modifica', id: b.dataset.modifica });
            }));
        cont.querySelectorAll('[data-rinnova]').forEach(b =>
            b.addEventListener('click', e => {
                e.stopPropagation();
                naviga('wizard', { modalita: 'rinnovo', id: b.dataset.rinnova });
            }));
        cont.querySelectorAll('[data-termina]').forEach(b =>
            b.addEventListener('click', e => {
                e.stopPropagation();
                const inc = Incarichi.trova(b.dataset.termina);
                if (inc) modaleTerminaIncarico(inc, () => disegnaTabellaIncarichi(annoRif));
            }));
        cont.querySelectorAll('[data-dimetti]').forEach(b =>
            b.addEventListener('click', e => {
                e.stopPropagation();
                const inc = Incarichi.trova(b.dataset.dimetti);
                if (inc) modaleDimissioniIncarico(inc, () => disegnaTabellaIncarichi(annoRif));
            }));
        cont.querySelectorAll('[data-conferma]').forEach(b =>
            b.addEventListener('click', e => {
                e.stopPropagation();
                const inc = Incarichi.trova(b.dataset.conferma);
                if (inc) modaleConfermaIncarico(inc, () => disegnaTabellaIncarichi(annoRif));
            }));
        cont.querySelectorAll('[data-riattiva]').forEach(b =>
            b.addEventListener('click', e => {
                e.stopPropagation();
                const inc = Incarichi.trova(b.dataset.riattiva);
                if (inc) modaleRiattivaIncarico(inc, () => disegnaTabellaIncarichi(annoRif));
            }));
        cont.querySelectorAll('[data-riproponi]').forEach(b =>
            b.addEventListener('click', e => {
                e.stopPropagation();
                Incarichi.riproponi(b.dataset.riproponi, Auth.utenteCorrente);
                toast('Incarico riportato in proposta: lo trovi nel cruscotto tra le proposte in attesa di conferma.', 'verde');
                disegnaTabellaIncarichi(annoRif);
            }));
        cont.querySelectorAll('[data-elimina]').forEach(b =>
            b.addEventListener('click', e => {
                e.stopPropagation();
                const inc = Incarichi.trova(b.dataset.elimina);
                if (inc) modaleEliminaIncarico(inc, () => disegnaTabellaIncarichi(annoRif));
            }));
        cont.querySelectorAll('th[data-ordina]').forEach(th =>
            th.addEventListener('click', () => {
                const c = th.dataset.ordina;
                if (filtriIncarichi.ordina === c) filtriIncarichi.verso *= -1;
                else { filtriIncarichi.ordina = c; filtriIncarichi.verso = 1; }
                disegnaTabellaIncarichi(annoRif);
            }));
    }

    function esportaCsvIncarichi() {
        const anni = Incarichi.anniConCompensi();
        const righe = [['Cliente', 'Tipo', 'Codice fiscale', 'Data inizio', 'Data fine', 'Rinnovo', 'Area', 'Regione', 'Qualità', 'Resp. incarico', 'Referente', 'Team', 'Fatturazione', 'Stato'].concat(anni.map(String))];
        incarichiFiltrati(annoRiferimento()).forEach(i => {
            righe.push([
                i.cliente, nomeTipo(i.tipo), i.codiceFiscale || '', i.dataInizio || i.dataInizioNote || '', i.dataFine || '',
                i.rinnovo || '', i.area || '', i.regione || '', i.qualita || '', i.respIncarico || '',
                i.referente || '', i.team || '', i.fatturazione || '', i.stato || ''
            ].concat(anni.map(a => Incarichi.compensoAnno(i, a) || '')));
        });
        const csv = righe.map(r => r.map(v => {
            let s = String(v).replace(/"/g, '""');
            // evita l'interpretazione come formula in Excel
            if (/^[=+\-@\t\r]/.test(s)) s = "'" + s;
            return '"' + s + '"';
        }).join(';')).join('\r\n');
        const blob = new Blob(['﻿' + csv], { type: 'text/csv;charset=utf-8' });
        const a = document.createElement('a');
        a.href = URL.createObjectURL(blob);
        a.download = 'incarichi_' + oggiISO() + '.csv';
        a.click();
        URL.revokeObjectURL(a.href);
        Audit.registra(Auth.utenteCorrente, 'Esportazione CSV incarichi', 'sistema', null, null, null);
    }

    /* =========================================================
       VISTA: DETTAGLIO INCARICO
    ========================================================= */
    function vistaDettaglio() {
        const inc = Incarichi.trova(parametriVista && parametriVista.id);
        if (!inc) { naviga('incarichi'); return; }
        // filtro regione: non si apre un incarico fuori dalle regioni consentite al ruolo
        if (!Auth.vedeIncarico(inc)) { naviga('incarichi'); return; }
        avvisaSeAltriModificano('incarico', inc.id);
        const s = Incarichi.statoScadenza(inc);
        const anni = Object.keys(inc.compensi || {}).map(Number).sort();
        const storia = Store.leggi(CHIAVI.audit, []).filter(v => v.rif === inc.id);
        // "torna indietro": la sezione da cui si e entrati (es. Aderenti Revilaw), altrimenti Incarichi
        const tornaEt = (origineNav && !SOTTOVISTE.includes(origineNav.vista))
            ? ((VOCI_NAV.find(x => x.id === origineNav.vista) || {}).nome || 'indietro') : 'Incarichi';

        $vista().innerHTML = `
            <header>
                <div>
                    <a id="btn-torna-origine" style="display:inline-block;cursor:pointer;font-size:0.85rem;color:var(--blu-500);margin-bottom:4px;">&#8592; Torna a ${esc(tornaEt)}</a>
                    <h1>${esc(inc.cliente)}</h1>
                    <p class="descrizione">
                        <span class="badge ${classeTipo(inc.tipo)}">${esc(nomeTipo(inc.tipo))}</span>
                        <span class="badge ${s.classe}">${esc(s.testo)}</span>
                        ${inc.calcoloCongelato ? '<span class="badge ambra">' + ICO_LUCCHETTO + 'Calcolo congelato</span>' : ''}
                    </p>
                </div>
                <div class="header-azioni">
                    <button class="btn btn-ghost" id="btn-indietro">&larr; Elenco</button>
                    ${Auth.puoVedere('richieste') ? '<button class="btn btn-secondary" id="btn-chiedi-correzione" title="Chiedi a un equity partner di correggere un dato di questo incarico">Chiedi una correzione</button>' : ''}
                    ${Auth.puoScrivere('incarichi') ? `
                        <button class="btn btn-secondary" id="btn-modifica">Modifica</button>
                        ${inc.stato === 'proposta'
                    ? '<button class="btn btn-secondary" id="btn-non-accettato-inc">Non accettato</button><button class="btn btn-primary" id="btn-conferma-inc">Conferma incarico</button>'
                    : inc.stato === 'nonAccettato'
                        ? '<button class="btn btn-secondary" id="btn-riproponi-inc">Riporta in proposta</button>'
                        : `<button class="btn btn-secondary" id="btn-rinnova">Rinnova</button>
                        ${inc.stato === 'cessato' || inc.stato === 'dimesso' ? '<button class="btn btn-secondary" id="btn-riattiva-inc">Riattiva incarico</button>' : '<button class="btn btn-secondary" id="btn-termina-inc">Termina incarico</button><button class="btn btn-secondary" id="btn-dimetti-inc">Dimissioni</button>'}`}
                        ${inc.calcoloCongelato ? '<button class="btn btn-secondary" id="btn-sblocca">Sblocca calcolo</button>' : ''}
                        ${inc.tipo === 'legale' || inc.tipo === 'volontaria' ? '<button class="btn ' + (inc.stato === 'proposta' ? 'btn-secondary' : 'btn-primary') + '" id="btn-lettera">Lettera di incarico</button>' : ''}
                    ` : ''}
                </div>
            </header>
            ${inc.stato === 'proposta' ? `<div class="card banner-proposta">
                <p class="descrizione" style="margin:0 0 10px;">${ICO_PROPOSTA}<strong>Incarico in stato di proposta.</strong> Il periodo corrente <strong>non entra ancora in fatturazione e nei compensi</strong>: comincia a contare solo quando lo confermi. Puoi stampare la lettera di incarico già ora (resta una proposta finché non confermi).</p>
                ${Auth.puoScrivere('incarichi') ? '<button class="btn btn-sm btn-primary" id="btn-conferma-banner">Conferma incarico</button>' : ''}
            </div>` : ''}
            ${inc.stato === 'nonAccettato' ? `<div class="card" style="border-left:4px solid var(--rosso);">
                <p class="descrizione" style="margin:0 0 10px;"><strong>Proposta non accettata dal cliente</strong>${inc.nonAccettato && inc.nonAccettato.il ? ' (registrata il ' + fmtDataOra(inc.nonAccettato.il) + ')' : ''}${inc.nonAccettato && inc.nonAccettato.nota ? ': "' + esc(inc.nonAccettato.nota) + '"' : ''}. Il periodo proposto <strong>non entra in fatturazione e nei compensi</strong>. Con <strong>Riporta in proposta</strong> puoi rielaborare l'incarico, rigenerare il PDF della lettera e ripetere la fase di conferma.</p>
                ${Auth.puoScrivere('incarichi') ? '<button class="btn btn-sm btn-secondary" id="btn-riproponi-banner">Riporta in proposta</button>' : ''}
            </div>` : ''}
            ${inc.calcoloCongelato ? `<div class="card" style="border-left:4px solid var(--oro);">
                <p class="descrizione" style="margin:0;">${ICO_LUCCHETTO}Il calcolo del compenso è congelato${inc.congelamento && inc.congelamento.il ? ' dal ' + fmtDataOra(inc.congelamento.il) : ''}. Per modificarlo, usa "Sblocca calcolo": verrà inviato un messaggio di allerta al titolare.</p>
            </div>` : ''}
            <div class="dettaglio-griglia">
                <div>
                    <div class="card">
                        <h2>Dati incarico</h2>
                        <div class="riepilogo-blocco">
                            <h4>Cliente</h4>
                            ${rigaRiepilogo('Ragione sociale', inc.cliente)}
                            ${rigaRiepilogo('Codice fiscale', inc.codiceFiscale)}
                            ${rigaRiepilogo('Regione', inc.regione)}
                            ${rigaRiepilogo('Email', [inc.email1, inc.email2].filter(Boolean).join(', '))}
                        </div>
                        <div class="riepilogo-blocco">
                            <h4>Durata</h4>
                            ${rigaRiepilogo('Tipo', TIPI[inc.tipo] || inc.tipo)}
                            ${rigaRiepilogo('Presenza in MEF', inc.presenzaMef)}
                            ${rigaRiepilogo('Data inizio', inc.dataInizio ? fmtData(inc.dataInizio) : inc.dataInizioNote)}
                            ${rigaRiepilogo('Data fine', fmtData(inc.dataFine) || inc.dataFineNote)}
                            ${rigaRiepilogo('Rinnovo', inc.rinnovo ? fmtData(inc.rinnovo) : inc.rinnovoNote)}
                            ${rigaRiepilogo('Stato', (inc.stato === 'cessato' ? 'Terminato' : (inc.stato === 'dimesso' ? 'Dimesso' + (inc.dimissioni && inc.dimissioni.data ? ' il ' + fmtData(inc.dimissioni.data) : '') : (inc.stato === 'proposta' ? 'Proposta (da confermare)' : (inc.stato === 'nonAccettato' ? 'Non accettato' + (inc.nonAccettato && inc.nonAccettato.il ? ' il ' + fmtDataOra(inc.nonAccettato.il) : '') : (inc.stato === 'attivo' ? 'Attivo' + (inc.confermato && inc.confermato.il ? ' - confermato il ' + fmtDataOra(inc.confermato.il) : '') : inc.stato))))) + (inc.statoNote ? ' (' + inc.statoNote + ')' : ''))}
                        </div>
                        <div class="riepilogo-blocco">
                            <h4>Team</h4>
                            ${rigaRiepilogo('Responsabile incarico', inc.respIncarico)}
                            ${rigaRiepilogo('Responsabile qualità', inc.qualita)}
                            ${rigaRiepilogo('Referente', inc.referente)}
                            ${rigaRiepilogo('Team di revisione', inc.team)}
                            ${(inc.teamStorico && inc.teamStorico.length) ? `<div class="riepilogo-riga"><span class="etichetta">Team precedente</span><span class="valore">${inc.teamStorico.map(s => esc(s.nome) + (s.al ? ' <span class="hint">(fino al ' + fmtData(s.al) + ')</span>' : '')).join(', ')}</span></div>` : ''}
                            ${rigaRiepilogo('Area', inc.area)}
                        </div>
                    </div>
                    <div class="card">
                        <h2>Compensi annui e fatturazione</h2>
                        <p class="descrizione" style="margin-bottom:12px;">Fatturazione: <strong>${esc(descriviFatturazione(inc))}</strong>${inc.gruppoFatturazione ? ' &middot; Gruppo: <strong>' + esc(inc.gruppoFatturazione) + '</strong>' : ''} &middot; Spese generali: <strong>${spesePerc(inc) ? percTesto(spesePerc(inc)) + '% sugli onorari' : 'non addebitate'}</strong></p>
                        ${anni.length ? `<div class="tabella-wrap"><table class="dati"><thead><tr><th>Esercizio</th><th class="num">Compenso annuo</th><th class="num">Scadenze</th><th class="num">Importo scadenza</th></tr></thead><tbody>` +
                            anni.map(a => {
                                const rate = Fatture.rate(inc, a);
                                // con un piano concordato le scadenze possono avere importi diversi fra loro
                                const uguali = rate.length && rate.every(r => Math.abs(r.importo - rate[0].importo) < 0.01);
                                return `<tr><td>${a}</td><td class="num">${eurFmt.format(Incarichi.compensoAnno(inc, a))}</td><td class="num">${rate.length}</td><td class="num">${rate.length ? (uguali ? eurFmt2.format(rate[0].importo) : 'variabili') : ''}</td></tr>`;
                            }).join('') + '</tbody></table></div>' : '<p class="tabella-vuota">Nessun compenso registrato.</p>'}
                        ${anni.length ? `<details class="piano-prec" style="margin-top:12px;">
                            <summary><strong>Piano delle scadenze</strong> &middot; ${anni.reduce((s, a) => s + Fatture.rate(inc, a).length, 0)} in totale</summary>
                            <div class="tabella-wrap"><table class="dati"><thead><tr><th>Esercizio</th><th>Periodo</th><th>Scadenza</th><th class="num">Importo</th>${spesePerc(inc) ? '<th class="num">Spese ' + percTesto(spesePerc(inc)) + '%</th>' : ''}<th>Stato</th></tr></thead><tbody>` +
                            anni.map(a => Fatture.rate(inc, a).map((r, i) =>
                                `<tr><td data-label="Esercizio">${i === 0 ? a : ''}</td>
                                    <td data-label="Periodo">${esc(etichettaRigaPiano(r.scadenza, inc.fatturazione || 'annuale', r.numero))}</td>
                                    <td data-label="Scadenza">${esc(fmtData(r.scadenza))}</td>
                                    <td class="num" data-label="Importo">${eurFmt2.format(r.importo)}</td>
                                    ${spesePerc(inc) ? '<td class="num" data-label="Spese">' + eurFmt2.format(speseSu(r.importo, inc)) + '</td>' : ''}
                                    <td data-label="Stato"><span class="badge ${r.stato === 'incassata' ? 'verde' : (r.stato === 'emessa' ? 'ambra' : 'neutro')}">${esc(r.stato)}</span></td></tr>`).join('')).join('') +
                            `</tbody></table></div>
                            <p class="hint" style="margin-top:8px;">Scadenze e importi si modificano dal wizard (Modifica &rarr; passo Fatturazione). I rimborsi delle spese vive si aggiungono dalla sezione Fatturazione.</p>
                        </details>` : ''}
                        ${inc.calc ? `<div class="calc-riquadro">
                            <strong>Ultimo calcolo del compenso</strong>
                            <div class="calc-riga"><span>Media dimensionale</span><span class="val">${eurFmt.format(inc.calc.media || 0)}</span></div>
                            <div class="calc-riga"><span>Ore finali (anno 1)</span><span class="val">${numFmt.format(inc.calc.oreAnno1 || 0)} h</span></div>
                            <div class="calc-riga"><span>Tariffa oraria</span><span class="val">${eurFmt.format(inc.calc.tariffa || 0)}</span></div>
                        </div>` : ''}
                    </div>
                    ${(inc.storico && inc.storico.length) ? `<div class="card" id="periodi-precedenti">
                        <h2>Periodi precedenti (${inc.storico.length})</h2>
                        <p class="descrizione" style="margin-bottom:12px;">Ogni rinnovo archivia qui il periodo concluso, con la sua lettera di incarico ricreabile.</p>
                        <div class="tabella-wrap"><table class="dati"><thead><tr><th>Periodo</th><th>Scadenza</th><th class="num">Compenso 1&deg; esercizio</th><th>Rinnovato il</th>${(inc.tipo === 'legale' || inc.tipo === 'volontaria') ? '<th></th>' : ''}</tr></thead><tbody>` +
                            inc.storico.map((s, i) => {
                                const durataS = s.tipo === 'legale' ? 3 : 1;
                                const primoS = s.esercizioPeriodo ? Number(s.esercizioPeriodo) : null;
                                const periodoS = primoS ? (durataS > 1 ? primoS + '-' + (primoS + durataS - 1) : String(primoS)) : 'n.d.';
                                const compS = primoS ? (Number((s.compensi || {})[primoS]) || 0) : 0;
                                const scadS = s.rinnovo || s.dataFine;
                                const azS = (inc.tipo === 'legale' || inc.tipo === 'volontaria') ? '<td><button class="btn btn-sm btn-secondary p-lettera-storica" data-periodo="' + i + '">Vedi lettera</button></td>' : '';
                                return '<tr><td><strong>' + periodoS + '</strong>' + (s.calcoloCongelato ? ' <span class="badge ambra">' + ICO_LUCCHETTO + 'congelato</span>' : '') + '</td><td>' + (scadS ? fmtData(scadS) : '') + '</td><td class="num">' + eurFmt.format(compS) + '</td><td>' + (s.chiuso ? fmtDataOra(s.chiuso.il) : '') + '</td>' + azS + '</tr>';
                            }).join('') +
                        `</tbody></table></div>
                    </div>` : ''}
                </div>
                <div>
                    <div class="card">
                        <h2>Storia delle modifiche</h2>
                        ${storia.length ? storia.map(v => `<div class="storia-voce">
                            <div class="quando">${fmtDataOra(v.ts)}</div>
                            <div><span class="chi">${esc(v.utente)}</span> - ${esc(v.azione)}</div>
                            ${Array.isArray(v.dettagli) ? '<ul class="campi">' + v.dettagli.map(d => '<li>' + esc(d.campo) + ': ' + esc(troncaTesto(d.prima, 40)) + ' → ' + esc(troncaTesto(d.dopo, 40)) + '</li>').join('') + '</ul>' : (v.dettagli ? '<div class="campi">' + esc(v.dettagli) + '</div>' : '')}
                        </div>`).join('') : '<p class="tabella-vuota">Nessuna modifica registrata.</p>'}
                        ${inc.creato ? `<div class="storia-voce"><div class="quando">${fmtDataOra(inc.creato.il)}</div><div>Creato da <span class="chi">${esc(inc.creato.da)}</span></div></div>` : ''}
                    </div>
                    ${Auth.puoEliminareIncarichi() ? `<div class="card">
                        <h2>Zona amministratore</h2>
                        <p class="descrizione" style="margin-bottom:12px;">L'eliminazione è definitiva e porta via anche compensi e scadenze. Per chiudere l'incarico conservando tutto usa <strong>Termina</strong> o <strong>Dimissioni</strong>.</p>
                        <button class="btn btn-danger btn-sm" id="btn-elimina">Elimina incarico</button>
                    </div>` : ''}
                </div>
            </div>`;

        document.getElementById('btn-indietro').addEventListener('click', () => naviga('incarichi'));
        $vista().querySelectorAll('.p-lettera-storica').forEach(b =>
            b.addEventListener('click', () => naviga('lettera', { id: inc.id, periodo: Number(b.dataset.periodo) })));
        { const bt = document.getElementById('btn-torna-origine'); if (bt) bt.addEventListener('click', () => tornaOrigine()); }
        // il dato sbagliato si incontra qui: la richiesta parte gia' agganciata a questo incarico
        { const bc = document.getElementById('btn-chiedi-correzione'); if (bc) bc.addEventListener('click', () => modaleNuovaRichiesta({ incaricoId: inc.id })); }
        if (Auth.puoScrivere('incarichi')) {
            document.getElementById('btn-modifica').addEventListener('click', () => naviga('wizard', { modalita: 'modifica', id: inc.id }));
            { const bR = document.getElementById('btn-rinnova'); if (bR) bR.addEventListener('click', () => naviga('wizard', { modalita: 'rinnovo', id: inc.id })); }
            const btnLettera = document.getElementById('btn-lettera');
            if (btnLettera) btnLettera.addEventListener('click', () => naviga('lettera', { id: inc.id }));
            const btnSblocca = document.getElementById('btn-sblocca');
            if (btnSblocca) btnSblocca.addEventListener('click', () => modaleSblocco(inc));
            const btnTermina = document.getElementById('btn-termina-inc');
            if (btnTermina) btnTermina.addEventListener('click', () => modaleTerminaIncarico(inc));
            const btnDimetti = document.getElementById('btn-dimetti-inc');
            if (btnDimetti) btnDimetti.addEventListener('click', () => modaleDimissioniIncarico(inc));
            const btnRiattivaInc = document.getElementById('btn-riattiva-inc');
            if (btnRiattivaInc) btnRiattivaInc.addEventListener('click', () => modaleRiattivaIncarico(inc, () => naviga('dettaglio', { id: inc.id })));
            const confermaInc = () => modaleConfermaIncarico(inc, () => naviga('dettaglio', { id: inc.id }));
            const btnConf = document.getElementById('btn-conferma-inc'); if (btnConf) btnConf.addEventListener('click', confermaInc);
            const btnConfB = document.getElementById('btn-conferma-banner'); if (btnConfB) btnConfB.addEventListener('click', confermaInc);
            const btnNA = document.getElementById('btn-non-accettato-inc');
            if (btnNA) btnNA.addEventListener('click', () => modaleNonAccettatoIncarico(inc, () => naviga('dettaglio', { id: inc.id })));
            const riproponiInc = () => {
                Incarichi.riproponi(inc.id, Auth.utenteCorrente);
                toast('Incarico riportato in proposta: ora puoi modificarlo e rigenerare il PDF.', 'verde');
                naviga('dettaglio', { id: inc.id });
            };
            const btnRip = document.getElementById('btn-riproponi-inc'); if (btnRip) btnRip.addEventListener('click', riproponiInc);
            const btnRipB = document.getElementById('btn-riproponi-banner'); if (btnRipB) btnRipB.addEventListener('click', riproponiInc);
        }
        // eliminato l'incarico la scheda aperta non esiste piu: si torna all'elenco
        const btnElimina = document.getElementById('btn-elimina');
        if (btnElimina) btnElimina.addEventListener('click', () => modaleEliminaIncarico(inc));
    }

    // termina l'incarico: conferma e spostamento nella scheda "Terminati".
    // onDone opzionale: eseguito dopo la conferma (dall'elenco ridisegna la tabella; dal dettaglio si ricarica la scheda)
    function modaleRiattivaIncarico(inc, onDone) {
        apriModale(`<h2>Riattivare l'incarico?</h2>
            <p>L'incarico <strong>${esc(inc.cliente)}</strong> tornerà tra gli <strong>attivi</strong>. L'operazione resta nel registro modifiche.</p>
            <div class="modale-azioni"><button class="btn btn-ghost" id="m-annulla">Annulla</button><button class="btn btn-primary" id="m-conferma">Riattiva</button></div>`);
        document.getElementById('m-annulla').addEventListener('click', chiudiModale);
        document.getElementById('m-conferma').addEventListener('click', () => {
            Incarichi.riattiva(inc.id, Auth.utenteCorrente);
            chiudiModale();
            toast('Incarico riattivato: torna tra gli incarichi attivi.', 'verde');
            if (typeof onDone === 'function') onDone();
        });
    }
    /* Conferma di una proposta: prima di renderla attiva si chiede se la fatturazione
       del periodo va bene o va modificata (apre il wizard al passo Fatturazione). */
    function modaleConfermaIncarico(inc, onDone) {
        const anniP = anniPeriodoProposto(inc) || Object.keys(inc.compensi || {}).map(Number).filter(Boolean);
        const rate = anniP.reduce((n, a) => n + Fatture.rate(inc, a).length, 0);
        const compP = anniP.reduce((s, a) => s + Incarichi.compensoAnno(inc, a), 0);
        const periodo = anniP.length ? (anniP.length > 1 ? anniP[0] + '-' + anniP[anniP.length - 1] : String(anniP[0])) : '';
        apriModale(`<h2>Conferma dell'incarico</h2>
            <p>Stai per confermare <strong>${esc(inc.cliente)}</strong>. Da questo momento il periodo <strong>${esc(periodo)}</strong> entra in <strong>fatturazione e compensi</strong>.</p>
            <div class="riepilogo-blocco" style="margin-top:6px;">
                <h4>Fatturazione del periodo</h4>
                ${rigaRiepilogo('Modalità', descriviFatturazione(inc))}
                ${rigaRiepilogo('Spese generali', spesePerc(inc) ? percTesto(spesePerc(inc)) + '% sugli onorari' : 'non addebitate')}
                ${rigaRiepilogo('Compenso del periodo', eurFmt.format(compP) + (rate ? ' in ' + rate + (rate === 1 ? ' scadenza' : ' scadenze') : ''))}
            </div>
            <p class="descrizione">La fatturazione secondo il periodo è corretta, oppure va modificata?</p>
            <div class="modale-azioni" style="flex-wrap:wrap;">
                <button class="btn btn-ghost" id="m-annulla">Annulla</button>
                <button class="btn btn-secondary" id="m-modifica">Modifica la fatturazione</button>
                <button class="btn btn-primary" id="m-conferma">Confermo, la fatturazione va bene</button>
            </div>`, { classe: 'larga' });
        document.getElementById('m-annulla').addEventListener('click', chiudiModale);
        document.getElementById('m-modifica').addEventListener('click', () => {
            chiudiModale();
            toast('Modifica il piano di fatturazione, salva e poi premi di nuovo "Conferma".', 'ambra');
            naviga('wizard', { modalita: 'modifica', id: inc.id, passo: 5 });
        });
        document.getElementById('m-conferma').addEventListener('click', () => {
            Incarichi.conferma(inc.id, Auth.utenteCorrente);
            chiudiModale();
            toast('Incarico confermato: ora entra in fatturazione e nei compensi.', 'verde');
            if (typeof onDone === 'function') onDone(); else naviga('dettaglio', { id: inc.id });
        });
    }
    /* Proposta non accettata dal cliente: esce dalle proposte in attesa e finisce
       nella scheda "Non accettati" della sezione Incarichi (con motivo facoltativo). */
    function modaleNonAccettatoIncarico(inc, onDone) {
        apriModale(`<h2>Incarico non accettato</h2>
            <p>La proposta di <strong>${esc(inc.cliente)}</strong> verrà segnata come <strong>non accettata</strong>: esce dalle proposte in attesa di conferma e finisce nella scheda <strong>Non accettati</strong> della sezione Incarichi. Da lì potrai riportarla in proposta per rielaborarla e rigenerare il PDF. L'operazione resta nel registro modifiche.</p>
            <div class="campo" style="margin-top:8px;"><label>Motivo (facoltativo)</label><input type="text" id="m-na-motivo" placeholder="Es. compenso ritenuto troppo alto"></div>
            <div class="modale-azioni">
                <button class="btn btn-ghost" id="m-annulla">Annulla</button>
                <button class="btn btn-danger" id="m-conferma">Segna come non accettato</button>
            </div>`);
        document.getElementById('m-annulla').addEventListener('click', chiudiModale);
        document.getElementById('m-conferma').addEventListener('click', () => {
            Incarichi.nonAccetta(inc.id, Auth.utenteCorrente, document.getElementById('m-na-motivo').value.trim());
            chiudiModale();
            toast('Incarico segnato come non accettato: lo trovi in Incarichi > Non accettati.', 'verde');
            if (typeof onDone === 'function') onDone();
        });
    }

    function modaleTerminaIncarico(inc, onDone) {
        apriModale(`<h2>Terminare l'incarico?</h2>
            <p>L'incarico <strong>${esc(inc.cliente)}</strong> verrà spostato nella scheda <strong>Terminati</strong> e non comparirà più tra gli attivi. Potrai riattivarlo in qualsiasi momento. L'operazione resta nel registro modifiche.</p>
            <div class="modale-azioni">
                <button class="btn btn-ghost" id="m-annulla">Annulla</button>
                <button class="btn btn-primary" id="m-conferma">Termina incarico</button>
            </div>`);
        document.getElementById('m-annulla').addEventListener('click', chiudiModale);
        document.getElementById('m-conferma').addEventListener('click', () => {
            Incarichi.termina(inc.id, Auth.utenteCorrente);
            chiudiModale();
            toast('Incarico terminato e spostato nella scheda "Terminati".', 'verde');
            if (onDone) onDone(); else naviga('dettaglio', { id: inc.id });
        });
    }

    /* Dimissioni dall'incarico: chiede la DATA delle dimissioni (di default oggi) e sposta
       l'incarico nella scheda "Dismessi". Riattivabile come i terminati. */
    function modaleDimissioniIncarico(inc, onDone) {
        apriModale(`<h2>Dimissioni dall'incarico?</h2>
            <p>L'incarico <strong>${esc(inc.cliente)}</strong> verrà spostato nella scheda <strong>Dismessi</strong> con la data delle dimissioni, e non comparirà più tra gli attivi. Potrai riattivarlo in qualsiasi momento. L'operazione resta nel registro modifiche.</p>
            <div class="campo"><label>Data delle dimissioni</label><input type="date" id="m-dim-data" value="${oggiISO()}"></div>
            <div class="msg-errore hidden" id="m-dim-err"></div>
            <div class="modale-azioni">
                <button class="btn btn-ghost" id="m-annulla">Annulla</button>
                <button class="btn btn-primary" id="m-conferma">Registra le dimissioni</button>
            </div>`);
        document.getElementById('m-annulla').addEventListener('click', chiudiModale);
        document.getElementById('m-conferma').addEventListener('click', () => {
            const data = document.getElementById('m-dim-data').value;
            const err = document.getElementById('m-dim-err');
            if (!data) { err.textContent = 'Indica la data delle dimissioni.'; err.classList.remove('hidden'); return; }
            Incarichi.dimetti(inc.id, data, Auth.utenteCorrente);
            chiudiModale();
            toast('Dimissioni registrate al ' + fmtData(data) + ': incarico nella scheda "Dismessi".', 'verde');
            if (onDone) onDone(); else naviga('dettaglio', { id: inc.id });
        });
    }

    /* Eliminazione definitiva dell'incarico. E' l'unica operazione degli incarichi che NON
       si annulla: la finestra dice cosa sparisce (compensi, scadenze, rimborsi, periodi
       precedenti) e ricorda che "Termina" e "Dimissioni" chiudono l'incarico senza
       perdere niente. onDone opzionale: dall'elenco ridisegna la tabella, dal dettaglio
       si torna all'elenco (la scheda aperta non esiste piu). */
    function modaleEliminaIncarico(inc, onDone) {
        if (!Auth.puoEliminareIncarichi()) return;
        const anni = Object.keys(inc.compensi || {}).map(Number).filter(Boolean).sort();
        const nRate = anni.reduce((s, a) => s + Fatture.rate(inc, a).length, 0);
        const totale = anni.reduce((s, a) => s + Incarichi.compensoAnno(inc, a), 0);
        const nStorico = (inc.storico && inc.storico.length) || 0;
        apriModale(`<h2>Eliminare l'incarico?</h2>
            <p>Stai per eliminare <strong>${esc(inc.cliente)}</strong>. <strong>L'operazione non si annulla.</strong></p>
            ${anni.length ? `<div class="riepilogo-blocco" style="margin-top:6px;">
                ${rigaRiepilogo('Esercizi', anni.length > 1 ? anni[0] + '-' + anni[anni.length - 1] : String(anni[0]))}
                ${rigaRiepilogo('Compensi registrati', eurFmt.format(totale))}
                ${rigaRiepilogo('Scadenze in fatturazione', String(nRate))}
                ${nStorico ? rigaRiepilogo('Periodi precedenti', String(nStorico)) : ''}
            </div>` : ''}
            <p class="hint">Spariscono con l'incarico i compensi, il piano delle scadenze con i loro stati e i rimborsi spese${nStorico ? ', insieme ai periodi precedenti e alle loro lettere' : ''}. Nel registro modifiche resta traccia dell'eliminazione.</p>
            <p class="hint" style="margin-top:10px;">Per chiudere l'incarico <strong>senza perdere nulla</strong> usa invece <strong>Termina</strong> o <strong>Dimissioni</strong>: finisce nella scheda dedicata e lo riattivi quando vuoi.</p>
            <div class="modale-azioni">
                <button class="btn btn-ghost" id="m-annulla">Annulla</button>
                <button class="btn btn-danger" id="m-conferma">Elimina definitivamente</button>
            </div>`);
        document.getElementById('m-annulla').addEventListener('click', chiudiModale);
        document.getElementById('m-conferma').addEventListener('click', () => {
            Incarichi.elimina(inc.id, Auth.utenteCorrente);
            chiudiModale();
            toast('Incarico eliminato.', 'verde');
            if (onDone) onDone(); else naviga('incarichi');
        });
    }

    // sblocco del calcolo: obbliga a comporre un messaggio di allerta
    function modaleSblocco(inc) {
        apriModale(`<h2>Sbloccare il calcolo?</h2>
            <p class="descrizione" style="margin-bottom:12px;">Il calcolo di <strong>${esc(inc.cliente)}</strong> è congelato. Per sbloccarlo devi inviare un messaggio di allerta al titolare dello studio, spiegando il motivo. Lo sblocco e la motivazione restano nel registro.</p>
            <div class="campo"><label>Motivo dello sblocco (messaggio di allerta) *</label><textarea id="m-sblocco-msg" placeholder="Es. rinegoziazione del compenso concordata con il cliente il ..."></textarea></div>
            <div class="msg-errore hidden" id="m-sblocco-err"></div>
            <div class="modale-azioni">
                <button class="btn btn-ghost" id="m-annulla">Annulla</button>
                <button class="btn btn-danger" id="m-conferma">Invia allerta e sblocca</button>
            </div>`);
        document.getElementById('m-annulla').addEventListener('click', chiudiModale);
        document.getElementById('m-conferma').addEventListener('click', () => {
            const msg = document.getElementById('m-sblocco-msg').value.trim();
            const err = document.getElementById('m-sblocco-err');
            if (msg.length < 5) { err.textContent = 'Scrivi il motivo dello sblocco (almeno 5 caratteri).'; err.classList.remove('hidden'); return; }
            Incarichi.scongela(inc.id, Auth.utenteCorrente, msg);
            chiudiModale();
            toast('Calcolo sbloccato. Allerta inviata al titolare.', 'verde');
            naviga('dettaglio', { id: inc.id });
        });
    }

    function rigaRiepilogo(etichetta, valore) {
        if (valore == null || valore === '') return '';
        return `<div class="riepilogo-riga"><span class="etichetta">${esc(etichetta)}</span><span class="valore">${esc(valore)}</span></div>`;
    }
    function troncaTesto(t, n) {
        t = String(t);
        return t.length > n ? t.slice(0, n - 1) + '…' : t;
    }

    /* =========================================================
       VISTA: WIZARD nuovo / modifica / rinnovo
    ========================================================= */
    let wizard = null;

    function vistaWizard() {
        const modalita = (parametriVista && parametriVista.modalita) || 'nuovo';
        const esistente = parametriVista && parametriVista.id ? Incarichi.trova(parametriVista.id) : null;
        if ((modalita === 'modifica' || modalita === 'rinnovo') && !esistente) { naviga('incarichi'); return; }
        // segnala agli altri connessi che sto modificando questo incarico (naviga lo pubblica in coda)
        if (esistente && (modalita === 'modifica' || modalita === 'rinnovo')) {
            statoModifica = { tipo: 'incarico', id: esistente.id, etichetta: esistente.cliente || '' };
            avvisaSeAltriModificano('incarico', esistente.id);
        }

        const annoBase = annoCorrente();
        wizard = {
            modalita, idEsistente: esistente ? esistente.id : null, passo: 1,
            dati: esistente ? JSON.parse(JSON.stringify(esistente)) : {
                cliente: '', tipo: 'legale', codiceFiscale: '', area: 'Nord', regione: 'Lombardia',
                email1: '', email2: '', qualita: '', respIncarico: '', referente: '', team: '',
                fatturazione: fatturazionePredefinita('legale'), gruppoFatturazione: '', fattInizio: null, fattFine: null, fattData: null, compensi: {}, stato: 'attivo',
                speseGenerali: true, speseGeneraliPerc: SPESE_PERC_DEFAULT, piano: {}
            },
            // piano di fatturazione in lavorazione (solo gli esercizi del periodo corrente):
            // si genera entrando nel passo 5 e si segna "toccato" appena lo si modifica a mano
            piano: null, pianoToccato: false, firmaPiano: '',
            // su un incarico esistente la fatturazione salvata e una scelta
            // deliberata: il cambio di tipo non deve sovrascriverla
            fatturazioneToccata: modalita !== 'nuovo',
            esercizio: annoBase,
            calc: (esistente && esistente.calc) ? { ...esistente.calc } : {
                attivo: 0, ricavi: 0, moltSettore: 1.0, moltRischio: 1.2, rischioNote: '',
                orePlus: 0, extra50: 0, hConsolidato: 0, hIfrs: 0, hIt: 0, hAltro: 0, altroNote: '',
                hVolontaria: 0, hPrimoAnno: 0, tariffa: 85
            },
            compensoManuale: false,
            compensoManualeValore: 0,
            // finche' l'utente non tocca il passo 3, in modifica i compensi
            // per anno esistenti vengono conservati cosi' come sono
            compensoModificato: modalita !== 'modifica'
        };
        const anniEsistenti = esistente ? Object.keys(esistente.compensi || {}).map(Number).sort((a, b) => a - b) : [];
        if (modalita === 'rinnovo') {
            // il rinnovo parte dall'esercizio successivo all'ultimo coperto;
            // la data di nomina proposta e' la vecchia scadenza (assemblea di rinnovo)
            wizard.esercizio = anniEsistenti.length ? anniEsistenti[anniEsistenti.length - 1] + 1 : annoBase;
            wizard.dati.compensi = { ...esistente.compensi };
            wizard.dati.dataInizio = esistente.rinnovo || esistente.dataFine || null;
            wizard.dati.dataFine = null;
            // il nuovo periodo e un accordo nuovo: il calcolo riparte sbloccato
            wizard.dati.calcoloCongelato = false;
            wizard.dati.congelamento = null;
        } else if (modalita === 'modifica') {
            // una proposta in attesa di approvazione del cliente resta sempre
            // modificabile: un eventuale congelamento (da una stampa precedente
            // alla regola attuale) decade aprendo la modifica
            if (wizard.dati.stato === 'proposta' && wizard.dati.calcoloCongelato) {
                wizard.dati.calcoloCongelato = false;
                wizard.dati.congelamento = null;
            }
            // esercizio di riferimento: il periodo piu' recente coperto dai compensi
            if (anniEsistenti.length) {
                const ultimo = anniEsistenti[anniEsistenti.length - 1];
                wizard.esercizio = esistente.tipo === 'legale' ? Math.max(ultimo - 2, anniEsistenti[0]) : ultimo;
            } else if (esistente.dataInizio) {
                wizard.esercizio = Number(esistente.dataInizio.slice(0, 4)) || annoBase;
            }
            // se il calcolo non e' ricostruibile ma esiste un compenso, viene
            // proposto come valore manuale (cosi' il passo 3 non blocca)
            const proposto = Math.round(calcolaCompenso(wizard.calc).compensoAnno1);
            const compEsistente = anniEsistenti.length ? Number(esistente.compensi[anniEsistenti[anniEsistenti.length - 1]]) : 0;
            if (proposto <= 0 && compEsistente > 0) {
                wizard.compensoManuale = true;
                wizard.compensoManualeValore = compEsistente;
            }
        }
        // apertura diretta a un passo (es. "Modifica la fatturazione" dalla conferma)
        const pIn = Number(parametriVista && parametriVista.passo);
        if (pIn >= 1 && pIn <= 6) wizard.passo = pIn;
        disegnaWizard();
    }

    const PASSI_WIZARD = ['Cliente', 'Incarico e durata', 'Compenso', 'Team', 'Fatturazione', 'Riepilogo'];

    function disegnaWizard() {
        const w = wizard;
        const titoli = { nuovo: 'Nuovo incarico', modifica: 'Modifica incarico', rinnovo: 'Rinnovo incarico' };
        $vista().innerHTML = `
            <header>
                <div>
                    <h1>${titoli[w.modalita]}${w.modalita !== 'nuovo' ? ': ' + esc(w.dati.cliente) : ''}</h1>
                    <p class="descrizione">${w.modalita === 'rinnovo' ? 'La revisione legale si rinnova per un nuovo triennio con compenso annuale. La revisione volontaria si rinnova di anno in anno.' : 'Compila i passaggi. Il compenso viene proposto con il metodo della pagina sulla revisione legale (ore CNDCEC per tariffa oraria).'}</p>
                </div>
                <div class="header-azioni"><button class="btn btn-ghost" id="btn-annulla-wizard">Annulla</button></div>
            </header>
            <div class="wizard-passi">
                ${PASSI_WIZARD.map((p, i) => `<button type="button" class="wizard-passo ${w.passo === i + 1 ? 'attivo' : (w.passo > i + 1 ? 'fatto' : '')}" data-passo="${i + 1}"><span class="n">${i + 1}</span>${p}</button>`).join('')}
            </div>
            <div class="wizard-nav">
                <button class="btn btn-secondary" id="btn-passo-prec" ${w.passo === 1 ? 'disabled' : ''}>&larr; Indietro</button>
                <button class="btn btn-primary" id="btn-passo-succ">${w.passo === 6 ? 'Salva incarico' : 'Avanti →'}</button>
            </div>
            <div class="card" id="wizard-corpo"></div>`;

        document.getElementById('btn-annulla-wizard').addEventListener('click', () =>
            tornaOrigine(() => w.idEsistente ? naviga('dettaglio', { id: w.idEsistente }) : naviga('incarichi')));
        document.getElementById('btn-passo-prec').addEventListener('click', () => { salvaPassoCorrente(); w.passo--; disegnaWizard(); });
        document.getElementById('btn-passo-succ').addEventListener('click', () => {
            if (!salvaPassoCorrente(true)) return;
            if (w.passo === 6) { concludiWizard(); return; }
            w.passo++;
            disegnaWizard();
        });
        // i passi in cima sono cliccabili: si salta a quello scelto conservando quanto
        // gia inserito (senza bloccare); la validazione completa scatta al salvataggio finale
        $vista().querySelectorAll('.wizard-passo[data-passo]').forEach(el =>
            el.addEventListener('click', () => {
                const target = Number(el.dataset.passo);
                if (target === w.passo) return;
                salvaPassoCorrente(false);
                w.passo = target;
                disegnaWizard();
            }));
        disegnaPassoWizard();
    }

    function disegnaPassoWizard() {
        const w = wizard, d = w.dati, corpo = document.getElementById('wizard-corpo');
        if (w.passo === 1) {
            corpo.innerHTML = `
                <h2>Dati del cliente</h2>
                <div class="griglia-2">
                    <div class="campo"><label>Ragione sociale *</label><input id="w-cliente" value="${esc(d.cliente)}"></div>
                    <div class="campo"><label>Codice fiscale / P. IVA</label><input id="w-cf" value="${esc(d.codiceFiscale || '')}"></div>
                    <div class="campo"><label>Regione</label><select id="w-regione">${(() => {
                        // un ruolo con filtro regione (coordinatore/vice) sceglie solo tra le SUE regioni
                        const cons = Auth.regioniConsentite();
                        if (cons) return RV_ROSTER.regioni.filter(r => cons.includes(chiaveRegione(r))).map(r => `<option ${chiaveRegione(d.regione) === chiaveRegione(r) ? 'selected' : ''}>${r}</option>`).join('');
                        const extra = d.regione && !RV_ROSTER.regioni.includes(d.regione) ? `<option selected>${esc(d.regione)}</option>` : '';
                        return extra + RV_ROSTER.regioni.map(r => `<option ${d.regione === r ? 'selected' : ''}>${r}</option>`).join('');
                    })()}</select></div>
                    <div class="campo"><label>Email di riferimento</label><input id="w-email1" type="email" value="${esc(d.email1 || '')}"></div>
                    <div class="campo"><label>Seconda email</label><input id="w-email2" type="email" value="${esc(d.email2 || '')}"></div>
                    <div class="campo"><label>Area</label><select id="w-area">${d.area && !RV_ROSTER.aree.includes(d.area) ? `<option selected>${esc(d.area)}</option>` : ''}${RV_ROSTER.aree.map(a => `<option ${d.area === a ? 'selected' : ''}>${a}</option>`).join('')}</select></div>
                </div>`;
        } else if (w.passo === 2) {
            const bloccaTipo = w.modalita === 'rinnovo';
            // se il calcolo e congelato, tipo ed esercizio non si spostano
            // (cambierebbero gli anni coperti dai compensi bloccati)
            const bloccaPeriodo = w.modalita === 'modifica' && d.calcoloCongelato;
            corpo.innerHTML = `
                <h2>Tipo di incarico e durata</h2>
                <div class="griglia-2">
                    <div class="campo"><label>Tipo *</label>
                        <select id="w-tipo" ${bloccaTipo || bloccaPeriodo ? 'disabled' : ''}>
                            ${Object.keys(TIPI).map(t => `<option value="${t}" ${d.tipo === t ? 'selected' : ''}>${TIPI[t]}</option>`).join('')}
                        </select>
                        <div class="hint">${bloccaPeriodo ? 'Calcolo congelato: per cambiare tipo o periodo sblocca prima il calcolo dal dettaglio.' : 'La revisione legale dura tre esercizi con compenso annuale. La revisione volontaria dura un esercizio.'}</div>
                    </div>
                    <div class="campo"><label>${w.modalita === 'rinnovo' ? 'Primo esercizio del nuovo periodo' : 'Primo esercizio'} *</label>
                        <input id="w-esercizio" type="number" min="2000" max="2100" value="${w.esercizio}" ${bloccaPeriodo ? 'disabled' : ''}>
                        <div class="hint" id="w-esercizi-hint"></div>
                    </div>
                    <div class="campo"><label>Data inizio (nomina)</label><input id="w-inizio" type="date" value="${esc(d.dataInizio || '')}"></div>
                    <div class="campo"><label>Data fine (approvazione ultimo bilancio)</label><input id="w-fine" type="date" value="${esc(d.dataFine || '')}"></div>
                </div>`;
            const aggiornaHint = () => {
                const tipo = document.getElementById('w-tipo').value;
                const e = Number(document.getElementById('w-esercizio').value) || annoCorrente();
                const hint = document.getElementById('w-esercizi-hint');
                if (tipo === 'legale') hint.textContent = 'Esercizi coperti: ' + e + ', ' + (e + 1) + ', ' + (e + 2) + '. Scadenza suggerita: 30/04/' + (e + 3) + '.';
                else if (tipo === 'volontaria') hint.textContent = 'Esercizio coperto: ' + e + '. Scadenza suggerita: 30/04/' + (e + 1) + '.';
                else hint.textContent = '';
                const fine = document.getElementById('w-fine');
                if (!fine.value || fine.dataset.auto === '1') {
                    fine.value = tipo === 'legale' ? (e + 3) + '-04-30' : (tipo === 'volontaria' ? (e + 1) + '-04-30' : fine.value);
                    fine.dataset.auto = '1';
                }
            };
            document.getElementById('w-tipo').addEventListener('change', () => {
                aggiornaHint();
                // se l'utente non ha scelto a mano la fatturazione, applica lo standard del tipo
                if (!w.fatturazioneToccata) d.fatturazione = fatturazionePredefinita(document.getElementById('w-tipo').value);
            });
            document.getElementById('w-esercizio').addEventListener('input', aggiornaHint);
            document.getElementById('w-fine').addEventListener('input', e => { e.target.dataset.auto = '0'; });
            if (w.modalita === 'rinnovo' || w.modalita === 'nuovo') aggiornaHint();
        } else if (w.passo === 3) {
            disegnaPassoCalcolo(corpo);
        } else if (w.passo === 4) {
            const risolviTeam = risolutorePersone();
            const tutteP = Persone.tutte();
            // etichetta CORRENTE di un valore salvato: aggiorna es. "Cambrea Dario" -> "Cambrea"
            // dopo che il nome e stato separato dal cognome. Disattivati/eliminati/orfani restano.
            const etichCorrente = valore => { const p = risolviTeam(valore); return (p && p.attivo && !p.eliminato) ? etichettaPersona(p, tutteP) : valore; };
            const opzioni = (lista, corrente) => {
                const cur = etichCorrente(corrente);
                const extra = cur && !lista.includes(cur) ? `<option selected>${esc(cur)}</option>` : '';
                return extra + lista.map(r => `<option ${cur === r ? 'selected' : ''}>${esc(r)}</option>`).join('');
            };
            // team salvato: distinguo chi e ancora attivo (selezionabile, con l'etichetta corrente)
            // da chi e "precedente" (disattivato, eliminato o non piu in anagrafica): questi restano
            // congelati e spuntati, ma non si possono aggiungere di nuovo.
            const idNelTeam = new Set(), precedenti = [], vistiPrec = new Set();
            dividiNomi(d.team).forEach(voce => {
                const p = risolviTeam(voce);
                if (p && p.attivo && !p.eliminato) { idNelTeam.add(p.id); return; }
                // dedup delle precedenti per persona (o etichetta, se orfana): due token della
                // stessa persona (es. importati) non devono comparire due volte
                const k = p ? p.id : '_' + String(voce).trim().toLowerCase();
                if (vistiPrec.has(k)) return;
                vistiPrec.add(k);
                precedenti.push({ valore: voce, etichetta: p ? etichettaPersona(p, tutteP) : voce, motivo: p ? (p.eliminato ? 'eliminata' : 'disattivata') : 'non più in anagrafica' });
            });
            const selezionabili = tutteP.filter(p => p.attivo && !p.eliminato)
                .map(p => ({ etichetta: etichettaPersona(p, tutteP), sel: idNelTeam.has(p.id) }))
                .sort((a, b) => a.etichetta.localeCompare(b.etichetta, 'it'));
            const nTeam = selezionabili.length + precedenti.length;
            corpo.innerHTML = `
                <h2>Team di revisione</h2>
                <p class="descrizione" style="margin-bottom:12px;">Assegna i ruoli e scegli i componenti del team. I nominativi si gestiscono dalla vista Aderenti Revilaw.</p>
                <div class="griglia-2">
                    <div class="campo"><label>Responsabile incarico *</label>
                        <select id="w-resp"><option value="">Seleziona</option>${opzioni(Persone.attiveEtichette('respIncarico'), d.respIncarico)}</select>
                    </div>
                    <div class="campo"><label>Responsabile qualità *</label>
                        <select id="w-qualita"><option value="">Seleziona</option>${opzioni(Persone.attiveEtichette('qualita'), d.qualita)}</select>
                        <div class="msg-errore hidden" id="w-qualita-errore"></div>
                    </div>
                    <div class="campo"><label>Referente</label>
                        <select id="w-referente"><option value="">Seleziona</option>${opzioni(Persone.attiveEtichette(), d.referente)}</select>
                    </div>
                </div>
                <div class="campo"><label>Team di revisione (componenti)</label>
                    <div class="team-picker">
                        <div class="team-picker-barra">
                            <input id="w-team-cerca" type="search" placeholder="Cerca un nominativo...">
                            <button type="button" class="btn btn-sm btn-ghost" data-team-sel="1">Seleziona tutti</button>
                            <button type="button" class="btn btn-sm btn-ghost" data-team-sel="0">Deseleziona</button>
                            <span class="hint" id="w-team-conteggio"></span>
                        </div>
                        <div class="team-picker-chips" id="w-team-chips"></div>
                        <div class="team-picker-lista" id="w-team-lista">
                            ${nTeam ? (
                                precedenti.map(pr => `<label class="team-opz" data-nome="${esc(pr.etichetta)}" style="background:var(--ambra-bg);border-radius:6px;"><input type="checkbox" class="w-team-check" value="${esc(pr.valore)}" data-etich="${esc(pr.etichetta)}" checked><span>${esc(pr.etichetta)} <span class="badge ambra">precedente: ${esc(pr.motivo)}</span></span></label>`).join('')
                                + selezionabili.map(s => `<label class="team-opz" data-nome="${esc(s.etichetta)}"><input type="checkbox" class="w-team-check" value="${esc(s.etichetta)}" ${s.sel ? 'checked' : ''}><span>${esc(s.etichetta)}</span></label>`).join('')
                            ) : '<div class="hint" style="padding:6px;">Nessun nominativo in anagrafica: aggiungili dalla vista Aderenti Revilaw.</div>'}
                        </div>
                    </div>
                </div>`;
            const teamLista = document.getElementById('w-team-lista');
            const teamChips = document.getElementById('w-team-chips');
            const teamConta = document.getElementById('w-team-conteggio');
            const aggiornaTeam = () => {
                const sel = Array.from(teamLista.querySelectorAll('.w-team-check:checked')).map(c => ({ v: c.value, e: c.dataset.etich || c.value }));
                teamConta.textContent = sel.length + ' selezionat' + (sel.length === 1 ? 'o' : 'i') + ' su ' + nTeam;
                teamChips.innerHTML = sel.length
                    ? sel.map(o => `<span class="team-chip">${esc(o.e)}<button type="button" class="team-chip-x" title="Rimuovi" data-nome="${esc(o.v)}">&times;</button></span>`).join('')
                    : '<span class="hint">Nessun componente selezionato.</span>';
                teamChips.querySelectorAll('.team-chip-x').forEach(b => b.addEventListener('click', () => {
                    teamLista.querySelectorAll('.w-team-check').forEach(cb => { if (cb.value === b.dataset.nome) cb.checked = false; });
                    aggiornaTeam();
                }));
            };
            teamLista.querySelectorAll('.w-team-check').forEach(c => c.addEventListener('change', aggiornaTeam));
            const teamCerca = document.getElementById('w-team-cerca');
            teamCerca.addEventListener('input', () => {
                const q = teamCerca.value.trim().toLowerCase();
                teamLista.querySelectorAll('.team-opz').forEach(row => { row.style.display = (!q || (row.dataset.nome || '').toLowerCase().includes(q)) ? '' : 'none'; });
            });
            corpo.querySelectorAll('[data-team-sel]').forEach(b => b.addEventListener('click', () => {
                const on = b.dataset.teamSel === '1';
                teamLista.querySelectorAll('.team-opz').forEach(row => { if (row.style.display !== 'none') { const cb = row.querySelector('.w-team-check'); if (cb) cb.checked = on; } });
                aggiornaTeam();
            }));
            aggiornaTeam();
        } else if (w.passo === 5) {
            const pInizio = d.fattInizio ? (d.fattInizio.anno + '-' + String(d.fattInizio.mese).padStart(2, '0')) : '';
            const pFine = d.fattFine ? (d.fattFine.anno + '-' + String(d.fattFine.mese).padStart(2, '0')) : '';
            const gruppiFatt = Array.from(new Set(Incarichi.tutti().map(i => i.gruppoFatturazione).filter(Boolean))).sort();
            corpo.innerHTML = `
                <h2>Fatturazione</h2>
                <div class="campo"><label>Modalità di fatturazione *</label>
                    <select id="w-fatturazione">
                        <option value="annuale" ${d.fatturazione === 'annuale' ? 'selected' : ''}>Annuale (una rata l'anno)</option>
                        <option value="trimestrale" ${d.fatturazione === 'trimestrale' ? 'selected' : ''}>Trimestrale (quattro rate l'anno)</option>
                        <option value="mensile" ${d.fatturazione === 'mensile' ? 'selected' : ''}>Mensile (dodici rate l'anno)</option>
                        <option value="specifica" ${d.fatturazione === 'specifica' ? 'selected' : ''}>Ad una data specifica</option>
                    </select>
                    <div class="hint">Predefinita per ${esc(nomeTipo(d.tipo))}: ${esc(fatturazionePredefinita(d.tipo))}.</div>
                </div>
                <div class="campo"><label>Gruppo di fatturazione</label>
                    <input id="w-gruppo-fatt" list="w-gruppi-fatt" value="${esc(d.gruppoFatturazione || '')}" placeholder="es. BC&amp; (facoltativo)" maxlength="40">
                    <datalist id="w-gruppi-fatt">${gruppiFatt.map(g => '<option value="' + esc(g) + '">').join('')}</datalist>
                    <div class="hint">Raggruppa più incarichi in un'unica fatturazione. Lascia vuoto se l'incarico si fattura da solo.</div>
                </div>
                <div class="griglia-2" id="w-finestra">
                    <div class="campo"><label>Inizio fatturazione</label><input type="month" id="w-fatt-inizio" value="${pInizio}"><div class="hint">Da quale periodo parte. Vuoto = da subito.</div><div class="hint" id="w-fatt-inizio-eco" style="color:var(--blu-700);font-weight:600;margin-top:2px;"></div></div>
                    <div class="campo"><label>Fine fatturazione</label><input type="month" id="w-fatt-fine" value="${pFine}"><div class="hint">Quando termina. Vuoto = senza fine.</div><div class="hint" id="w-fatt-fine-eco" style="color:var(--blu-700);font-weight:600;margin-top:2px;"></div></div>
                </div>
                <div class="campo" id="w-data-specifica"><label>Data della fattura</label><input type="date" id="w-fatt-data" value="${d.fattData || ''}"><div class="hint">La scadenza cade in questa data, nell'esercizio corrispondente.</div></div>
                <div class="campo">
                    <label style="display:flex; align-items:center; gap:8px; font-weight:600;">
                        <input type="checkbox" id="w-spese" ${d.speseGenerali === false ? '' : 'checked'} style="width:auto;"> Aggiungi le spese generali forfettarie
                    </label>
                    <div class="campo" id="w-spese-box" style="max-width:220px; margin:8px 0 0;">
                        <label>Percentuale sugli onorari</label>
                        <input type="text" inputmode="decimal" id="w-spese-perc" value="${percTesto(isFinite(Number(d.speseGeneraliPerc)) && d.speseGeneraliPerc != null ? Number(d.speseGeneraliPerc) : SPESE_PERC_DEFAULT)}" placeholder="5">
                    </div>
                    <div class="hint">Tecnologia, banche dati, software, segreteria e comunicazione: standard 5% degli onorari. La percentuale scelta vale sulle scadenze e nella clausola della lettera di incarico.</div>
                </div>
                <div id="w-piano"></div>
                <p class="hint" style="margin-top:12px;">I <strong>rimborsi delle spese vive</strong> (viaggi, vitto, alloggio) non si indicano qui: si aggiungono scadenza per scadenza nella sezione <strong>Fatturazione</strong>, dove il campo si può anche congelare.</p>`;
            const sincronizzaCampi = () => {
                const per = document.getElementById('w-fatturazione').value;
                document.getElementById('w-finestra').style.display = per === 'specifica' ? 'none' : '';
                document.getElementById('w-data-specifica').style.display = per === 'specifica' ? '' : 'none';
                document.getElementById('w-spese-box').style.display = document.getElementById('w-spese').checked ? '' : 'none';
            };
            // ogni ritocco alle condizioni rifa il piano: le righe nascono da periodicita,
            // finestra e compenso, quindi non possono restare quelle di prima
            const rifaiPiano = () => {
                leggiCampiFatturazione();
                const avvisa = w.pianoToccato;
                w.piano = null;
                preparaPianoWizard();
                if (avvisa) toast('Piano rifatto sulle nuove condizioni: gli importi corretti a mano sono stati sostituiti.', 'ambra');
                ecoFinestra();
                disegnaPianoWizard();
            };
            document.getElementById('w-fatturazione').addEventListener('change', () => { w.fatturazioneToccata = true; sincronizzaCampi(); rifaiPiano(); });
            ['w-fatt-inizio', 'w-fatt-fine', 'w-fatt-data'].forEach(idw => { const el = document.getElementById(idw); if (el) el.addEventListener('change', rifaiPiano); });
            document.getElementById('w-spese').addEventListener('change', () => { sincronizzaCampi(); leggiCampiFatturazione(); disegnaPianoWizard(); });
            document.getElementById('w-spese-perc').addEventListener('input', () => { leggiCampiFatturazione(); disegnaPianoWizard(); });
            sincronizzaCampi();
            preparaPianoWizard();
            ecoFinestra();
            disegnaPianoWizard();
        } else if (w.passo === 6) {
            const anni = anniEsercizi();
            const mappa = compensiRisultanti();
            corpo.innerHTML = `
                <h2>Riepilogo</h2>
                <div class="riepilogo-blocco"><h4>Cliente</h4>
                    ${rigaRiepilogo('Ragione sociale', d.cliente)}
                    ${rigaRiepilogo('Codice fiscale', d.codiceFiscale)}
                    ${rigaRiepilogo('Regione', d.regione)}
                </div>
                <div class="riepilogo-blocco"><h4>Incarico</h4>
                    ${rigaRiepilogo('Tipo', TIPI[d.tipo])}
                    ${rigaRiepilogo('Esercizi', anni.join(', '))}
                    ${rigaRiepilogo('Periodo', (d.dataInizio ? fmtData(d.dataInizio) : '') + ' - ' + (d.dataFine ? fmtData(d.dataFine) : ''))}
                </div>
                <div class="riepilogo-blocco"><h4>Team</h4>
                    ${rigaRiepilogo('Responsabile incarico', d.respIncarico)}
                    ${rigaRiepilogo('Responsabile qualità', d.qualita)}
                    ${rigaRiepilogo('Referente', d.referente)}
                    ${rigaRiepilogo('Team', d.team)}
                    ${(d.teamStorico && d.teamStorico.length) ? `<div class="riepilogo-riga"><span class="etichetta">Team precedente</span><span class="valore">${d.teamStorico.map(s => esc(s.nome) + (s.al ? ' <span class="hint">(fino al ' + fmtData(s.al) + ')</span>' : '')).join(', ')}</span></div>` : ''}
                </div>
                <div class="riepilogo-blocco"><h4>Compenso e fatturazione</h4>
                    ${anni.map(a => {
                const righe = (w.piano || {})[a];
                const tot = Array.isArray(righe) ? totalePiano(righe) : (mappa[a] || 0);
                const n = Array.isArray(righe) ? righe.length : null;
                return rigaRiepilogo('Esercizio ' + a, eurFmt.format(tot) + (n != null ? ' in ' + n + (n === 1 ? ' scadenza' : ' scadenze') : ''));
            }).join('')}
                    ${rigaRiepilogo('Fatturazione', descriviFatturazione(d))}
                    ${rigaRiepilogo('Spese generali', spesePerc(d) ? percTesto(spesePerc(d)) + '% sugli onorari' : 'non addebitate')}
                    ${w.modalita === 'modifica' && !w.compensoModificato ? '<p class="hint" style="font-size:0.78rem; color:var(--grigio-600); margin-top:6px;">Il passo 3 non è stato modificato: i compensi esistenti restano invariati.</p>' : ''}
                </div>
                <p class="descrizione">Salvando, la modifica viene registrata nel registro con il tuo nome (${esc(Auth.utenteCorrente.nome)}).</p>`;
        }
    }

    /* ---------------------------------------------------------------
       Passo 5: piano di fatturazione modificabile riga per riga
    --------------------------------------------------------------- */

    /* Riporta i campi del passo Fatturazione dentro w.dati. Il piano non si legge da
       qui: vive in w.piano e ha i suoi eventi (cosi non si perde quel che si sta
       scrivendo in un importo mentre si aggiorna il resto). */
    function leggiCampiFatturazione() {
        const d = wizard.dati;
        const sel = document.getElementById('w-fatturazione');
        if (!sel) return;
        d.fatturazione = sel.value;
        d.gruppoFatturazione = document.getElementById('w-gruppo-fatt').value.trim();
        if (d.fatturazione === 'specifica') {
            d.fattData = document.getElementById('w-fatt-data').value || null;
            d.fattInizio = null; d.fattFine = null;
        } else {
            d.fattData = null;
            const pi = document.getElementById('w-fatt-inizio').value;
            const pf = document.getElementById('w-fatt-fine').value;
            d.fattInizio = pi ? { anno: Number(pi.slice(0, 4)), mese: Number(pi.slice(5, 7)) } : null;
            d.fattFine = pf ? { anno: Number(pf.slice(0, 4)), mese: Number(pf.slice(5, 7)) } : null;
        }
        d.speseGenerali = document.getElementById('w-spese').checked;
        // percentuale battuta a mano: si accetta sia 7.5 sia 7,5, e non si va oltre il 100%
        d.speseGeneraliPerc = Math.min(100, Math.max(0, parseEuro(document.getElementById('w-spese-perc').value)));
    }

    // eco sotto i campi finestra: con quale periodo parte e con quale finisce
    function ecoFinestra() {
        const d = wizard.dati, per = d.fatturazione || 'annuale';
        const ecoI = document.getElementById('w-fatt-inizio-eco');
        const ecoF = document.getElementById('w-fatt-fine-eco');
        if (!ecoI || !ecoF) return;
        const anni = anniEsercizi();
        if (per === 'specifica' || !anni.length) { ecoI.textContent = ''; ecoF.textContent = ''; return; }
        // Comando il periodo indicato tal quale (nessuno slittamento per scadenze o esercizi
        // a compenso 0); campo vuoto = dal primo / all'ultimo esercizio.
        const ord = anni.slice().sort((a, b) => a - b);
        const inizioP = d.fattInizio || { anno: ord[0], mese: 1 };
        const fineP = d.fattFine || { anno: ord[ord.length - 1], mese: 12 };
        ecoI.textContent = 'Inizia con ' + etichettaPeriodoFatt(inizioP, per) + (d.fattInizio ? '' : ' (senza data di inizio)');
        ecoF.textContent = 'Termina con ' + etichettaPeriodoFatt(fineP, per) + (d.fattFine ? '' : ' (senza data di fine)');
    }

    /* Condizioni da cui nasce il piano: se cambiano (periodicita, finestra, esercizi,
       compenso del passo 3) le righe di prima non valgono piu e vanno rifatte. */
    function firmaPiano() {
        const d = wizard.dati, anni = anniEsercizi(), mappa = compensiRisultanti();
        return [d.fatturazione || '', d.fattData || '',
            d.fattInizio ? d.fattInizio.anno + '/' + d.fattInizio.mese : '',
            d.fattFine ? d.fattFine.anno + '/' + d.fattFine.mese : '',
            anni.join(','), anni.map(a => mappa[a] || 0).join(',')].join('|');
    }

    /* Righe del periodo corrente: quelle gia concordate sull'incarico se sono ancora
       coerenti col compenso, altrimenti la proposta che nasce dalla periodicita.
       Gli esercizi fuori dal periodo (es. quelli del rinnovo precedente) non si toccano. */
    function pianoDelPeriodo(riproponi) {
        const w = wizard, d = w.dati, anni = anniEsercizi(), mappa = compensiRisultanti();
        const base = {
            id: w.idEsistente || 'anteprima', fatturazione: d.fatturazione, compensi: mappa,
            fattData: d.fattData || null, fattInizio: d.fattInizio || null, fattFine: d.fattFine || null
        };
        const proposto = pianoProposto(base, anni);
        const out = {};
        anni.forEach(a => {
            const salvate = (d.piano && Array.isArray(d.piano[a])) ? d.piano[a] : null;
            // il piano salvato vale sempre quanto il compenso salvato: se non torna piu,
            // vuol dire che il compenso e stato rifatto al passo 3 e il piano lo segue
            const coerente = salvate && (mappa[a] == null || Math.abs(totalePiano(salvate) - mappa[a]) < 0.01);
            out[a] = (!riproponi && coerente) ? salvate.map(r => Object.assign({}, r)) : (proposto[a] || []);
        });
        return out;
    }

    // genera il piano solo quando serve davvero (primo ingresso o condizioni cambiate)
    function preparaPianoWizard() {
        const w = wizard, firma = firmaPiano();
        if (w.piano && w.firmaPiano === firma) return;
        const primaVolta = !w.piano && !w.firmaPiano;
        w.piano = pianoDelPeriodo(!primaVolta);
        w.pianoToccato = false;
        w.firmaPiano = firma;
    }

    // periodo aggiunto a mano: cade dopo l'ultimo, con il passo della periodicita
    function nuovaRigaPiano(anno, righe, periodicita) {
        const passo = periodicita === 'mensile' ? 1 : (periodicita === 'trimestrale' ? 3 : 12);
        const ultimo = righe.length ? Number(String(righe[righe.length - 1].scadenza || '').slice(5, 7)) || 0 : 0;
        const mese = Math.min(12, Math.max(1, ultimo ? ultimo + passo : 12));
        const giorno = mese === 2 ? 28 : ([4, 6, 9, 11].includes(mese) ? 30 : 31);
        return {
            id: 'n' + Date.now().toString(36) + Math.random().toString(36).slice(2, 5),
            scadenza: anno + '-' + String(mese).padStart(2, '0') + '-' + giorno, importo: 0, chiave: null
        };
    }

    /* Rinnovo: piano del periodo che si sta chiudendo, in sola lettura. Si legge
       dall'incarico salvato, cosi vale sia per i piani concordati sia per le rate
       automatiche degli incarichi piu vecchi. */
    function pianoPrecedenteRinnovo(anniCorrenti) {
        const prec = wizard.idEsistente ? Incarichi.trova(wizard.idEsistente) : null;
        if (!prec) return [];
        let anni = Array.from(new Set(
            Object.keys(prec.compensi || {}).concat(Object.keys(prec.piano || {})).map(Number)
        )).filter(a => a && !anniCorrenti.includes(a)).sort((a, b) => a - b);
        // solo il periodo che si sta chiudendo: i trienni ancora prima restano
        // consultabili in "Periodi precedenti" sul dettaglio dell'incarico
        const primo = Number(prec.esercizioPeriodo) || null;
        if (primo) {
            const durata = prec.tipo === 'legale' ? 3 : 1;
            anni = anni.filter(a => a >= primo && a < primo + durata);
        }
        return anni.map(anno => ({ anno, rate: Fatture.rate(prec, anno), incarico: prec }));
    }

    /* Selettore di data a tre tendine (giorno / mese / anno) per una scadenza del
       piano: il calendario nativo nasconde l'anno dietro le frecce dei mesi, qui invece
       si sceglie direttamente. L'anno propone il triennio attorno all'esercizio. */
    function cellaDataPiano(anno, idx, scadenza) {
        const d = /^\d{4}-\d{2}-\d{2}$/.test(scadenza || '') ? scadenza : (anno + '-12-31');
        const gg = Number(d.slice(8, 10)), mm = Number(d.slice(5, 7)), aa = Number(d.slice(0, 4));
        const anniOpt = [];
        for (let y = anno - 1; y <= anno + 2; y++) anniOpt.push(y);
        if (!anniOpt.includes(aa)) { anniOpt.push(aa); anniOpt.sort((a, b) => a - b); }
        const optG = Array.from({ length: 31 }, (_, k) => `<option value="${k + 1}" ${k + 1 === gg ? 'selected' : ''}>${k + 1}</option>`).join('');
        const optM = MESI_IT.map((nm, k) => `<option value="${k + 1}" ${k + 1 === mm ? 'selected' : ''}>${nm.charAt(0).toUpperCase() + nm.slice(1)}</option>`).join('');
        const optA = anniOpt.map(y => `<option value="${y}" ${y === aa ? 'selected' : ''}>${y}</option>`).join('');
        return `<span class="pdata" data-anno="${anno}" data-i="${idx}">
            <select class="pdata-g" aria-label="Giorno">${optG}</select>
            <select class="pdata-m" aria-label="Mese">${optM}</select>
            <select class="pdata-a" aria-label="Anno">${optA}</select>
        </span>`;
    }

    function disegnaPianoWizard() {
        const w = wizard, d = w.dati, cont = document.getElementById('w-piano');
        if (!cont) return;
        const anni = anniEsercizi();
        const per = d.fatturazione || 'annuale';
        const perc = spesePerc(d);
        const spese = imp => Math.round((Number(imp) || 0) * perc) / 100;
        const testaAnno = anno => {
            const righe = w.piano[anno] || [];
            const tot = totalePiano(righe);
            const totSpese = Math.round(righe.reduce((s, r) => s + spese(r.importo), 0) * 100) / 100;
            return righe.length + (righe.length === 1 ? ' periodo' : ' periodi') + ' &middot; ' + eurFmt2.format(tot)
                + (perc ? ' + ' + eurFmt2.format(totSpese) + ' di spese generali' : '');
        };
        const bloccoAnno = anno => {
            const righe = w.piano[anno] || [];
            return `<div class="piano-anno">
                <div class="piano-testa"><strong>Esercizio ${anno}</strong><span class="piano-tot" data-anno="${anno}">${testaAnno(anno)}</span></div>
                ${righe.length ? `<div class="tabella-wrap"><table class="dati piano-tab"><thead><tr>
                    <th>Periodo</th><th>Scadenza</th><th class="num">Importo</th>${perc ? '<th class="num">Spese ' + percTesto(perc) + '%</th><th class="num">Totale</th>' : ''}<th></th>
                </tr></thead><tbody>
                ${righe.map((r, i) => {
                const imp = Number(r.importo) || 0;
                return `<tr data-anno="${anno}" data-i="${i}">
                        <td data-label="Periodo">${esc(etichettaRigaPiano(r.scadenza, per, i + 1))}</td>
                        <td data-label="Scadenza">${cellaDataPiano(anno, i, r.scadenza)}</td>
                        <td class="num" data-label="Importo"><span class="piano-imp"><input type="text" inputmode="decimal" class="piano-importo" data-anno="${anno}" data-i="${i}" value="${fmtEuroInput(imp)}" placeholder="0,00"><span class="rimb-eur">&euro;</span></span></td>
                        ${perc ? '<td class="num piano-sp" data-label="Spese">' + eurFmt2.format(spese(imp)) + '</td><td class="num piano-tt" data-label="Totale">' + eurFmt2.format(imp + spese(imp)) + '</td>' : ''}
                        <td data-label=""><button type="button" class="btn btn-sm btn-ghost piano-elimina" data-anno="${anno}" data-i="${i}">Elimina</button></td>
                    </tr>`;
            }).join('')}
                </tbody></table></div>`
                    : `<p class="tabella-vuota">Nessun periodo: l'esercizio ${anno} non verrà fatturato e il suo compenso resta a zero.</p>`}
                <button type="button" class="btn btn-sm btn-secondary piano-aggiungi" data-anno="${anno}">+ Aggiungi periodo</button>
            </div>`;
        };
        const prec = w.modalita === 'rinnovo' ? pianoPrecedenteRinnovo(anni) : [];
        const bloccoPrec = !prec.length ? '' : `<details class="piano-prec" open>
            <summary><strong>Periodo precedente</strong> &middot; ${prec.map(p => p.anno).join(', ')} &middot; ${eurFmt.format(prec.reduce((s, p) => s + p.rate.reduce((t, r) => t + r.importo, 0), 0))}</summary>
            <div class="tabella-wrap"><table class="dati"><thead><tr><th>Esercizio</th><th>Periodo</th><th>Scadenza</th><th class="num">Importo</th><th>Stato</th></tr></thead><tbody>
            ${prec.map(p => (p.rate.length ? p.rate : [null]).map((r, i) => r
                ? `<tr><td data-label="Esercizio">${i === 0 ? p.anno : ''}</td><td data-label="Periodo">${esc(etichettaRigaPiano(r.scadenza, p.incarico.fatturazione || 'annuale', r.numero))}</td><td data-label="Scadenza">${esc(fmtData(r.scadenza))}</td><td class="num" data-label="Importo">${eurFmt2.format(r.importo)}</td><td data-label="Stato"><span class="badge ${r.stato === 'incassata' ? 'verde' : (r.stato === 'emessa' ? 'ambra' : 'neutro')}">${esc(r.stato)}</span></td></tr>`
                : `<tr><td data-label="Esercizio">${p.anno}</td><td colspan="4" class="tabella-vuota">Nessuna scadenza registrata.</td></tr>`).join('')).join('')}
            </tbody></table></div>
            <p class="hint" style="margin-top:8px;">Sola lettura: resta com'è, con i suoi stati di fatturazione, e finisce in "Periodi precedenti" sul dettaglio dell'incarico.</p>
        </details>`;

        cont.innerHTML = `<h3 style="margin-top:20px;">Periodi di fatturazione e importi</h3>
            <p class="descrizione" style="margin-bottom:12px;">Ogni riga è una scadenza: puoi cambiarne la data e l'importo, eliminarla o aggiungerne una. <strong>Il compenso dell'esercizio è la somma delle sue righe</strong>, quindi quello che scrivi qui è quello che finisce in fatturazione, nei report e nella lettera.</p>
            ${bloccoPrec}
            ${anni.map(bloccoAnno).join('')}`;

        const aggiornaTotali = anno => {
            const righe = w.piano[anno] || [];
            cont.querySelectorAll('tr[data-anno="' + anno + '"]').forEach(tr => {
                const imp = Number((righe[Number(tr.dataset.i)] || {}).importo) || 0;
                const sp = tr.querySelector('.piano-sp'), tt = tr.querySelector('.piano-tt');
                if (sp) sp.textContent = eurFmt2.format(spese(imp));
                if (tt) tt.textContent = eurFmt2.format(imp + spese(imp));
            });
            const testa = cont.querySelector('.piano-tot[data-anno="' + anno + '"]');
            if (testa) testa.innerHTML = testaAnno(anno);
        };
        cont.querySelectorAll('.piano-importo').forEach(inp => {
            const applica = () => {
                const anno = inp.dataset.anno, riga = (w.piano[anno] || [])[Number(inp.dataset.i)];
                if (!riga) return;
                riga.importo = parseEuro(inp.value);
                w.pianoToccato = true;
                aggiornaTotali(anno);
            };
            // aggiornamento a ogni battuta (senza ridisegnare, cosi non si perde il campo)
            inp.addEventListener('input', applica);
            inp.addEventListener('change', () => { applica(); inp.value = fmtEuroInput(parseEuro(inp.value)); });
        });
        cont.querySelectorAll('.pdata').forEach(sp => {
            const applica = () => {
                const riga = (w.piano[sp.dataset.anno] || [])[Number(sp.dataset.i)];
                if (!riga) return;
                const gg = Number(sp.querySelector('.pdata-g').value);
                const mm = Number(sp.querySelector('.pdata-m').value);
                const aa = Number(sp.querySelector('.pdata-a').value);
                const ultimo = new Date(aa, mm, 0).getDate();   // giorni del mese scelto
                const giorno = Math.min(gg, ultimo);            // 31 feb -> 28/29
                riga.scadenza = aa + '-' + String(mm).padStart(2, '0') + '-' + String(giorno).padStart(2, '0');
                w.pianoToccato = true;
                disegnaPianoWizard();   // aggiorna etichetta periodo ed eventuale giorno corretto
            };
            sp.querySelectorAll('select').forEach(s => s.addEventListener('change', applica));
        });
        cont.querySelectorAll('.piano-elimina').forEach(b =>
            b.addEventListener('click', () => {
                const righe = w.piano[b.dataset.anno];
                if (!righe) return;
                righe.splice(Number(b.dataset.i), 1);
                w.pianoToccato = true;
                disegnaPianoWizard();
            }));
        cont.querySelectorAll('.piano-aggiungi').forEach(b =>
            b.addEventListener('click', () => {
                const anno = b.dataset.anno;
                const righe = w.piano[anno] || (w.piano[anno] = []);
                righe.push(nuovaRigaPiano(Number(anno), righe, per));
                w.pianoToccato = true;
                disegnaPianoWizard();
            }));
    }

    function disegnaPassoCalcolo(corpo) {
        const w = wizard, c = w.calc;
        // se il calcolo e congelato (solo in modifica): sola lettura
        if (w.modalita === 'modifica' && w.dati.calcoloCongelato) {
            const cong = w.dati.congelamento || {};
            const compenso = w.dati.compensi && w.dati.compensi[anniEsercizi()[0]];
            corpo.innerHTML = `
                <h2>Calcolo del compenso</h2>
                <div class="calc-riquadro" style="border-color:var(--ambra); background:var(--ambra-bg);">
                    <strong>${ICO_LUCCHETTO}Calcolo congelato</strong>
                    <p class="descrizione" style="margin:8px 0;">Il calcolo di questo incarico è stato congelato${cong.il ? ' il ' + fmtDataOra(cong.il) : ''}${cong.da ? ' da ' + esc(cong.da) : ''}. Il compenso concordato non può essere modificato.</p>
                    <div class="calc-riga totale"><span>Compenso concordato (primo esercizio)</span><span class="val">${compenso ? eurFmt.format(compenso) : '-'}</span></div>
                </div>
                <p class="descrizione">Per modificare il calcolo occorre prima sbloccarlo dal dettaglio dell'incarico, inviando un messaggio di allerta al titolare.</p>`;
            w.compensoModificato = false;
            return;
        }
        corpo.innerHTML = `
            <h2>Calcolo del compenso</h2>
            <p class="descrizione" style="margin-bottom:14px;">Metodo della pagina sulla revisione legale: media dimensionale, ore base CNDCEC, correttivi di settore e rischio, tariffa oraria.</p>
            <div class="griglia-2">
                <div class="campo"><label>Totale attivo patrimoniale</label><input id="c-attivo" inputmode="numeric" value="${c.attivo ? numFmt.format(c.attivo) : ''}" placeholder="es. 5.000.000"><div class="imp-eco" id="c-attivo-eco"></div></div>
                <div class="campo"><label>Ricavi delle vendite</label><input id="c-ricavi" inputmode="numeric" value="${c.ricavi ? numFmt.format(c.ricavi) : ''}" placeholder="es. 8.000.000"><div class="imp-eco" id="c-ricavi-eco"></div></div>
                <div class="campo"><label>Settore di attività</label><select id="c-settore">${SETTORI.map(s => `<option value="${s.val}" ${c.moltSettore === s.val ? 'selected' : ''}>${s.nome}</option>`).join('')}</select></div>
                <div class="campo"><label>Rischio incarico</label><select id="c-rischio">${RISCHI.map(s => `<option value="${s.val}" ${c.moltRischio === s.val ? 'selected' : ''}>${s.nome}</option>`).join('')}</select></div>
                <div class="campo"><label>Aumento manuale ore base</label><input id="c-oreplus" type="number" min="0" value="${c.orePlus || 0}"></div>
                <div class="campo hidden" id="c-extra50-box"><label>Ore extra oltre 50 milioni</label><input id="c-extra50" type="number" min="0" value="${c.extra50 || 0}"><div class="hint" id="c-extra50-hint"></div></div>
            </div>
            <h3>Ore extra per casistiche</h3>
            <div class="griglia-3">
                <div class="campo"><label>Consolidato (ricorrente)</label><input id="c-consolidato" type="number" min="0" value="${c.hConsolidato || 0}"></div>
                <div class="campo"><label>IFRS / principi particolari</label><input id="c-ifrs" type="number" min="0" value="${c.hIfrs || 0}"></div>
                <div class="campo"><label>Sistemi IT / Data Analytics</label><input id="c-it" type="number" min="0" value="${c.hIt || 0}"></div>
                <div class="campo"><label>Altro (ricorrente)</label><input id="c-altro" type="number" min="0" value="${c.hAltro || 0}"></div>
                <div class="campo"><label>Rev. volontaria anno prec. (solo anno 1)</label><input id="c-volontaria" type="number" min="0" value="${c.hVolontaria || 0}"></div>
                <div class="campo"><label>Primo anno / subentro (solo anno 1)</label><input id="c-primoanno" type="number" min="0" value="${c.hPrimoAnno || 0}"></div>
            </div>
            <div class="griglia-2">
                <div class="campo"><label>Tariffa oraria media</label><input id="c-tariffa" type="number" min="0" value="${c.tariffa || 85}"><div class="imp-eco" id="c-tariffa-eco"></div><div class="hint">Tariffa media ponderata del team (partner, manager, senior, junior).</div></div>
                <div class="campo"><label>Note sul rischio</label><input id="c-note" value="${esc(c.rischioNote || '')}" placeholder="es. governance, contenziosi, sistemi IT"></div>
            </div>
            <div class="calc-riquadro" id="c-risultato"></div>
            <div class="campo" style="margin-top:10px;">
                <label style="display:flex; align-items:center; gap:8px; font-weight:600;">
                    <input type="checkbox" id="c-manuale" ${w.compensoManuale ? 'checked' : ''} style="width:auto;"> Imposta il compenso annuo manualmente
                </label>
                <input id="c-compenso-manuale" inputmode="numeric" class="${w.compensoManuale ? '' : 'hidden'}" value="${w.compensoManualeValore ? numFmt.format(w.compensoManualeValore) : ''}" placeholder="es. 8.500" style="margin-top:8px;">
                <div class="imp-eco ${w.compensoManuale ? '' : 'hidden'}" id="c-compenso-manuale-eco"></div>
            </div>`;

        /* Eco in euro sotto i campi importo. Mostra il valore che il calcolo sta USANDO, non
           quello che e' stato battuto: chi scrive 5000000 vede subito 5.000.000 euro senza
           contare gli zeri, e se sbaglia a digitare se ne accorge qui. */
        const ecoImporto = (id, valore, suffisso) => {
            const el = document.getElementById(id);
            if (el) el.textContent = valore > 0 ? eurFmt.format(valore) + (suffisso || '') : '';
        };
        const aggiornaEco = () => {
            ecoImporto('c-attivo-eco', w.calc.attivo);
            ecoImporto('c-ricavi-eco', w.calc.ricavi);
            ecoImporto('c-tariffa-eco', w.calc.tariffa, ' all\'ora');
            ecoImporto('c-compenso-manuale-eco', w.compensoManualeValore, ' all\'anno');
        };
        const ricalcola = () => {
            leggiCampiCalcolo();
            aggiornaEco();
            const r = calcolaCompenso(w.calc);
            const box = document.getElementById('c-extra50-box');
            box.classList.toggle('hidden', !r.oltre50M);
            if (r.oltre50M) document.getElementById('c-extra50-hint').textContent =
                'Media oltre 50 milioni: consiglio orientativo +' + Math.round(r.oreCorrette * 0.10) + ' / +' + Math.round(r.oreCorrette * 0.20) + ' ore.';
            const volontaria = wizard.dati.tipo === 'volontaria';
            document.getElementById('c-risultato').innerHTML = `
                <div class="calc-riga"><span>Media dimensionale</span><span class="val">${eurFmt.format(r.media)}</span></div>
                <div class="calc-riga"><span>Ore base CNDCEC</span><span class="val">${numFmt.format(r.oreBase)} h</span></div>
                <div class="calc-riga"><span>Ore base effettive</span><span class="val">${numFmt.format(r.oreBaseEff)} h</span></div>
                <div class="calc-riga"><span>Ore corrette (settore ${w.calc.moltSettore} - rischio ${w.calc.moltRischio})</span><span class="val">${numFmt.format(r.oreLegale)} h</span></div>
                <div class="calc-riga"><span>Ore anno 1 (con extra)</span><span class="val">${numFmt.format(r.oreAnno1)} h</span></div>
                ${volontaria ? '' : `<div class="calc-riga"><span>Ore anni 2 e 3</span><span class="val">${numFmt.format(r.oreAnni23)} h</span></div>`}
                <div class="calc-riga totale"><span>Compenso annuo proposto</span><span class="val">${eurFmt.format(r.compensoAnno1)}</span></div>
                ${volontaria ? '' : `<div class="calc-riga"><span>Compenso anni 2 e 3</span><span class="val">${eurFmt.format(r.compensoAnni23)}</span></div>`}`;
        };
        ['c-attivo', 'c-ricavi', 'c-settore', 'c-rischio', 'c-oreplus', 'c-extra50', 'c-consolidato', 'c-ifrs', 'c-it', 'c-altro', 'c-volontaria', 'c-primoanno', 'c-tariffa', 'c-note'].forEach(id => {
            const el = document.getElementById(id);
            el.addEventListener('input', () => { wizard.compensoModificato = true; ricalcola(); });
        });
        document.getElementById('c-manuale').addEventListener('change', e => {
            wizard.compensoManuale = e.target.checked;
            wizard.compensoModificato = true;
            document.getElementById('c-compenso-manuale').classList.toggle('hidden', !e.target.checked);
            document.getElementById('c-compenso-manuale-eco').classList.toggle('hidden', !e.target.checked);
        });
        // il compenso manuale non passa da ricalcola: qui l'eco va aggiornato a parte
        document.getElementById('c-compenso-manuale').addEventListener('input', () => {
            wizard.compensoModificato = true;
            leggiCampiCalcolo();
            aggiornaEco();
        });
        ricalcola();
    }

    function leggiCampiCalcolo() {
        const c = wizard.calc;
        c.attivo = parseImporto(document.getElementById('c-attivo').value);
        c.ricavi = parseImporto(document.getElementById('c-ricavi').value);
        c.moltSettore = parseFloat(document.getElementById('c-settore').value);
        c.moltRischio = parseFloat(document.getElementById('c-rischio').value);
        c.orePlus = Number(document.getElementById('c-oreplus').value) || 0;
        c.extra50 = Number(document.getElementById('c-extra50').value) || 0;
        c.hConsolidato = Number(document.getElementById('c-consolidato').value) || 0;
        c.hIfrs = Number(document.getElementById('c-ifrs').value) || 0;
        c.hIt = Number(document.getElementById('c-it').value) || 0;
        c.hAltro = Number(document.getElementById('c-altro').value) || 0;
        c.hVolontaria = Number(document.getElementById('c-volontaria').value) || 0;
        c.hPrimoAnno = Number(document.getElementById('c-primoanno').value) || 0;
        c.tariffa = Number(document.getElementById('c-tariffa').value) || 0;
        c.rischioNote = document.getElementById('c-note').value;
        wizard.compensoManualeValore = parseImporto(document.getElementById('c-compenso-manuale').value);
    }

    function compensoAnnuoCorrente() {
        const w = wizard;
        if (w.compensoManuale && w.compensoManualeValore > 0) return w.compensoManualeValore;
        const r = calcolaCompenso(w.calc);
        return Math.round(r.compensoAnno1);
    }

    function anniEsercizi() {
        const w = wizard;
        const e = Number(w.esercizio) || annoCorrente();
        return w.dati.tipo === 'legale' ? [e, e + 1, e + 2] : [e];
    }

    /* Compensi che verranno effettivamente salvati, anno per anno:
       - in modifica senza interventi sul passo 3 restano i valori esistenti;
       - con compenso manuale, lo stesso importo su tutti gli esercizi;
       - altrimenti anno 1 con le ore una tantum, anni 2-3 a regime. */
    function compensiRisultanti() {
        const w = wizard;
        const anni = anniEsercizi();
        const r = calcolaCompenso(w.calc);
        const manuale = w.compensoManuale && w.compensoManualeValore > 0;
        // calcolo congelato: si conservano SOLO i compensi gia concordati,
        // senza fabbricarne di nuovi per anni non coperti
        const congelato = w.modalita === 'modifica' && w.dati.calcoloCongelato;
        const mappa = {};
        anni.forEach((a, idx) => {
            if (!w.compensoModificato && w.dati.compensi && w.dati.compensi[a] != null) {
                mappa[a] = Number(w.dati.compensi[a]);
            } else if (congelato) {
                // non concordato: resta fuori dalla mappa (nessun compenso inventato)
            } else if (manuale) {
                mappa[a] = w.compensoManualeValore;
            } else {
                mappa[a] = Math.round(idx === 0 ? r.compensoAnno1 : r.compensoAnni23);
            }
        });
        return mappa;
    }

    function salvaPassoCorrente(valida) {
        const w = wizard, d = w.dati;
        if (w.passo === 1) {
            d.cliente = document.getElementById('w-cliente').value.trim();
            d.codiceFiscale = document.getElementById('w-cf').value.trim();
            d.regione = document.getElementById('w-regione').value;
            d.email1 = document.getElementById('w-email1').value.trim();
            d.email2 = document.getElementById('w-email2').value.trim();
            d.area = document.getElementById('w-area').value;
            if (valida && !d.cliente) { toast('Inserisci la ragione sociale.', 'rosso'); return false; }
        } else if (w.passo === 2) {
            d.tipo = document.getElementById('w-tipo').value;
            w.esercizio = Number(document.getElementById('w-esercizio').value) || annoCorrente();
            d.dataInizio = document.getElementById('w-inizio').value || null;
            d.dataFine = document.getElementById('w-fine').value || null;
            if (valida && !w.esercizio) { toast('Indica il primo esercizio.', 'rosso'); return false; }
        } else if (w.passo === 3) {
            // calcolo congelato in modifica: nessuna lettura, i compensi restano
            if (!(w.modalita === 'modifica' && d.calcoloCongelato)) {
                leggiCampiCalcolo();
                if (valida) {
                    const mappa = compensiRisultanti();
                    if (Object.values(mappa).some(v => !v || v <= 0)) { toast('Il compenso annuo deve essere maggiore di zero: inserisci attivo e ricavi oppure imposta il compenso manualmente.', 'rosso'); return false; }
                }
            }
        } else if (w.passo === 4) {
            d.respIncarico = document.getElementById('w-resp').value;
            d.qualita = document.getElementById('w-qualita').value;
            d.referente = document.getElementById('w-referente').value;
            d.team = Array.from(document.querySelectorAll('.w-team-check:checked')).map(c => c.value).join(', ');
            if (valida) {
                if (!d.respIncarico || !d.qualita) { toast('Indica responsabile incarico e responsabile qualità.', 'rosso'); return false; }
                if (d.respIncarico === d.qualita) {
                    const err = document.getElementById('w-qualita-errore');
                    // per nuovi incarichi e rinnovi la separazione e obbligatoria;
                    // in modifica di dati preesistenti viene solo segnalata
                    if (w.modalita === 'modifica') {
                        err.textContent = 'Attenzione: il responsabile della qualità coincide con il responsabile dell\'incarico (dato preesistente, valuta di separare i ruoli).';
                        err.classList.remove('hidden');
                    } else {
                        err.textContent = 'Il responsabile della qualità deve essere diverso dal responsabile dell\'incarico.';
                        err.classList.remove('hidden');
                        return false;
                    }
                }
            }
        } else if (w.passo === 5) {
            leggiCampiFatturazione();
            // il piano del periodo corrente entra nell'incarico; gli altri esercizi
            // (es. quelli dei rinnovi precedenti) restano come sono
            if (w.piano) {
                d.piano = Object.assign({}, d.piano || {});
                Object.keys(w.piano).forEach(a => { d.piano[a] = w.piano[a].map(r => Object.assign({}, r)); });
            }
            if (valida) {
                const anni = anniEsercizi();
                const totale = anni.reduce((s, a) => s + totalePiano((w.piano || {})[a]), 0);
                if (totale <= 0) { toast('Il piano di fatturazione è vuoto: aggiungi almeno un periodo con un importo.', 'rosso'); return false; }
                const aZero = anni.filter(a => totalePiano((w.piano || {})[a]) <= 0);
                if (aZero.length) toast('Esercizi senza periodi: ' + aZero.join(', ') + '. Il loro compenso sarà zero.', 'ambra');
            }
        }
        return true;
    }

    // persone presenti nel team salvato dell'incarico ma non piu nel team scelto ora
    // (confronto per persona, cosi un semplice cambio di etichetta non conta come uscita)
    function personeRimosseDalTeam(idEsistente, teamNuovo) {
        const orig = idEsistente ? Incarichi.trova(idEsistente) : null;
        if (!orig) return [];
        const risolvi = risolutorePersone();
        const chiave = v => { const p = risolvi(v); return p ? p.id : '_' + String(v).trim().toLowerCase(); };
        const nuovi = new Set(dividiNomi(teamNuovo).map(chiave));
        const out = [], visti = new Set();
        dividiNomi(orig.team).forEach(v => {
            const k = chiave(v);
            if (nuovi.has(k) || visti.has(k)) return;
            visti.add(k);
            const p = risolvi(v);
            out.push({ etichetta: p ? etichettaPersona(p) : v });
        });
        return out;
    }
    // riepilogo delle persone tolte dal team: chiede fino a quando hanno coperto il ruolo,
    // poi prosegue col salvataggio. Le date finiscono nello storico del team dell'incarico.
    function modaleUscitaTeam(rimossi, onConferma) {
        const oggi = oggiISO();
        const righe = rimossi.map((r, i) => `<div class="campo" style="display:flex;align-items:center;gap:12px;justify-content:space-between;flex-wrap:wrap;">
            <span><strong>${esc(r.etichetta)}</strong></span>
            <label style="display:flex;align-items:center;gap:8px;font-weight:500;">fino al <input type="date" class="u-team-data" data-i="${i}" max="${oggi}" style="max-width:180px;"></label>
        </div>`).join('');
        apriModale(`<h2>Persone tolte dal team</h2>
            <p class="descrizione">Hai tolto ${rimossi.length === 1 ? 'questa persona' : 'queste persone'} dal team di revisione. Indica fino a quando ${rimossi.length === 1 ? 'ha' : 'hanno'} coperto il ruolo (facoltativo): ne resta traccia nello storico dell'incarico.</p>
            ${righe}
            <div class="modale-azioni"><button class="btn btn-ghost" id="m-annulla">Annulla</button><button class="btn btn-primary" id="m-conferma">Conferma e salva</button></div>`, { classe: 'larga', bloccante: true });
        document.getElementById('m-annulla').addEventListener('click', chiudiModale);
        document.getElementById('m-conferma').addEventListener('click', () => {
            const utente = Auth.utenteCorrente;
            const entries = rimossi.map((r, i) => {
                const inp = document.querySelector('.u-team-data[data-i="' + i + '"]');
                return { nome: r.etichetta, al: (inp && inp.value) || null, da: utente ? (utente.nome + ' <' + utente.email + '>') : '', il: Date.now() };
            });
            chiudiModale();
            onConferma(entries);
        });
    }
    /* Controllo completo prima del salvataggio: coi passi cliccabili si puo arrivare
       al Riepilogo saltando un passaggio obbligatorio, quindi si ricontrolla tutto sul
       modello e, se manca qualcosa, si rimanda al passo giusto. */
    function validaTutto() {
        const w = wizard, d = w.dati;
        if (!d.cliente) return { passo: 1, msg: 'Inserisci la ragione sociale.' };
        if (!w.esercizio) return { passo: 2, msg: 'Indica il primo esercizio.' };
        // compenso: dal piano se e stato generato (passo 5), altrimenti dal calcolo (passo 3)
        const anni = anniEsercizi();
        const totalePianoAnni = anni.reduce((s, a) => s + totalePiano((w.piano || {})[a]), 0);
        const compOk = (w.piano && totalePianoAnni > 0) || (!w.piano && Object.values(compensiRisultanti()).some(v => v > 0));
        if (!compOk) return { passo: w.piano ? 5 : 3, msg: 'Il compenso deve essere maggiore di zero: compila il calcolo o il piano di fatturazione.' };
        if (!d.respIncarico || !d.qualita) return { passo: 4, msg: 'Indica responsabile incarico e responsabile qualità.' };
        if (w.modalita !== 'modifica' && d.respIncarico === d.qualita) return { passo: 4, msg: 'Il responsabile della qualità deve essere diverso dal responsabile dell\'incarico.' };
        return null;
    }

    function concludiWizard() {
        const w = wizard, d = w.dati;
        // coi passi liberi, ricontrolla che non manchi nulla e rimanda al passo giusto
        const mancante = validaTutto();
        if (mancante) {
            toast(mancante.msg, 'rosso');
            if (w.passo !== mancante.passo) { salvaPassoCorrente(false); w.passo = mancante.passo; disegnaWizard(); }
            return;
        }
        // il filtro per regione vale anche in scrittura: un ruolo limitato (coordinatore/vice)
        // non puo creare o spostare un incarico fuori dalle sue regioni, altrimenti lo
        // perderebbe subito di vista. Barriera lato programma (come il resto del filtro regione).
        const consentite = Auth.regioniConsentite();
        if (consentite && !consentite.includes(chiaveRegione(d.regione || ''))) {
            toast('Puoi creare o modificare incarichi solo nelle tue regioni.', 'rosso');
            return;
        }
        // conferma esplicita prima di salvare (modifiche / rinnovi / nuovo incarico)
        const testoConf = w.modalita === 'rinnovo' ? 'Confermi il <strong>rinnovo</strong> di questo incarico?'
            : w.modalita === 'modifica' ? 'Confermi le <strong>modifiche</strong> a questo incarico?'
                : 'Salvare il <strong>nuovo incarico</strong>?';
        apriModale(`<h2>Conferma</h2><p>${testoConf}</p>
            <div class="modale-azioni"><button class="btn btn-ghost" id="m-annulla">Annulla</button><button class="btn btn-primary" id="m-conferma">Conferma</button></div>`);
        document.getElementById('m-annulla').addEventListener('click', chiudiModale);
        document.getElementById('m-conferma').addEventListener('click', () => {
            chiudiModale();
            // se qualcuno e uscito dal team, prima si registra la data di fine ruolo, poi si salva
            const rimossi = (w.modalita === 'modifica' || w.modalita === 'rinnovo') ? personeRimosseDalTeam(w.idEsistente, d.team) : [];
            if (rimossi.length) { modaleUscitaTeam(rimossi, entries => { d.teamStorico = (d.teamStorico || []).concat(entries); finalizzaWizard(); }); return; }
            finalizzaWizard();
        });
    }
    /* Gli esercizi FUORI dal periodo che si sta modificando/rinnovando vengono fissati
       come piano con la loro periodicita ORIGINALE: senza questo, cambiare la
       periodicita (in modifica o al rinnovo) riscriverebbe le rate degli anni passati,
       gia magari fatturati. Usa i dati salvati (prec), non quelli nuovi. */
    function congelaAnniFuoriPeriodo(d, prec, anniCorrenti) {
        if (!prec) return;
        const anniPrec = Array.from(new Set(Object.keys(prec.compensi || {}).map(Number)))
            .filter(a => a && !anniCorrenti.includes(a));
        if (!anniPrec.length) return;
        d.piano = Object.assign({}, d.piano || {});
        const senzaPiano = anniPrec.filter(a => !Array.isArray(d.piano[a]) && !Array.isArray((prec.piano || {})[a]));
        const generato = senzaPiano.length ? pianoProposto(prec, senzaPiano) : {};
        anniPrec.forEach(a => {
            if (Array.isArray(d.piano[a])) return;                        // gia fissato in questa sessione
            if (Array.isArray((prec.piano || {})[a])) d.piano[a] = prec.piano[a].map(r => Object.assign({}, r));
            else if (generato[a] && generato[a].length) d.piano[a] = generato[a];
        });
    }

    function finalizzaWizard() {
        const w = wizard, d = w.dati;
        const anni = anniEsercizi();
        const mappa = compensiRisultanti();
        // l'incarico com'era salvato: serve a congelare gli anni fuori periodo con la
        // loro periodicita di prima (in modifica e in rinnovo)
        const prec = w.idEsistente ? Incarichi.trova(w.idEsistente) : null;
        if (w.modalita === 'rinnovo') {
            anni.forEach(a => { d.compensi[a] = mappa[a]; });
        } else {
            const nuovi = {};
            // in modifica conserva gli anni gia presenti fuori dal periodo corrente
            Object.keys(d.compensi || {}).forEach(a => { if (!anni.includes(Number(a))) nuovi[a] = d.compensi[a]; });
            anni.forEach(a => { nuovi[a] = mappa[a]; });
            d.compensi = nuovi;
        }
        congelaAnniFuoriPeriodo(d, prec, anni);
        // il piano di fatturazione comanda: il compenso dell'esercizio e la somma delle
        // sue scadenze, cosi togliere o correggere un periodo si vede subito ovunque
        anni.forEach(a => {
            const righe = d.piano && d.piano[a];
            if (!Array.isArray(righe)) return;
            const tot = totalePiano(righe);
            if (tot > 0) d.compensi[a] = tot; else delete d.compensi[a];
        });
        const r = calcolaCompenso(w.calc);
        d.calc = { ...w.calc, media: r.media, oreAnno1: r.oreAnno1, oreAnni23: r.oreAnni23, compensoAnno1: d.compensi[anni[0]] || mappa[anni[0]] };
        // il periodo corrente dell'incarico, usato dalla lettera
        d.esercizioPeriodo = anni[0];

        const haLettera = d.tipo === 'legale' || d.tipo === 'volontaria';
        if (w.modalita === 'rinnovo') {
            d.rinnovo = d.dataFine;
            // archivia il periodo PRECEDENTE (dati + lettera ricreabile) prima di sovrascrivere.
            // gli anni chiusi sono gia stati fissati come piano da congelaAnniFuoriPeriodo
            if (prec) {
                const pianoPrec = {};
                Object.keys(d.piano || {}).forEach(a => { if (!anni.includes(Number(a))) pianoPrec[a] = d.piano[a]; });
                const snap = {
                    chiuso: { il: Date.now(), da: (Auth.utenteCorrente.nome || Auth.utenteCorrente.email || '') },
                    esercizioPeriodo: prec.esercizioPeriodo || null,
                    tipo: prec.tipo,
                    dataInizio: prec.dataInizio || null,
                    rinnovo: prec.rinnovo || null,
                    dataFine: prec.dataFine || null,
                    compensi: Object.assign({}, prec.compensi || {}),
                    piano: JSON.parse(JSON.stringify(pianoPrec)),
                    speseGenerali: prec.speseGenerali !== false, speseGeneraliPerc: spesePerc(prec),
                    calc: prec.calc ? Object.assign({}, prec.calc) : null,
                    qualita: prec.qualita, respIncarico: prec.respIncarico, referente: prec.referente, team: prec.team,
                    calcoloCongelato: !!prec.calcoloCongelato, congelamento: prec.congelamento || null
                };
                d.storico = (prec.storico || []).concat([snap]);
            }
            // il rinnovo nasce come PROPOSTA: il nuovo periodo non entra in fatturazione/compensi
            // finche' non viene confermato (il periodo precedente, gia' confermato, continua a contare)
            d.stato = 'proposta';
            d.confermato = null;
            d.terminato = null;
            d.dimissioni = null;
            const agg = Incarichi.aggiorna(w.idEsistente, d, Auth.utenteCorrente, 'Rinnovo incarico (proposta)');
            toast(haLettera ? 'Rinnovo salvato come PROPOSTA. Stampa la nuova lettera; il nuovo periodo entra in fatturazione solo quando confermi l\'incarico.' : 'Rinnovo salvato come PROPOSTA: confermalo per farlo entrare in fatturazione e compensi.', 'ambra');
            naviga(haLettera ? 'lettera' : 'dettaglio', { id: agg.id });
        } else if (w.modalita === 'modifica') {
            Incarichi.aggiorna(w.idEsistente, d, Auth.utenteCorrente, 'Modifica incarico');
            if (haLettera) {
                // dopo la modifica si va dritti alla pagina del mandato: cosi si
                // puo ristampare subito il PDF aggiornato (e cambiare la firma)
                toast('Incarico aggiornato: puoi ristampare il mandato.', 'verde');
                naviga('lettera', { id: w.idEsistente });
            } else {
                toast('Incarico aggiornato.', 'verde');
                // torna alla sezione da cui si era partiti (es. Aderenti Revilaw), altrimenti al dettaglio
                tornaOrigine(() => naviga('dettaglio', { id: w.idEsistente }));
            }
        } else {
            // un nuovo incarico nasce come PROPOSTA: va confermato per entrare in fatturazione/compensi
            d.stato = 'proposta';
            d.confermato = null;
            const nuovo = Incarichi.crea(d, Auth.utenteCorrente);
            toast(haLettera ? 'Incarico creato come PROPOSTA. Stampa la lettera; entra in fatturazione solo quando lo confermi.' : 'Incarico creato come PROPOSTA: confermalo per farlo entrare in fatturazione e compensi.', 'ambra');
            naviga(haLettera ? 'lettera' : 'dettaglio', { id: nuovo.id });
        }
    }

    /* =========================================================
       VISTA: FATTURAZIONE
    ========================================================= */
    let annoFatturazione = null;
    let fattTab = ''; // scheda periodicita: 'mensile' | 'trimestrale' | 'annuale' | 'specifica'
    let fattSub = null; // sotto-scheda: mese (1-12) per mensile, trimestre (1-4) per trimestrale; null altrimenti
    let fattAperti = null; // gruppi di fatturazione aperti (Set di nomi); null = predefinito (solo "Senza gruppo")

    function vistaFatturazione() {
        const anni = Incarichi.anniConCompensi();
        if (!annoFatturazione || !anni.includes(annoFatturazione)) {
            annoFatturazione = anni.includes(annoCorrente()) ? annoCorrente() : anni[anni.length - 1];
        }
        $vista().innerHTML = `
            <header>
                <div>
                    <h1>Riepilogo fatturazioni</h1>
                    <p class="descrizione">Piano delle rate per esercizio in base alla periodicità di ogni incarico (annuale, trimestrale o mensile). Gli incarichi in <strong>proposta</strong> non compaiono qui finché non sono confermati.</p>
                </div>
                <div class="header-azioni">
                    <div class="campo" style="margin:0;"><label>Esercizio</label>
                        <select id="f-anno">${anni.map(a => `<option ${a === annoFatturazione ? 'selected' : ''}>${a}</option>`).join('')}</select>
                    </div>
                    <button class="btn btn-secondary" id="btn-esporta-fatt">Esporta CSV</button>
                </div>
            </header>
            <div id="fatturazione-corpo"></div>`;
        document.getElementById('f-anno').addEventListener('change', e => {
            annoFatturazione = Number(e.target.value);
            fattSub = null;
            fattAperti = null;
            disegnaFatturazione();
        });
        document.getElementById('btn-esporta-fatt').addEventListener('click', esportaCsvFatturazione);
        disegnaFatturazione();
    }

    function disegnaFatturazione() {
        const anno = annoFatturazione;
        const rateAll = Fatture.tutteAnno(anno);
        const corpo = document.getElementById('fatturazione-corpo');
        if (!rateAll.length) {
            corpo.innerHTML = '<div class="card tabella-vuota">Nessun compenso registrato per l\'esercizio ' + anno + '.</div>';
            return;
        }
        const puoMod = Auth.puoScrivere('fatturazione');
        const mesi = ['Gen', 'Feb', 'Mar', 'Apr', 'Mag', 'Giu', 'Lug', 'Ago', 'Set', 'Ott', 'Nov', 'Dic'];
        const mesiFull = ['Gennaio', 'Febbraio', 'Marzo', 'Aprile', 'Maggio', 'Giugno', 'Luglio', 'Agosto', 'Settembre', 'Ottobre', 'Novembre', 'Dicembre'];
        // spese generali della rata: percentuale scelta sull'incarico (5% se non indicata)
        const speseRata = r => speseSu(r.importo, r.incarico);

        // KPI e grafico: quadro dell'intero anno (tutte le periodicita)
        const totaleAnno = rateAll.reduce((s, r) => s + r.importo, 0);
        const emesse = rateAll.filter(r => r.stato !== 'da emettere');
        const incassate = rateAll.filter(r => r.stato === 'incassata');
        const perMese = {};
        rateAll.forEach(r => { perMese[r.mese] = (perMese[r.mese] || 0) + r.importo; });

        // schede per periodicita (solo quelle presenti nell'anno)
        const perDi = r => (r.incarico.fatturazione || 'annuale');
        const ordine = ['mensile', 'trimestrale', 'annuale', 'specifica'];
        const etichettaPer = { mensile: 'Mensile', trimestrale: 'Trimestrale', annuale: 'Annuale', specifica: 'Data specifica' };
        const presenti = ordine.filter(p => rateAll.some(r => perDi(r) === p));
        if (!presenti.includes(fattTab)) fattTab = presenti[0];
        let rateTab = rateAll.filter(r => perDi(r) === fattTab);

        // sotto-schede: il mensile si divide in tante finestre quanti sono i mesi, il trimestrale nei trimestri
        let subTabs = '';
        if (fattTab === 'mensile' || fattTab === 'trimestrale') {
            const perMensile = fattTab === 'mensile';
            const subKey = perMensile ? (r => r.mese) : (r => Math.ceil(r.mese / 3));
            const subLabel = perMensile ? (k => mesiFull[k - 1]) : (k => ['Primo', 'Secondo', 'Terzo', 'Quarto'][k - 1] + ' trimestre');
            const subPresenti = Array.from(new Set(rateTab.map(subKey))).sort((a, b) => a - b);
            if (!subPresenti.includes(fattSub)) fattSub = subPresenti[0];
            subTabs = `<div class="tab-dest tab-sub">${subPresenti.map(k => `<button class="tab-btn ${fattSub === k ? 'attivo' : ''}" data-fattsub="${k}">${subLabel(k)} (${rateTab.filter(r => subKey(r) === k).length})</button>`).join('')}</div>`;
            rateTab = rateTab.filter(r => subKey(r) === fattSub);
        } else {
            fattSub = null;
        }

        // raggruppa per gruppo di fatturazione (vuoto = "Senza gruppo")
        const perGruppo = {};
        rateTab.forEach(r => {
            const key = (r.incarico.gruppoFatturazione && r.incarico.gruppoFatturazione.trim()) || '';
            (perGruppo[key] || (perGruppo[key] = { nome: key, rate: [] })).rate.push(r);
        });
        const gruppi = Object.values(perGruppo).sort((a, b) => (a.nome ? 0 : 1) - (b.nome ? 0 : 1) || a.nome.localeCompare(b.nome));

        const rigaRata = r => {
            const rb = Fatture.rimborso(r.chiave);
            const base = r.importo + speseRata(r); // importo + spese generali (parte fissa del totale)
            return `<tr>
                <td class="cliente-cella" data-label="Cliente"><span class="link-incarico" data-apri="${esc(r.incarico.id)}">${esc(r.incarico.cliente)}</span></td>
                <td data-label="Rata">${r.numero} di ${r.totale}</td>
                <td data-label="Mese">${mesi[r.mese - 1]}</td>
                <td class="num" data-label="Importo">${eurFmt2.format(r.importo)}</td>
                <td class="num" data-label="Spese generali" title="${spesePerc(r.incarico) ? percTesto(spesePerc(r.incarico)) + '% degli onorari' : 'non addebitate su questo incarico'}">${eurFmt2.format(speseRata(r))}</td>
                <td data-label="Rimborsi spese"><span class="rimb-campo">
                    <input type="text" inputmode="decimal" class="rimb-input" data-chiave="${esc(r.chiave)}" data-cliente="${esc(r.incarico.cliente)}" data-imp="${rb.importo || 0}" value="${fmtEuroInput(rb.importo)}" ${rb.congelato || !puoMod ? 'disabled' : ''} placeholder="0,00"><span class="rimb-eur">&euro;</span>
                    ${puoMod ? `<button type="button" class="btn btn-sm btn-ghost rimb-lock" data-chiave="${esc(r.chiave)}" data-cliente="${esc(r.incarico.cliente)}" data-cong="${rb.congelato ? '1' : '0'}" title="${rb.congelato ? 'Campo congelato: clicca per sbloccare' : 'Congela il campo'}">${rb.congelato ? ICO_LUCCHETTO + 'Sblocca' : 'Congela'}</button>` : ''}
                </span></td>
                <td class="num fatt-tot-riga" data-base="${base}" data-label="Totale">${eurFmt2.format(base + rb.importo)}</td>
                <td data-label="Stato">${puoMod ? `<select class="stato-rata" data-chiave="${esc(r.chiave)}" data-cliente="${esc(r.incarico.cliente)}" style="padding:4px 8px; border-radius:6px; border:1px solid var(--grigio-200); font-size:0.8rem;">
                    <option value="da emettere" ${r.stato === 'da emettere' ? 'selected' : ''}>da emettere</option>
                    <option value="emessa" ${r.stato === 'emessa' ? 'selected' : ''}>emessa</option>
                    <option value="incassata" ${r.stato === 'incassata' ? 'selected' : ''}>incassata</option>
                </select>` : `<span class="badge ${r.stato === 'incassata' ? 'verde' : (r.stato === 'emessa' ? 'ambra' : 'neutro')}">${esc(r.stato)}</span>`}</td>
            </tr>`;
        };
        const sezGruppo = g => {
            const tImp = g.rate.reduce((s, r) => s + r.importo, 0);
            const t5 = g.rate.reduce((s, r) => s + speseRata(r), 0); // somma delle spese di riga (riconcilia col Totale)
            const tRimb = g.rate.reduce((s, r) => s + Fatture.rimborso(r.chiave).importo, 0);
            const tTot = tImp + t5 + tRimb;
            const nClienti = new Set(g.rate.map(r => r.incarico.id)).size;
            const nEmesse = g.rate.filter(r => r.stato !== 'da emettere').length;
            const aperto = fattAperti ? fattAperti.has(g.nome) : !g.nome;
            return `<details class="fatt-gruppo" data-gruppo="${esc(g.nome)}"${aperto ? ' open' : ''}>
                <summary class="fatt-gruppo-sommario">
                    <span class="fatt-gruppo-nome">${g.nome ? esc(g.nome) : '<em>Senza gruppo</em>'}</span>
                    <span class="fatt-gruppo-meta">${nClienti} client${nClienti === 1 ? 'e' : 'i'} &middot; ${g.rate.length} rate</span>
                    <span class="fatt-gruppo-imp">${eurFmt2.format(tTot)}</span>
                    <span class="badge ${nEmesse === g.rate.length ? 'verde' : 'neutro'}">${nEmesse}/${g.rate.length} emesse</span>
                </summary>
                <div class="fatt-gruppo-corpo">
                    <div class="tabella-wrap"><table class="dati a-schede"><thead><tr>
                        <th>Cliente</th><th>Rata</th><th>Mese</th><th class="num">Importo</th><th class="num" title="Spese generali forfettarie, con la percentuale indicata sull'incarico">Spese gen.</th><th>Rimborsi spese</th><th class="num" title="Importo + spese generali + rimborsi">Totale</th><th>Stato</th>
                    </tr></thead><tbody>${g.rate.map(rigaRata).join('')}</tbody>
                    <tfoot><tr><td colspan="3">Totale gruppo</td><td class="num" data-label="Importi">${eurFmt2.format(tImp)}</td><td class="num" data-label="Spese gen.">${eurFmt2.format(t5)}</td><td class="num fatt-tot-rimb" data-label="Rimborsi">${eurFmt2.format(tRimb)}</td><td class="num fatt-tot-tot" data-label="Totale">${eurFmt2.format(tTot)}</td><td></td></tr></tfoot></table></div>
                </div>
            </details>`;
        };
        const tabs = `<div class="tab-dest" style="margin-bottom:16px;">${presenti.map(p => `<button class="tab-btn ${fattTab === p ? 'attivo' : ''}" data-fatttab="${p}">${etichettaPer[p]} (${rateAll.filter(r => perDi(r) === p).length})</button>`).join('')}</div>`;

        corpo.innerHTML = `
            <div class="kpi-griglia">
                <div class="kpi"><div class="etichetta">Da fatturare ${anno}</div><div class="valore">${eurFmt.format(totaleAnno)}</div><div class="nota">${rateAll.length} rate totali</div></div>
                <div class="kpi verde"><div class="etichetta">Rate emesse</div><div class="valore">${emesse.length} / ${rateAll.length}</div><div class="nota">${eurFmt.format(emesse.reduce((s, r) => s + r.importo, 0))}</div></div>
                <div class="kpi ambra"><div class="etichetta">Rate incassate</div><div class="valore">${incassate.length}</div><div class="nota">${eurFmt.format(incassate.reduce((s, r) => s + r.importo, 0))}</div></div>
            </div>
            <div class="card">
                <h2>Distribuzione per mese</h2>
                <div class="grafico-wrap"><canvas id="grafico-mesi" height="200"></canvas></div>
            </div>
            <div class="card">
                <h2>Dettaglio rate ${anno}</h2>
                <p class="hint" style="margin:-6px 0 12px;">Rate divise per periodicità (schede); il mensile e il trimestrale si dividono a loro volta in una finestra per ogni mese/trimestre. In ogni finestra gli incarichi sono raggruppati per gruppo di fatturazione: clicca un gruppo per vedere i singoli clienti; clicca il nome del cliente per aprire l'incarico. Le scadenze e gli importi arrivano dal piano concordato sull'incarico (passo Fatturazione del wizard). Colonna Spese gen. con la percentuale scelta sull'incarico, Totale = importo + spese generali + rimborsi; i rimborsi delle spese vive (in euro) si inseriscono qui e si possono congelare/sbloccare per campo.</p>
                ${tabs}
                ${subTabs}
                ${gruppi.length ? '<div class="fatt-gruppi">' + gruppi.map(sezGruppo).join('') + '</div>' : '<p class="tabella-vuota">Nessuna rata per questa finestra.</p>'}
            </div>`;

        corpo.querySelectorAll('[data-fatttab]').forEach(b => b.addEventListener('click', () => { fattTab = b.dataset.fatttab; fattSub = null; fattAperti = null; disegnaFatturazione(); }));
        corpo.querySelectorAll('[data-fattsub]').forEach(b => b.addEventListener('click', () => { fattSub = Number(b.dataset.fattsub); fattAperti = null; disegnaFatturazione(); }));
        corpo.querySelectorAll('.fatt-gruppo').forEach(d => d.addEventListener('toggle', () => {
            fattAperti = new Set(Array.from(corpo.querySelectorAll('.fatt-gruppo')).filter(x => x.open).map(x => x.dataset.gruppo));
        }));
        corpo.querySelectorAll('.link-incarico[data-apri]').forEach(el => el.addEventListener('click', () => naviga('dettaglio', { id: el.dataset.apri })));
        corpo.querySelectorAll('.stato-rata').forEach(sel =>
            sel.addEventListener('change', () => {
                Fatture.cambiaStato(sel.dataset.chiave, sel.value, Auth.utenteCorrente, sel.dataset.cliente);
                toast('Stato rata aggiornato.', 'verde');
                disegnaFatturazione();
            }));
        corpo.querySelectorAll('.rimb-input').forEach(inp =>
            inp.addEventListener('change', () => {
                const val = parseEuro(inp.value);
                if (Fatture.salvaRimborso(inp.dataset.chiave, val, Auth.utenteCorrente, inp.dataset.cliente)) {
                    toast('Rimborso spese salvato.', 'verde');
                    inp.value = fmtEuroInput(val);
                    inp.dataset.imp = val;
                    // aggiorna i totali (riga e gruppo) SENZA ridisegnare: un redraw stacchererebbe il
                    // pulsante Congela prima del mouseup, "ingoiando" il click se si scrive e si congela di seguito
                    const tr = inp.closest('tr');
                    const cellRiga = tr && tr.querySelector('.fatt-tot-riga');
                    if (cellRiga) cellRiga.textContent = eurFmt2.format((Number(cellRiga.dataset.base) || 0) + val);
                    const gr = inp.closest('.fatt-gruppo');
                    if (gr) {
                        let tRimb = 0, tTot = 0;
                        gr.querySelectorAll('.rimb-input').forEach(x => { tRimb += Number(x.dataset.imp) || 0; });
                        gr.querySelectorAll('.fatt-tot-riga').forEach(c => { tTot += Number(c.dataset.base) || 0; });
                        tTot += tRimb;
                        const cr = gr.querySelector('.fatt-tot-rimb'); if (cr) cr.textContent = eurFmt2.format(tRimb);
                        const ct = gr.querySelector('.fatt-tot-tot'); if (ct) ct.textContent = eurFmt2.format(tTot);
                        const ch = gr.querySelector('.fatt-gruppo-imp'); if (ch) ch.textContent = eurFmt2.format(tTot); // totale in intestazione del gruppo
                    }
                }
            }));
        corpo.querySelectorAll('.rimb-lock').forEach(b =>
            b.addEventListener('click', () => {
                const cong = b.dataset.cong === '1';
                Fatture.congelaRimborso(b.dataset.chiave, !cong, Auth.utenteCorrente, b.dataset.cliente);
                toast(cong ? 'Campo rimborsi sbloccato.' : 'Campo rimborsi congelato.', 'verde');
                disegnaFatturazione();
            }));
        disegnaGraficoBarre('grafico-mesi', mesi, mesi.map((m, i) => perMese[i + 1] || 0));
    }

    function esportaCsvFatturazione() {
        const anno = annoFatturazione;
        const rate = Fatture.tutteAnno(anno);
        const mesi = ['Gen', 'Feb', 'Mar', 'Apr', 'Mag', 'Giu', 'Lug', 'Ago', 'Set', 'Ott', 'Nov', 'Dic'];
        const righe = [['Cliente', 'Gruppo di fatturazione', 'Periodicità', 'Rata', 'Mese', 'Scadenza', 'Importo', 'Spese generali', '% spese', 'Rimborsi spese', 'Totale', 'Stato']];
        rate.forEach(r => {
            const rb = Fatture.rimborso(r.chiave);
            const spese = speseSu(r.importo, r.incarico);
            righe.push([r.incarico.cliente, r.incarico.gruppoFatturazione || '', r.incarico.fatturazione || 'annuale',
                r.numero + ' di ' + r.totale, mesi[r.mese - 1], fmtData(r.scadenza), r.importo, spese, percTesto(spesePerc(r.incarico)),
                rb.importo || 0, r.importo + spese + (rb.importo || 0), r.stato]);
        });
        const csv = righe.map(r => r.map(v => {
            let s = String(v).replace(/"/g, '""');
            if (/^[=+\-@\t\r]/.test(s)) s = "'" + s;
            return '"' + s + '"';
        }).join(';')).join('\r\n');
        const blob = new Blob(['﻿' + csv], { type: 'text/csv;charset=utf-8' });
        const a = document.createElement('a');
        a.href = URL.createObjectURL(blob);
        a.download = 'fatturazione_' + anno + '_' + oggiISO() + '.csv';
        a.click();
        URL.revokeObjectURL(a.href);
        Audit.registra(Auth.utenteCorrente, 'Esportazione CSV fatturazione', 'sistema', null, null, null);
    }

    /* =========================================================
       VISTA: REPORT COMPENSI
    ========================================================= */
    let filtriReport = { anno: null };
    function vistaReport() {
        const incarichi = Incarichi.visibili();
        const anni = Incarichi.anniConCompensi();
        // anno di riferimento della schermata (selettore): default = anno corrente se presente, altrimenti l'ultimo
        const annoDefault = anni.includes(annoCorrente()) ? annoCorrente() : anni[anni.length - 1];
        const annoRif = (filtriReport.anno && anni.includes(filtriReport.anno)) ? filtriReport.anno : annoDefault;
        // compensoContabile esclude le proposte (per il loro periodo non ancora confermato)
        const elencoClienti = incarichi
            .map(i => ({ cliente: i.cliente, id: i.id, importo: compensoContabile(i, annoRif) }))
            .filter(x => x.importo > 0)
            .sort((a, b) => b.importo - a.importo);
        const totaleAnno = elencoClienti.reduce((s, x) => s + x.importo, 0);
        // confronto con l'anno prima: si mostra solo se quell'anno esiste e non era a zero
        const totalePrec = incarichi.reduce((s, i) => s + compensoContabile(i, annoRif - 1), 0);
        const variazione = totalePrec > 0 ? (totaleAnno - totalePrec) / totalePrec * 100 : null;

        /* Compenso rispetto alle ore stimate. Le ore arrivano dal calcolo CNDCEC (attivo+ricavi):
           dove non e' compilato non sono stimabili, e l'incarico non puo' entrare nel grafico:
           va detto, non nascosto. */
        const oreTutti = incarichi.map(i => ({
            id: i.id, cliente: i.cliente, tipo: i.tipo,
            ore: oreStimatePerAnno(i, annoRif), compenso: compensoContabile(i, annoRif)
        }));
        const oreDati = oreTutti.filter(x => x.ore > 0 && x.compenso > 0)
            .map(x => Object.assign(x, { eurH: x.compenso / x.ore }));
        const senzaOre = oreTutti.filter(x => x.compenso > 0 && !(x.ore > 0)).length;
        /* Tariffa di riferimento = mediana dello studio. Con pochi incarichi la mediana e' se
           stessa: un incarico verrebbe confrontato con il proprio compenso e risulterebbe sempre
           "in linea". Sotto la soglia si mostrano i punti senza dare giudizi. */
        const MIN_CONFRONTO = 5;
        const ordEurH = oreDati.map(x => x.eurH).sort((a, b) => a - b);
        const confrontabile = ordEurH.length >= MIN_CONFRONTO;
        const tariffaRif = confrontabile
            ? (ordEurH.length % 2 ? ordEurH[(ordEurH.length - 1) / 2]
                : (ordEurH[ordEurH.length / 2 - 1] + ordEurH[ordEurH.length / 2]) / 2)
            : 0;
        const peggiori = oreDati.slice().sort((a, b) => a.eurH - b.eurH);
        // meta' degli incarichi sta sotto la mediana per definizione: non e' una notizia.
        // Il segnale vero e' chi sta molto sotto, quindi si contano quelli sotto il 70%.
        const moltoSotto = confrontabile ? oreDati.filter(x => x.eurH < tariffaRif * 0.7).length : 0;

        $vista().innerHTML = `
            <header>
                <div>
                    <h1>Report compensi</h1>
                    <p class="descrizione">Compensi per cliente e rapporto tra compenso e ore stimate. Scegli l'anno di riferimento.</p>
                </div>
                <div class="header-azioni">
                    <label style="display:flex;align-items:center;gap:8px;font-size:0.85rem;color:var(--grigio-600);white-space:nowrap;">Anno di riferimento
                        <select id="f-anno-report" style="width:auto;">${anni.map(a => '<option value="' + a + '"' + (a === annoRif ? ' selected' : '') + '>' + a + '</option>').join('')}</select>
                    </label>
                    <button class="btn btn-secondary" id="btn-stampa-report">Stampa report</button>
                </div>
            </header>
            <div class="intest-stampa">
                <div class="is-marchio">Revilaw S.p.A.</div>
                <div class="is-tit">Report compensi ${annoRif}</div>
                <div class="is-meta">${elencoClienti.length} clienti con compenso &middot; totale ${eurFmt.format(totaleAnno)} &middot; stampato il ${fmtData(oggiISO())}</div>
            </div>
            <div class="kpi-griglia">
                <div class="kpi">
                    <div class="etichetta">Totale compensi ${annoRif}</div>
                    <div class="valore">${eurFmt.format(totaleAnno)}</div>
                    <div class="nota">${elencoClienti.length} ${elencoClienti.length === 1 ? 'cliente' : 'clienti'} con compenso</div>
                </div>
                <div class="kpi">
                    <div class="etichetta">Media per cliente</div>
                    <div class="valore">${elencoClienti.length ? eurFmt.format(totaleAnno / elencoClienti.length) : '-'}</div>
                    <div class="nota">${elencoClienti.length ? 'il più alto è ' + eurFmt.format(elencoClienti[0].importo) : ''}</div>
                </div>
                ${variazione == null ? '' : `<div class="kpi ${variazione >= 0 ? 'verde' : 'rosso'}">
                    <div class="etichetta">Rispetto al ${annoRif - 1}</div>
                    <div class="valore">${variazione >= 0 ? '+' : ''}${variazione.toFixed(1)}%</div>
                    <div class="nota">${eurFmt.format(totalePrec)} nel ${annoRif - 1}</div>
                </div>`}
            </div>
            <div class="card">
                <h2>Primi clienti per compenso ${annoRif}</h2>
                <p class="hint" style="margin:-6px 0 10px;">Passa sopra una barra per il dettaglio; clicca per aprire l'incarico.</p>
                <div id="grafico-clienti"></div>
            </div>
            <div class="card">
                <h2>Compenso rispetto alle ore stimate ${annoRif}</h2>
                <p class="hint" style="margin:-6px 0 10px;">Ogni punto è un incarico: a destra chi costa più ore, in alto chi rende di più. Chi sta <strong>sotto la retta</strong> è pagato poco per le ore che assorbe. Passa sopra un punto per il dettaglio; clicca per aprire l'incarico.</p>
                ${oreDati.length ? `<div class="ore-sintesi">
                    <div class="ore-box"><span class="ore-n">${oreDati.length}</span><span class="ore-et">incarichi con ore stimate</span></div>
                    ${confrontabile ? `<div class="ore-box"><span class="ore-n">${eurFmt.format(Math.round(tariffaRif))}</span><span class="ore-et">tariffa mediana per ora</span></div>
                    <div class="ore-box ${moltoSotto ? 'ore-box-att' : ''}"><span class="ore-n">${moltoSotto}</span><span class="ore-et">sotto il 70% della mediana</span></div>` : ''}
                </div>` : ''}
                ${oreDati.length && !confrontabile ? `<div class="ore-avviso">
                    Solo ${oreDati.length} ${oreDati.length === 1 ? 'incarico ha' : 'incarichi hanno'} le ore stimate: troppo pochi per dire cosa è alto e cosa è basso.
                    I punti sono mostrati senza giudizio; servono almeno ${MIN_CONFRONTO} incarichi perché il confronto con la mediana abbia senso.
                </div>` : ''}
                <div id="grafico-ore-compenso"></div>
                ${senzaOre ? `<div class="ore-avviso">
                    <strong>${senzaOre} incarichi con compenso nel ${annoRif} non hanno le ore stimate</strong> e restano fuori dal grafico.
                    Le ore si ricavano dal metodo CNDCEC a partire da <strong>totale attivo</strong> e <strong>ricavi</strong>: compilali nel calcolo del compenso dentro l'incarico${Auth.eProprietario() ? `,
                    oppure caricali per tutti in una volta da <em>Dati e backup &rarr; Importa incarichi &rarr; Aggiorna la stima delle ore dai bilanci</em>` : ''}.
                </div>` : ''}
                ${peggiori.length ? `<h3 style="margin:16px 0 6px;font-size:0.95rem;">Compenso più basso per ora</h3>
                <div class="tabella-wrap"><table class="dati"><thead><tr>
                    <th>Cliente</th><th class="num">Ore stimate</th><th class="num">Compenso ${annoRif}</th><th class="num">Per ora</th>${confrontabile ? '<th class="num">Rispetto alla mediana</th>' : ''}
                </tr></thead><tbody>` +
                peggiori.map(p => {
                    const scarto = confrontabile ? (p.eurH - tariffaRif) / tariffaRif * 100 : 0;
                    return `<tr class="cliccabile" data-apri="${esc(p.id)}">
                        <td class="cliente-cella">${esc(p.cliente)}</td>
                        <td class="num">${numFmt.format(p.ore)} h</td>
                        <td class="num">${eurFmt.format(p.compenso)}</td>
                        <td class="num"><strong>${eurFmt.format(Math.round(p.eurH))}</strong></td>
                        ${confrontabile ? `<td class="num"><span class="badge ${scarto < -30 ? 'rosso' : (scarto < 0 ? 'ambra' : 'verde')}">${scarto >= 0 ? '+' : ''}${scarto.toFixed(0)}%</span></td>` : ''}
                    </tr>`;
                }).join('') + `</tbody></table></div>` : ''}
            </div>
            <div class="card">
                <h2>Compensi per cliente ${annoRif}</h2>
                <p class="hint" style="margin:-6px 0 12px;">${elencoClienti.length} clienti con compenso nel ${annoRif} · totale ${eurFmt.format(totaleAnno)}</p>
                <div class="tabella-wrap"><table class="dati"><thead><tr><th>Cliente</th><th class="num">Compenso ${annoRif}</th></tr></thead><tbody>` +
            elencoClienti.map(t => `<tr class="cliccabile" data-apri="${t.id}"><td class="cliente-cella">${esc(t.cliente)}</td><td class="num">${eurFmt.format(t.importo)}</td></tr>`).join('') +
            `</tbody></table></div>
            </div>`;

        const selAnno = document.getElementById('f-anno-report');
        if (selAnno) selAnno.addEventListener('change', () => { filtriReport.anno = Number(selAnno.value); vistaReport(); });
        document.getElementById('btn-stampa-report').addEventListener('click', () => window.print());
        $vista().querySelectorAll('[data-apri]').forEach(r =>
            r.addEventListener('click', () => naviga('dettaglio', { id: r.dataset.apri })));
        // ogni tabella del report ha ricerca testuale + export CSV
        $vista().querySelectorAll('.card table.dati').forEach(tab => {
            const h2 = tab.closest('.card') && tab.closest('.card').querySelector('h2');
            const nome = h2 ? h2.textContent.trim().toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '').slice(0, 40) : 'report';
            attrezzaTabella(tab, { filtri: false, ricerca: true, nomeFile: 'report-' + nome });
        });
        disegnaGraficoClientiSvg('grafico-clienti', elencoClienti, annoRif);
        disegnaGraficoOreCompensoSvg('grafico-ore-compenso', oreDati, tariffaRif, annoRif);
    }

